	{{"complete", 982, at = {1439, 38.24, 28.8}}, {"complete", 1138, at = {1439, 44.76, 21.8}}, note = "Two wrecks lie on the sea floor in the bay north of Auberdine; each holds a lockbox. Reef Crawlers and Encrusted Tide Crawlers line this shore.", title = "The bay wrecks"},
