	{{"turnin", 965, at = {1439, 54.97, 24.89}, who = "Balthule Shadowstrike"}, {"accept", 966, at = {1439, 54.97, 24.89}, who = "Balthule Shadowstrike"}, {"complete", 966, at = {1439, 55.75, 25.91}}, {"turnin", 966, at = {1439, 54.97, 24.89}, who = "Balthule Shadowstrike"}, {"accept", 967, at = {1439, 54.97, 24.89}, who = "Balthule Shadowstrike"}, note = "Balthule Shadowstrike hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in Ashenvale.", title = "The Tower of Althalaxx"},
	{{"have", 12343, 1, at = {1439, 51.83, 33.5}, name = "Blackwood Nut Sample"}, {"have", 12341, 1, at = {1439, 52.86, 33.42}, name = "Blackwood Fruit Sample"}, {"have", 12342, 1, at = {1439, 50.66, 34.94}, name = "Blackwood Grain Sample"}, {"complete", 4763, at = {1439, 52.5, 33.4}}, note = "The furbolg camp south of the Cliffspring River keeps its Nut, Fruit and Grain Stores by the bonfires. With a sample of each and the Filled Cleansing Bowl in your bags (the Empty Cleansing Bowl is filled at the Auberdine Moonwell), use the bowl by the bonfire closest to the river: it summons Xabraxxis, the satyr corruptor, and the Talisman of Corruption lies in his Demon Bag.", title = "The northern Blackwood camp"},
	{{"complete", 947, at = {1439, 55.04, 33.34}}, {"complete", 2139, at = {1439, 51.48, 38.26}}, note = "The cave lies south of the falls: Scaber Stalks grow all through it, the Death Cap at the very back. The Den Mother lairs in the hills south of the falls.", title = "The cave and the Den Mother"},
	{{"note", "Hearth to Auberdine"}, {"accept", 729, at = {1439, 37.44, 41.84}, who = "Archaeologist Hollee"}, {"turnin", 2139, at = {1439, 38.84, 43.42}, who = "Tharnariun Treetender"}, {"turnin", 947, at = {1439, 37.32, 43.64}, who = "Barithras Moonshade"}, {"accept", 948, at = {1439, 37.32, 43.64}, who = "Barithras Moonshade"}, {"turnin", 982, at = {1439, 38.11, 41.17}, who = "Gorbold Steelhand"}, {"turnin", 4763, at = {1439, 37.4, 40.13}, who = "Thundris Windweaver"}, {"turnin", 1138, at = {1439, 36.1, 44.93}, who = "Gubber Blump"}, {"note", "Sell and repair"}, title = "Hearth to Auberdine"},
	{{"complete", 6123, at = {1439, 43.21, 45.77}}, note = "The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of Auberdine; the moonkin there are irritable. Earthroot needs Herbalism: herbalists pick it all over Darkshore, anyone else brings it from Stormwind (Maria Lumere) or the Auction House.", only = {classes = {"DRUID"}, races = {"NightElf"}}, title = "Lunar Fungus and Earthroot"},
	{{"turnin", 948, at = {1439, 43.55, 76.29}, who = "Onu"}, {"accept", 944, at = {1439, 43.55, 76.29}, who = "Onu"}, {"accept", 98013, at = {1439, 43.71, 76.49}, who = "Arbal"}, {"accept", 5321, at = {1439, 44.4, 76.43}, who = "Kerlonian Evershade"}, note = "Follow the road south. Onu is the ancient at the Grove; Arbal and Kerlonian Evershade sleep beside him.", title = "The Grove of the Ancients"},
	{{"complete", 986, at = {1439, 43.98, 79.96}}, {"complete", 944}, {"turnin", 944, at = {1439, 38.6, 86.2}, who = "Scrying Bowl"}, {"accept", 949, at = {1439, 38.6, 86.2}, who = "Scrying Bowl"}, {"turnin", 949, at = {1439, 38.54, 86.05}, who = "Twilight Tome"}, {"accept", 950, at = {1439, 38.54, 86.05}, who = "Twilight Tome"}, {"accept", 98042, at = {1439, 38.54, 86.05}, who = "Twilight Tome"}, {"complete", 98042, at = {1439, 38.47, 86.09}}, {"accept", 968, optional = true}, {"accept", 945, at = {1439, 38.64, 87.33}, who = "Therylune"}, {"complete", 945}, note = "Moonstalker Sires prowl the woods around the glaive. The Scrying Bowl and the Twilight Tome sit at the bottom of the crater; Therylune stands on its north side.", title = "The Master's Glaive"},
	{{"complete", 4740, at = {1439, 36.44, 76.51}}, {"accept", 4731, at = {1439, 31.67, 83.68}, who = "Beached Sea Turtle"}, {"accept", 4732, at = {1439, 31.23, 85.6}, who = "Beached Sea Turtle"}, {"accept", 4733, at = {1439, 31.26, 87.44}, who = "Beached Sea Creature"}, note = "Murkdeep camps on the beach west of the glaive: kill the murlocs at the camp fire; he comes in the third wave with his hound. Three beached remains lie on the beaches west and south-west of Remtravel's Excavation.", title = "Murkdeep's beach"},
	{{"turnin", 729, at = {1439, 35.73, 83.7}, who = "Prospector Remtravel"}, {"accept", 731, at = {1439, 35.73, 83.7}, who = "Prospector Remtravel"}, {"complete", 731}, note = "Remtravel's Excavation lies on the coast south of Murkdeep's beach. Protect the prospector while he searches for the fossil.", title = "Prospector Remtravel"},
