	{{"note", "Hearth to Auberdine"}, {"turnin", 87760, at = {1439, 36.62, 45.59}, who = "Gwennyth Bly'Leggonde"}, {"turnin", 951, at = {1439, 43.55, 76.29}, who = "Onu"}, {"turnin", 98013, at = {1439, 43.71, 76.49}, who = "Arbal"}, title = "Back south"},
