	{{"note", "Fly to Rut'theran Village", only = {races = {"NightElf"}}}, {"goto", 1438, 58.4, 94.02, "Get the flight path at Rut'theran Village", only = {races = {"Skyborne"}}}, {"accept", 98393, at = {1457, 35.37, 8.4}, who = "Mathrengyl Bearwalker"}, note = "Night Elves fly from Auberdine to Rut'theran Village; Skyborne take the boat from the Auberdine dock and learn the Rut'theran flight path there. Take the portal up to Mathrengyl Bearwalker in the Cenarion Enclave.", only = {classes = {"DRUID"}}, title = "The Great Cat Spirit"},
	{{"turnin", 98393, at = {1450, 56.21, 30.64}, who = "Dendrite Starblaze"}, {"accept", 98394, at = {1450, 56.21, 30.64}, only = {races = {"NightElf"}}, who = "Dendrite Starblaze"}, {"turnin", 6124, at = {1450, 56.21, 30.64}, only = {races = {"NightElf"}}, who = "Dendrite Starblaze"}, {"accept", 6125, at = {1450, 56.21, 30.64}, only = {races = {"NightElf"}}, who = "Dendrite Starblaze"}, {"accept", 98341, at = {1450, 56.21, 30.64}, only = {races = {"Skyborne"}}, who = "Dendrite Starblaze"}, {"turnin", 94914, at = {1450, 56.21, 30.64}, only = {races = {"Skyborne"}}, who = "Dendrite Starblaze"}, {"goto", 1450, 48.1, 67.34, "Get the flight path at Moonglade"}, note = "Cast Teleport: Moonglade. Dendrite Starblaze is in Nighthaven; learn the flight path there if you do not have it.", only = {classes = {"DRUID"}}, title = "Dendrite Starblaze"},
