	{{"turnin", 98731, at = {1450, 56.21, 30.64}, only = {races = {"NightElf"}}, who = "Dendrite Starblaze"}, {"turnin", 98738, at = {1450, 56.21, 30.64}, only = {races = {"Skyborne"}}, who = "Dendrite Starblaze"}, {"accept", 98397, at = {1450, 56.21, 30.64}, who = "Dendrite Starblaze"}, {"note", "Fly to Rut'theran Village"}, note = "Back to Dendrite Starblaze in Nighthaven, then fly to Rut'theran Village (by way of Auberdine).", only = {classes = {"DRUID"}}, title = "Back to Dendrite"},
