Pathwise.RegisterRoute({category = "Leveling", faction = "Alliance", id = "forever/alliance/04-redridge-mountains", levels = {20, 23}, map = 1433, next = "forever/alliance/05-duskwood", title = "Redridge Mountains", steps = {
	{{"note", "Train new spells at your class trainer", only = {classes = {"WARRIOR", "PALADIN", "HUNTER", "ROGUE", "PRIEST", "MAGE", "WARLOCK", "DRUID"}}}, {"turnin", 97914, at = {1453, 57.74, 47.86}, who = "Baros Alexston"}, {"accept", 97926, at = {1453, 57.74, 47.86}, optional = true, who = "Baros Alexston"}, {"note", "Sell and repair"}, note = "The Auberdine boat docks at Stormwind Harbor. Walk up into the city for training and Baros Alexston, then leave by the main gate and follow the road east through Elwynn Forest.", title = "Stormwind"},
	{{"note", "Train new spells at your class trainer"}, note = "Stormwind has no shaman trainer: take the Deeprun Tram from the Dwarven District to Ironforge, train with Eldrun Stormbreaker, then ride the tram back.", only = {classes = {"SHAMAN"}}, title = "Shaman training"},
	{{"accept", 2360, at = {1453, 78.31, 70.74}, only = {classes = {"ROGUE"}}, who = "Master Mathias Shaw"}, {"accept", 1716, at = {1453, 39.22, 85.23}, only = {classes = {"WARLOCK"}}, who = "Gakin the Darkbinder"}, {"accept", 5676, at = {1453, 49.53, 44.6}, only = {classes = {"PRIEST"}, races = {"Human"}}, who = "High Priestess Laurena"}, {"turnin", 5676, at = {1453, 49.53, 44.6}, only = {classes = {"PRIEST"}, races = {"Human"}}, who = "High Priestess Laurena"}, {"accept", 5645, at = {1453, 49.53, 44.6}, only = {classes = {"PRIEST"}, races = {"Dwarf"}}, who = "High Priestess Laurena"}, {"accept", 94819, at = {1453, 49.53, 44.6}, only = {classes = {"PRIEST"}, races = {"Gnome"}}, who = "High Priestess Laurena"}, {"accept", 5673, at = {1453, 49.53, 44.6}, only = {classes = {"PRIEST"}, races = {"NightElf"}}, who = "High Priestess Laurena"}, note = "Master Mathias Shaw is at SI:7 in Old Town, Gakin the Darkbinder in the Slaughtered Lamb's cellar in the Mage Quarter, High Priestess Laurena in the Cathedral of Light.", only = {classes = {"ROGUE", "PRIEST", "WARLOCK"}}, title = "Stormwind class quests"},
	{{"note", "Fly to Sentinel Hill"}, {"have", 15882, 1, at = {1436, 17.94, 33.18}, name = "Half Pendant of Aquatic Endurance"}, note = "Fly to Sentinel Hill and head north-west to the coast: the Strange Lockbox lies on the sea floor off the shore. Then head east along the road through Elwynn to Redridge.", only = {classes = {"DRUID"}, races = {"NightElf"}}, title = "Half Pendant of Aquatic Endurance"},
	{{"accept", 244, at = {1433, 10.18, 71.46}, who = "Guard Parker"}, note = "The road from Elwynn enters Redridge at Three Corners. Guard Parker stands where the roads to Redridge and Duskwood meet.", title = "Three Corners"},
	{{"goto", 1433, 25.5, 59.41, "Get the flight path at Lakeshire"}, {"turnin", 244, at = {1433, 25.64, 60}, who = "Deputy Feldon"}, {"accept", 246, at = {1433, 25.64, 60}, who = "Deputy Feldon"}, {"accept", 98407, at = {1433, 25.64, 60}, who = "Deputy Feldon"}, {"accept", 128, at = {1433, 26.45, 57.85}, who = "Guard Howe"}, note = "Follow the road along the south shore of Lake Everstill to the gryphon master. Deputy Feldon and Guard Howe stand by the road next to her.", title = "Lakeridge Highway"},
	{{"bind", "Lakeshire", at = {1433, 21.92, 44.82}, who = "Innkeeper Brianna"}, {"accept", 125, at = {1433, 27.05, 48.64}, who = "Foreman Oslow"}, {"accept", 20, at = {1433, 28.41, 48.97}, who = "Marshal Marris"}, {"accept", 91, at = {1433, 24.63, 44.26}, who = "Bailiff Conacher"}, {"accept", 150, at = {1433, 22.63, 47.38}, who = "Dockmaster Baren"}, {"accept", 127, at = {1433, 22.63, 47.38}, who = "Dockmaster Baren"}, {"turnin", 65, at = {1433, 21.39, 45.35}, who = "Wiley the Black"}, {"accept", 92, at = {1433, 17.59, 43.84}, who = "Chef Breanna"}, {"accept", 34, at = {1433, 16.77, 46.33}, who = "Martie Jainrose"}, note = "Cross the long bridge north into town. Foreman Oslow and Marshal Marris stand at the north end of the bridge, Bailiff Conacher in the town hall, Dockmaster Baren and Wiley the Black on the docks, Chef Breanna at the inn, Martie Jainrose in her garden at the west end.", title = "Lakeshire"},
	{{"complete", 125, at = {1433, 36.43, 54.66}}, {"turnin", 125, at = {1433, 27.05, 48.64}, who = "Foreman Oslow"}, {"accept", 89, at = {1433, 27.05, 48.64}, who = "Foreman Oslow"}, note = "Swim east from the bridge into Lake Everstill; the chest lies on the lake bed.", title = "Sunken Chest"},
	{{"complete", 246, at = {1433, 11.65, 62.18}}, {"complete", 98407, at = {1433, 10.3, 66.9}}, {"complete", 89, at = {1433, 15.75, 40.03}}, {"complete", 92, at = {1433, 37.07, 32.38}}, note = "Redridge Mongrels and other gnolls hold the hills east of Three Corners, north of the road; Redridge Thrashers prowl among them, Poachers camp south of the road. Redridge Brutes, for the Iron Pikes and Rivets, hold the hills further north; Dire Condors and Great Goretusks roam the hills east of them.", title = "Gnolls toward Three Corners"},
	{{"complete", 34, at = {1433, 10.59, 49.31}}, note = "Bellygrub (level 24) roots around the pen just west of Lakeshire. Pull him away from the other boars and fight at full health.", title = "Bellygrub"},
	{{"turnin", 246, at = {1433, 25.64, 60}, who = "Deputy Feldon"}, {"turnin", 98407, at = {1433, 25.64, 60}, who = "Deputy Feldon"}, title = "Deputy Feldon"},
	{{"turnin", 89, at = {1433, 27.05, 48.64}, who = "Foreman Oslow"}, {"accept", 98386, at = {1433, 27.05, 48.64}, who = "Foreman Oslow"}, {"turnin", 34, at = {1433, 16.77, 46.33}, who = "Martie Jainrose"}, {"accept", 180, at = {1433, 21.66, 46.44}, who = "Wanted: Lieutenant Fangore"}, title = "Lakeshire"},
	{{"complete", 127, at = {1433, 30.7, 56.46}}, {"complete", 150, at = {1433, 30.7, 56.46}}, note = "Murloc Flesheaters and Tidecallers line the south shore east of the bridge. Any of them can carry a Spotted Sunfish or a fin.", title = "Lake murlocs"},
	{{"complete", 98386, at = {1433, 42.74, 38.46}}, {"complete", 92, at = {1433, 42.74, 38.46}}, note = "Greater Tarantulas crawl on the slopes around the mill north-east of the lake.", title = "Alther's Mill"},
	{{"complete", 91, at = {1433, 63.63, 45.71}}, {"complete", 180, at = {1433, 75.09, 37.06}}, note = "East past the mill and across the river. Shadowhide gnolls fill the valley; Lieutenant Fangore (26, well above you) leads them at its north end: clear his escort first and fight him at full health. Stay out of Stonewatch Keep to the south: its orcs are elite.", title = "Galardell Valley"},
	{{"complete", 20, at = {1433, 71, 70.5}}, note = "South down the valley's east side to the Blackrock camps east of Stonewatch Keep. Renegades, Grunts and Outrunners fill them; keep east of the keep, whose orcs are elite.", title = "Blackrock camps"},
	{{"note", "Hearth to Lakeshire"}, {"turnin", 150, at = {1433, 22.63, 47.38}, who = "Dockmaster Baren"}, {"turnin", 127, at = {1433, 22.63, 47.38}, who = "Dockmaster Baren"}, {"turnin", 92, at = {1433, 17.59, 43.84}, who = "Chef Breanna"}, {"turnin", 98386, at = {1433, 27.05, 48.64}, who = "Foreman Oslow"}, {"turnin", 20, at = {1433, 28.41, 48.97}, who = "Marshal Marris"}, {"turnin", 91, at = {1433, 24.63, 44.26}, who = "Bailiff Conacher"}, {"turnin", 180, at = {1433, 24.9, 44.45}, who = "Magistrate Solomon"}, {"note", "Sell and repair"}, title = "Back to Lakeshire"},
