	{{"accept", 219, at = {1433, 23.3, 12.55}, who = "Corporal Keeshan"}, {"complete", 219}, note = "Keeshan hides at the very north end of the valley, by the Burning Steppes border. Escort him down to Lakeshire; Blackrock orcs ambush you on the way.", title = "Corporal Keeshan"},
	{{"turnin", 219, at = {1433, 28.41, 48.97}, who = "Marshal Marris"}, {"turnin", 128, at = {1433, 26.45, 57.85}, who = "Guard Howe"}, {"note", "Duskwood is next: follow the road west to Three Corners, then south to Darkshire."}, title = "Lakeshire"},
