	{{"turnin", 604, at = {1434, 27.17, 77.01}, who = "Fleet Master Seahorn"}, {"accept", 608, at = {1434, 27.17, 77.01}, who = "Fleet Master Seahorn"}, {"turnin", 587, at = {1434, 26.92, 77.35}, who = "Deeg"}, {"turnin", 576, at = {1434, 28.59, 75.9}, who = "Dizzy One-Eye"}, title = "Booty Bay"},
	{{"complete", 608, at = {1434, 32.87, 88.2}, optional = true}, {"have", 4056, 1, at = {1434, 30.64, 90.17}, name = "Cortello's Riddle"}, {"accept", 624}, note = "The captains stand on the ships anchored off the Wild Shore, each with a crew of 42-45 pirates: Stillwater (45) and Keelhaul (46) on the nearer decks, Fleet Master Firallon (48) on the flagship. At 42 this is a fight for a group or for the end of the guide; clear each deck first if you go. Cortello's scroll lies on the wreck by the shore.", title = "The Bloodsail captains"},
	{{"turnin", 608, at = {1434, 27.17, 77.01}, optional = true, who = "Fleet Master Seahorn"}, title = "Booty Bay"},
	{{"complete", 617, at = {1434, 28.21, 64.41}}, note = "The naga comb the beaches north of the Bloodsail camp; they drop the reeds.", title = "Naga Explorers"},
	{{"complete", 606, at = {1434, 30.88, 66.73}}, {"accept", 349, at = {1434, 35.27, 60.41}, who = "Witch Doctor Unbagwa"}, {"complete", 349, at = {1434, 35.09, 60.75}}, note = "Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; Witch Doctor Unbagwa sits among them.", title = "Gorilla hills"},
	{{"turnin", 349, at = {1434, 35.27, 60.41}, who = "Witch Doctor Unbagwa"}, {"complete", 348, at = {1434, 35.05, 60.88}}, note = "Hand in the fangs and stay: three waves of gorillas come, Mokk the Savage last. Fight at full health.", title = "Unbagwa's ritual"},
	{{"turnin", 606, at = {1434, 26.9, 73.59}, who = "\"Shaky\" Phillipe"}, {"accept", 607, at = {1434, 26.9, 73.59}, who = "\"Shaky\" Phillipe"}, {"turnin", 607, at = {1434, 27.78, 77.07}, who = "\"Sea Wolf\" MacKinley"}, {"accept", 609, at = {1434, 27.78, 77.07}, who = "\"Sea Wolf\" MacKinley"}, {"turnin", 348, at = {1434, 27.61, 76.74}, who = "Fin Fizracket"}, {"turnin", 617, at = {1434, 26.76, 76.38}, who = "Privateer Bloads"}, {"accept", 623, at = {1434, 26.76, 76.38}, who = "Privateer Bloads"}, note = "Ride back down to town; Shaky stands at the tunnel mouth.", title = "Booty Bay"},
	{{"complete", 609, at = {1434, 35.26, 51.27}}, note = "Ride north to the hills west of the road. Maury \"Club Foot\" Wilkins and Jon-Jon the Crow stand together just north of Zanzil's village.", title = "Maury and Jon-Jon"},
	{{"complete", 621, at = {1434, 34.92, 51.84}}, {"complete", 609, at = {1434, 40, 58.24}}, note = "Every Zanzil follower can drop the mixture; Chucky \"Ten Thumbs\" walks the south of the camp.", title = "Zanzil's village"},
	{{"complete", 600, at = {1434, 36.52, 57.06}}, note = "Follow the road north-east to the Venture Co. camp at the Crystalvein Mine; the miners, surveyors and foremen drop the crystals.", title = "Crystalvein Mine"},
	{{"complete", 209, at = {1434, 45.61, 41.6}}, note = "The Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do.", title = "Skullsplitter ruins"},
	{{"complete", 212, at = {1434, 38.15, 40.36}}, note = "The Cold Eye Basilisks lie on the rocks west of the mine.", title = "Cold Eye Basilisks"},
	{{"complete", 705, at = {1434, 27.6, 29.2}}, {"complete", 611, at = {1434, 24.97, 23.58}}, note = "Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; Gazban swims among them and drops the Stone of the Tides.", title = "The north-west coast"},
	{{"note", "Kill Arbor Tarantula"}, {"turnin", 622, at = {1434, 37.74, 3.3}, who = "Corporal Kaleb"}, note = "Ride north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale. On the way, an Arbor Tarantula crawls in the jungle south-east of Nesingwary's camp: catch one with the Entomology Starter Kit, then tick it off.", title = "Rebel Camp"},
	{{"note", "Hearth to Booty Bay"}, {"turnin", 611, at = {1434, 27.23, 76.87}, who = "Baron Revilgaz"}, {"turnin", 609, at = {1434, 27.78, 77.07}, who = "\"Sea Wolf\" MacKinley"}, {"note", "MacKinley's next task sends you after elite ogres: skip it."}, {"turnin", 600, at = {1434, 27.12, 77.21}, who = "Crank Fizzlebub"}, {"turnin", 621, at = {1434, 27.12, 77.21}, who = "Crank Fizzlebub"}, {"note", "Crank's next Zanzil errand starts in Thousand Needles: skip it."}, {"turnin", 209, at = {1434, 27, 77.13}, who = "Kebok"}, title = "Booty Bay"},
	{{"note", "Fly to Stormwind"}, {"bind", "Stormwind City", at = {1453, 60.39, 75.27}, who = "Innkeeper Allison"}, {"turnin", 212, at = {1453, 51.79, 93.64}, who = "Angus Stern"}, {"accept", 1271, at = {1453, 51.79, 93.64}, who = "Angus Stern"}, {"turnin", 1271, at = {1453, 51.79, 93.64}, who = "Angus Stern"}, {"accept", 1477, at = {1453, 48.71, 87.62}, who = "High Sorcerer Andromath"}, {"accept", 1363, at = {1453, 51.8, 74.24}, who = "Mazen Mac'Nadir"}, {"turnin", 1363, at = {1453, 51.4, 73.81}, who = "Acolyte Dellis"}, {"accept", 1364, at = {1453, 51.4, 73.81}, who = "Acolyte Dellis"}, {"accept", 1448, at = {1453, 69.45, 40.4}, who = "Brohann Caskbelly"}, {"turnin", 542, at = {1453, 77.07, 30.21}, who = "Milton Sheaf"}, {"note", "Train new spells at your class trainer", only = {classes = {"WARRIOR", "PALADIN", "HUNTER", "ROGUE", "PRIEST", "MAGE", "WARLOCK", "DRUID"}}}, note = "Angus Stern cooks in the Blue Recluse; Brohann Caskbelly is in the Dwarven District.", title = "Stormwind"},
	{{"note", "Train new spells at your class trainer", optional = true}, {"note", "Sell and repair at Katie Hunter", optional = true}, note = "At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Randal Hunter teaches Humans at Eastvale Logging Camp in eastern Elwynn Forest, beside Katie Hunter's horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour.", only = {races = {"Human"}}, title = "Riding at 40"},
	{{"note", "Train new spells at your class trainer", optional = true}, {"note", "Galestriders: Genn Fairweather, in Valanaar on Zephras Isle."}, note = "At 40 with 100 gold you can learn to ride, and learning it gives you a mount. No Skyborne riding trainer is known; the Forever client files Galestrider Riding under the one Riding skill, so Randal Hunter at Eastvale Logging Camp in eastern Elwynn Forest, the nearest trainer to Stormwind, should teach it (unconfirmed). The Galestriders are sold by Genn Fairweather in Valanaar on Zephras Isle; Collectibles, Mounts · Level 40 lists them.", only = {races = {"Skyborne"}}, title = "Riding at 40"},
	{{"note", "Train new spells at your class trainer", optional = true}, {"note", "Sell and repair at Lelanai", optional = true}, note = "At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Jartsam teaches Night Elves in Darnassus, beside Lelanai's sabers: the boat from Stormwind Harbor to Auberdine, then the flight to Rut'theran Village. Forever may let any race learn from any riding trainer (unconfirmed), such as Randal Hunter at Eastvale Logging Camp in Elwynn Forest. Collectibles, Mounts · Level 40 lists every colour.", only = {races = {"NightElf"}}, title = "Riding at 40"},
	{{"accept", 1661, at = {1453, 50.48, 47.49}, who = "Duthorian Rall"}, {"turnin", 1661, at = {1453, 50.48, 47.49}, who = "Duthorian Rall"}, only = {classes = {"PALADIN"}}, title = "Paladin: The Tome of Nobility"},
	{{"accept", 4488, at = {1453, 39.24, 84.96}, who = "Demisette Cloyce"}, only = {classes = {"WARLOCK"}}, title = "Warlock: Summon Felsteed"},
	{{"note", "Fly to Darkshire"}, {"accept", 1398, at = {1435, 26.74, 59.83}, who = "Watcher Biggs"}, note = "Fly to Darkshire and ride east through Deadwind Pass into the Swamp of Sorrows; Watcher Biggs stands by the road just past the border.", title = "Watcher Biggs"},
	{{"turnin", 624, at = {1435, 22.87, 48.19}, who = "A Soggy Scroll"}, {"note", "The riddle's next scroll lies in western Dustwallow: skip it."}, {"complete", 1364, at = {1435, 15.77, 40.78}}, note = "The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays.", title = "A Soggy Scroll"},
	{{"complete", 1364, at = {1435, 15.77, 40.78}}, {"complete", 1448, at = {1435, 70.2, 45.2}}, note = "Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the Pool of Tears, where the temple's ruins break the water.", title = "The sunken temple"},
	{{"complete", 1398, at = {1435, 91.94, 31.94}}, note = "The driftwood washes up along the eastern shore.", title = "Misty Reed Strand"},
	{{"turnin", 1398, at = {1435, 26.74, 59.83}, who = "Watcher Biggs"}, {"accept", 1425, at = {1435, 26.74, 59.83}, who = "Watcher Biggs"}, {"turnin", 93176, at = {1435, 25.3, 54.39}, who = "Amaryllis Webb"}, note = "Ride back west along the road; Amaryllis Webb stands a short way north of Biggs.", title = "Watcher Biggs"},
	{{"note", "Hearth to Stormwind City"}, {"turnin", 1448, at = {1453, 69.45, 40.4}, who = "Brohann Caskbelly"}, {"accept", 1449, at = {1453, 69.45, 40.4}, who = "Brohann Caskbelly"}, title = "Stormwind"},
	{{"turnin", 1467, at = {1455, 69.95, 21.26}, who = "Roetten Stonehammer"}, {"accept", 707, at = {1455, 74.64, 11.74}, who = "Prospector Stormpike"}, {"turnin", 727, at = {1455, 50.83, 5.62}, who = "Gerrig Bonegrip"}, {"note", "Train new spells at your class trainer", only = {classes = {"SHAMAN"}}}, note = "Take the Deeprun Tram from the Dwarven District. Roetten is in the Reclaimers' hall by the Hall of Explorers, Prospector Stormpike in the hall itself, Gerrig Bonegrip in the Forlorn Cavern. The next guide flies on to Thelsamar.", title = "Ironforge"},
	{{"note", "Train new spells at your class trainer", optional = true}, {"note", "Sell and repair at Veron Amberstill", optional = true}, note = "At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Ultham Ironhorn teaches Dwarves at Amberstill Ranch, east of Kharanos on the road to Loch Modan, beside Veron Amberstill's rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour.", only = {races = {"Dwarf"}}, title = "Riding at 40"},
	{{"note", "Train new spells at your class trainer", optional = true}, {"note", "Sell and repair at Milli Featherwhistle", optional = true}, note = "At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Binjy Featherwhistle teaches Gnomes at Steelgrill's Depot, just east of Kharanos, beside Milli Featherwhistle's mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour.", only = {races = {"Gnome"}}, title = "Riding at 40"},
} })

Pathwise.RegisterRoute({category = "Leveling", faction = "Alliance", id = "forever/alliance/40-50/02-badlands", levels = {43, 44}, map = 1418, next = "forever/alliance/40-50/03-feralas", title = "Badlands & The Hinterlands", steps = {
