	{{"turnin", 705, at = {1418, 42.39, 52.93}, who = "Rigglefuzz"}, {"note", "Rigglefuzz's next quest pays no experience: skip it."}, note = "Ride west to the Valley of Fangs in the middle of the Badlands; Rigglefuzz camps beside Martek.", title = "Rigglefuzz"},
	{{"complete", 732, at = {1418, 12.62, 75.49}}, note = "Ride west across the Badlands to the Dustbelcher camp at Camp Boff. Boss Tho'grun stands in its middle with Wyrmhunters and Maulers around him.", title = "Boss Tho'grun"},
	{{"turnin", 732, at = {1418, 61.94, 54.26}, who = "Garek"}, {"note", "Garek's next task is an elite hunt: skip it."}, note = "Ride back east to Dustwind Gulch.", title = "Garek"},
	{{"level", 43}, {"complete", 706, at = {1418, 69.67, 53.81}, optional = true}, note = "The Scalding Whelps nest in the ravine east of Garek; leave the Scorched Guardians (elite) alone. The Black Drake's Heart drops rarely: take it if it comes while you grind.", title = "Lethlor Ravine"},
	{{"turnin", 706, at = {1418, 53.8, 43.3}, optional = true, who = "Sigrun Ironhew"}, title = "Hammertoe's Digsite"},
	{{"note", "Fly to Southshore"}, {"turnin", 1052, at = {1424, 51.47, 58.35}, who = "Raleigh the Devout"}, {"note", "Raleigh's next errand is in the Scarlet Monastery: skip it."}, note = "Ride north to Thelsamar and fly to Southshore. Raleigh the Devout preaches by the inn.", title = "Southshore"},
	{{"goto", 1425, 11.07, 46.15, "Get the flight path at Aerie Peak"}, {"turnin", 1449, at = {1425, 11.81, 46.76}, who = "Falstad Wildhammer"}, {"accept", 1450, at = {1425, 11.81, 46.76}, who = "Falstad Wildhammer"}, {"turnin", 1450, at = {1425, 9.75, 44.47}, who = "Gryphon Master Talonaxe"}, {"accept", 1451, at = {1425, 9.75, 44.47}, who = "Gryphon Master Talonaxe"}, {"accept", 2988, at = {1425, 9.75, 44.47}, who = "Gryphon Master Talonaxe"}, {"accept", 2880, at = {1425, 14.83, 44.57}, who = "Fraggar Thundermantle"}, note = "Ride north-east out of Southshore on the road into the Hinterlands; Aerie Peak sits just past the border. Falstad holds court at the top, Gryphon Master Talonaxe tends the aviary and Fraggar Thundermantle stands by the inn.", title = "Aerie Peak"},
	{{"turnin", 1451, at = {1425, 26.94, 48.59}, who = "Rhapsody Shindigger"}, {"note", "Rhapsody's cocktail needs parts from Kalimdor: skip it."}, note = "Rhapsody camps on the road east of Aerie Peak.", title = "Rhapsody Shindigger"},
	{{"complete", 2988, at = {1425, 23.28, 58.81}}, {"complete", 2880, at = {1425, 31.9, 57.58}}, note = "The first two cages stand together in the Witherbark village south of Rhapsody; the third is in the next village to the east. Every Witherbark troll can drop a necklace.", title = "Witherbark villages"},
	{{"turnin", 2880, at = {1425, 14.83, 44.57}, who = "Fraggar Thundermantle"}, {"accept", 2881, at = {1425, 14.83, 44.57}, optional = true, who = "Fraggar Thundermantle"}, {"turnin", 2881, at = {1425, 14.83, 44.57}, optional = true, who = "Fraggar Thundermantle"}, {"turnin", 2988, at = {1425, 9.75, 44.47}, who = "Gryphon Master Talonaxe"}, {"note", "Talonaxe's next task waits for a later Hinterlands guide."}, title = "Aerie Peak"},
	{{"note", "Fly to Menethil Harbor"}, {"goto", 1437, 5.13, 63.61, "Boat to Theramore"}, note = "Take the boat to Theramore from the far pier.", title = "Menethil Harbor"},
	{{"turnin", 623, at = {1445, 68.84, 53.22}, who = "Privateer Groy"}, note = "Privateer Groy stands on the docks where the boat lands.", title = "Theramore"},
	{{"note", "Fly to Ratchet"}, {"turnin", 4488, at = {1413, 62.63, 35.5}, who = "Strahad Farsan"}, {"accept", 4490, at = {1413, 62.63, 35.5}, who = "Strahad Farsan"}, {"turnin", 4490, at = {1413, 62.63, 35.5}, who = "Strahad Farsan"}, note = "Fly to Ratchet; Strahad Farsan teaches in the house by the bank. Fly back to Theramore afterwards.", only = {classes = {"WARLOCK"}}, title = "Warlock: Summon Felsteed"},
	{{"note", "Fly to Nijel's Point"}, note = "Fly to Nijel's Point, ride south through Desolace into Feralas and follow the road to the dock on the Forgotten Coast; the boat crosses to Feathermoon Stronghold, where the next guide starts.", title = "On to Feathermoon"},
} })

