	{{"turnin", 4125, at = {1444, 45.44, 64.96}, who = "Wrecked Row Boat"}, {"accept", 4127, at = {1444, 45.44, 64.96}, who = "Wrecked Row Boat"}, note = "Take the boat to the Forgotten Coast and follow the shore south to the wrecked row boat on the beach.", title = "The courier's boat"},
	{{"complete", 2982, at = {1444, 58.36, 66.56}}, note = "Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north.", title = "Gordunni ogres"},
	{{"complete", 2821, at = {1444, 55.88, 58.81}}, note = "Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; Bloodroar the Stalker (level 48) prowls the middle.", title = "Feral Scar Vale"},
	{{"turnin", 4127, at = {1444, 31.86, 45.13}, who = "Ginro Hearthkindle"}, {"accept", 4129, at = {1444, 31.86, 45.13}, who = "Ginro Hearthkindle"}, {"turnin", 4129, at = {1444, 32.45, 43.79}, who = "Quintis Jonespyre"}, {"accept", 4130, at = {1444, 32.45, 43.79}, who = "Quintis Jonespyre"}, {"turnin", 4130, at = {1444, 31.86, 45.13}, who = "Ginro Hearthkindle"}, {"accept", 4131, at = {1444, 31.86, 45.13}, who = "Ginro Hearthkindle"}, {"turnin", 2982, at = {1444, 31.83, 45.61}, who = "Angelas Moonbreeze"}, {"turnin", 2821, at = {1444, 30.63, 42.71}, who = "Pratt McGrubben"}, {"accept", 7733, at = {1444, 30.63, 42.71}, who = "Pratt McGrubben"}, note = "Ride back north-west to the Forgotten Coast dock and take the boat to the island.", title = "Feathermoon Stronghold"},
	{{"complete", 2870, at = {1444, 28.5, 70.46}}, note = "Swim south from the island to the Isle of Dread. Hatecrest Serpent Guards and Sorceresses hold it; Lord Shalzaru (level 47) waits in the cave at its south end. Pull his guards first.", title = "Lord Shalzaru"},
	{{"note", "Hearth to Feathermoon Stronghold"}, {"turnin", 2870, at = {1444, 30.38, 46.17}, who = "Latronicus Moonspear"}, {"accept", 2871, at = {1444, 30.38, 46.17}, who = "Latronicus Moonspear"}, {"turnin", 2871, at = {1444, 30.08, 45.06}, who = "Vestia Moonspear"}, note = "Hearth to Feathermoon.", title = "Feathermoon Stronghold"},
