	{{"turnin", 4131, at = {1444, 73.32, 56.31}, who = "Large Leather Backpacks"}, {"accept", 4135, at = {1444, 73.32, 56.31}, who = "Large Leather Backpacks"}, {"have", 11463, 1, at = {1444, 73.32, 56.31}, name = "Undelivered Parcel"}, {"accept", 4281}, {"turnin", 4135, at = {1444, 72.07, 63.72}, who = "Zukk'ash Pod"}, {"accept", 4265, at = {1444, 72.07, 63.72}, who = "Zukk'ash Pod"}, {"complete", 4265}, note = "Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to Thalanaar. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out.", title = "The Writhing Deep"},
	{{"goto", 1444, 89.5, 45.85, "Get the flight path at Thalanaar"}, {"turnin", 4281, at = {1444, 89.64, 46.57}, who = "Falfindel Waywarder"}, {"turnin", 1100, at = {1444, 89.64, 46.57}, who = "Falfindel Waywarder"}, note = "Ride north-east to the night elf outpost on the Thousand Needles border.", title = "Thalanaar"},
	{{"complete", 7733, at = {1444, 54.9, 32.9}}, {"have", 18969, 1, at = {1444, 54.83, 33.05}, name = "Pristine Yeti Hide", optional = true}, {"accept", 7735, optional = true}, note = "Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a Pristine Yeti Hide, which Pratt pays for too.", title = "Rage Scar yetis"},
	{{"accept", 2844, at = {1444, 42.39, 22}, who = "Rockbiter"}, note = "Ride west to the friendly mountain giant at the foot of the hills. Land Walkers and Cliff Giants around him are elite: give them room.", title = "Rockbiter"},
	{{"turnin", 2844, at = {1444, 38.22, 10.3}, who = "Shay Leafrunner"}, {"accept", 2845, at = {1444, 38.22, 10.3}, who = "Shay Leafrunner"}, {"complete", 2845, at = {1444, 38.25, 10.29}}, note = "Shay wanders the hills north of Rockbiter, among the Northspring harpies; her bell is in the chest beside her.", title = "Shay Leafrunner"},
	{{"complete", 2845, at = {1444, 42.33, 21.85}}, {"turnin", 2845, at = {1444, 42.39, 22}, who = "Rockbiter"}, note = "Ring the bell whenever Shay stops to wander, and lead her south to Rockbiter.", title = "Shay's escort"},
	{{"note", "Hearth to Feathermoon Stronghold"}, {"turnin", 4265, at = {1444, 31.86, 45.13}, who = "Ginro Hearthkindle"}, {"accept", 4266, at = {1444, 31.86, 45.13}, who = "Ginro Hearthkindle"}, {"turnin", 4266, at = {1444, 30.28, 46.17}, who = "Shandris Feathermoon"}, {"note", "Shandris then asks you to carry news to Darnassus: skip it, Gadgetzan sends you there instead."}, {"turnin", 7733, at = {1444, 30.63, 42.71}, who = "Pratt McGrubben"}, {"turnin", 7735, at = {1444, 30.63, 42.71}, optional = true, who = "Pratt McGrubben"}, note = "Hearth to Feathermoon.", title = "Feathermoon Stronghold"},
	{{"goto", 1446, 38.7, 20, "Zul'Farrak", optional = true}, note = "Running Zul'Farrak instead of grinding gets you there faster in a group. The troll city lies in northern Tanaris, the next zone on the route; come back to Zorbin on the Forgotten Coast afterwards.", title = "Zul'Farrak instead of grinding"},
	{{"level", 45}, note = "Boat to the Forgotten Coast and ride east into Feral Scar Vale. Zorbin's quests on the coast need level 45.", title = "Grind to 45"},
	{{"accept", 7003, at = {1444, 44.81, 43.42}, who = "Zorbin Fandazzle"}, {"accept", 7721, at = {1444, 44.81, 43.42}, who = "Zorbin Fandazzle"}, note = "Ride back to the Forgotten Coast; the goblin stands by the dock.", title = "Zorbin Fandazzle"},
	{{"complete", 7003, at = {1444, 44.34, 46.61}}, {"complete", 7721, at = {1444, 44.97, 46.29}}, note = "Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with Zorbin's Ultra-Shrinker and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf.", title = "Giants and elementals"},
	{{"turnin", 7003, at = {1444, 44.81, 43.42}, who = "Zorbin Fandazzle"}, {"turnin", 7721, at = {1444, 44.81, 43.42}, who = "Zorbin Fandazzle"}, {"note", "Zorbin's refills are level 55: skip them."}, {"note", "You end at the Forgotten Coast dock: the Tanaris guide starts with the trip east from here."}, title = "Zorbin Fandazzle"},
} })

Pathwise.RegisterRoute({category = "Leveling", faction = "Alliance", id = "forever/alliance/40-50/04-tanaris", levels = {45, 47}, map = 1446, next = "forever/alliance/40-50/05-the-hinterlands", title = "Tanaris", steps = {
