	{{"turnin", 1190, at = {1441, 77.21, 77.39}, who = "Rizzle's Unguarded Plans"}, {"accept", 1194, at = {1441, 77.21, 77.39}, who = "Rizzle's Unguarded Plans"}, note = "While Zamek keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track.", title = "Rizzle's plans"},
