	{{"turnin", 1878, at = {1446, 52.49, 28.45}, who = "Spigot Operator Luglunket"}, {"turnin", 1691, at = {1446, 52.46, 28.51}, who = "Chief Engineer Bilgewhizzle"}, {"accept", 2605, at = {1446, 51.81, 28.66}, who = "Marin Noggenfogger"}, {"accept", 5863, at = {1446, 52.82, 27.4}, who = "Andi Lynn"}, {"accept", 3022, at = {1446, 52.36, 26.91}, who = "Curgle Cranklehop"}, {"accept", 3362, at = {1446, 51.57, 26.76}, who = "Tran'rek"}, {"accept", 992, at = {1446, 50.21, 27.48}, who = "Senior Surveyor Fizzledowser"}, title = "Gadgetzan"},
	{{"complete", 992, at = {1446, 39.9, 28.4}}, note = "Ride north-west to the Sandfury troll camp at Sandsorrow Watch. Use the Untapped Dowsing Widget at the edge of its pool; the trolls stand close, so pull the nearest first.", title = "The pool by Sandsorrow Watch"},
	{{"turnin", 992, at = {1446, 50.21, 27.48}, who = "Senior Surveyor Fizzledowser"}, {"accept", 82, at = {1446, 50.21, 27.48}, who = "Senior Surveyor Fizzledowser"}, title = "Gadgetzan"},
	{{"accept", 3161, at = {1446, 52.71, 45.92}, who = "Marvon Rivetseeker"}, {"complete", 3161, at = {1446, 52.3, 45.3}}, {"turnin", 3161, at = {1446, 52.71, 45.92}, who = "Marvon Rivetseeker"}, note = "Ride south to the dig camp at the Broken Pillar. Marvon hands you a detector helm: wear it to see the Gahz'ridian mounds, which lie thick in the sand around the camp and south-west toward the ogres.", title = "The Broken Pillar"},
	{{"complete", 5863, at = {1446, 42.68, 53.15}}, note = "Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; Gor'marok the Ravager (49) stands in the middle with guards around him: clear them first.", title = "Dunemaul Compound"},
