	{{"complete", 3362, at = {1446, 29.34, 62.44}}, {"complete", 2605, at = {1446, 28.19, 62.93}}, note = "Ride south into Thistleshrub Valley. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time.", title = "Thistleshrub Valley"},
	{{"accept", 1560, at = {1446, 29.48, 60.51}, who = "Tooga"}, {"complete", 1560}, {"turnin", 1560, at = {1446, 66.58, 25.67}, who = "Torta"}, note = "The little turtle Tooga hides at the north end of the valley. Lead him home to his wife Torta, by the water just east of Steamwheedle Port: he walks slowly and the desert's beasts go for him, so keep him alive.", title = "Tooga's escort"},
	{{"turnin", 5863, at = {1446, 52.82, 27.4}, who = "Andi Lynn"}, {"turnin", 2605, at = {1446, 51.81, 28.66}, who = "Marin Noggenfogger"}, {"accept", 2606, at = {1446, 51.81, 28.66}, who = "Marin Noggenfogger"}, {"turnin", 3362, at = {1446, 51.57, 26.76}, who = "Tran'rek"}, {"turnin", 82, at = {1446, 50.89, 26.96}, who = "Alchemist Pestlezugg"}, {"turnin", 2606, at = {1446, 51.06, 26.87}, who = "Sprinkle"}, {"note", "Sprinkle's next ingredient grows in the Hinterlands, and the route never brings it back: skip it."}, {"accept", 10, at = {1446, 50.21, 27.48}, who = "Senior Surveyor Fizzledowser"}, note = "Ride back west to Gadgetzan.", title = "Gadgetzan"},
	{{"complete", 2781, at = {1446, 61.77, 38.17}}, note = "Ride south-east to Waterspring Field. Caliph stands in the middle of the southern Wastewander camp: clear around him first.", title = "Caliph Scorpidsting"},
	{{"complete", 10, at = {1446, 55.96, 71.17}}, note = "Ride south past the Broken Pillar to the Gaping Chasm, the Hazzali tunnels; Scrimshank's gear lies deep inside.", title = "The Gaping Chasm"},
	{{"note", "Hearth to Gadgetzan"}, {"turnin", 2781, at = {1446, 52.46, 28.51}, who = "Chief Engineer Bilgewhizzle"}, {"turnin", 10, at = {1446, 50.21, 27.48}, who = "Senior Surveyor Fizzledowser"}, {"accept", 110, at = {1446, 50.21, 27.48}, who = "Senior Surveyor Fizzledowser"}, {"turnin", 110, at = {1446, 50.89, 26.96}, who = "Alchemist Pestlezugg"}, {"accept", 113, at = {1446, 50.89, 26.96}, who = "Alchemist Pestlezugg"}, {"turnin", 113, at = {1446, 50.21, 27.48}, who = "Senior Surveyor Fizzledowser"}, {"accept", 162, at = {1446, 50.21, 27.48}, who = "Senior Surveyor Fizzledowser"}, note = "Hearth to Gadgetzan.", title = "Gadgetzan"},
