	{{"complete", 7723, at = {1427, 41.66, 41.39}}, {"complete", 3442, at = {1427, 41.66, 41.39}}, note = "Heavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts.", title = "Golems and elementals"},
	{{"turnin", 3442, at = {1427, 39.06, 38.99}, who = "Kalaran Windblade"}, {"accept", 3443, at = {1427, 39.06, 38.99}, who = "Kalaran Windblade"}, title = "Kalaran Windblade"},
	{{"complete", 7729, at = {1427, 37.49, 39.64}}, {"complete", 3443, at = {1427, 38.39, 38.04}}, {"complete", 7728, at = {1427, 40.01, 48.33}}, {"have", 11818, 1, at = {1427, 33.71, 51.92}, name = "Grimesilt Outhouse Key", optional = true}, {"accept", 4451, optional = true}, note = "Taskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a Thorium Plated Dagger. The Steamsmiths work at the furnaces in the middle (the Smithing Tuyere), the Lookouts stand on the southern ridges (the Spyglass). Any Dark Iron may drop the Grimesilt Outhouse Key: keep it.", title = "Dark Iron dwarves"},
	{{"complete", 7724, at = {1427, 29.56, 56.52}}, note = "The spiders roam the plateaus and lava pools in the south-west of the gorge.", title = "Greater Lava Spiders"},
	{{"turnin", 3443, at = {1427, 39.06, 38.99}, who = "Kalaran Windblade"}, title = "Kalaran Windblade"},
	{{"complete", 7722, at = {1427, 40.45, 35.74}}, {"complete", 7727, at = {1427, 43.38, 28.26}}, note = "The Slag Pit opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of Overseer Maltorius and his elite guards deep inside.", title = "The Slag Pit"},
	{{"turnin", 7728, at = {1427, 38.97, 27.51}, who = "Taskmaster Scrange"}, {"turnin", 7729, at = {1427, 38.97, 27.51}, who = "Taskmaster Scrange"}, {"turnin", 7723, at = {1427, 38.58, 27.81}, who = "Hansel Heavyhands"}, {"turnin", 7724, at = {1427, 38.58, 27.81}, who = "Hansel Heavyhands"}, {"turnin", 7727, at = {1427, 38.58, 27.81}, who = "Hansel Heavyhands"}, {"turnin", 7722, at = {1427, 38.8, 28.51}, who = "Master Smith Burninate"}, title = "Thorium Point"},
	{{"turnin", 4451, at = {1427, 65.59, 62.17}, optional = true, who = "Wooden Outhouse"}, {"accept", 4449, at = {1427, 65.59, 62.17}, who = "Wooden Outhouse"}, {"complete", 4449, at = {1427, 63.9, 60.39}}, {"turnin", 4449, at = {1427, 65.59, 62.17}, who = "Wooden Outhouse"}, {"note", "The prisoner's next task, Ledger from Tanaris, sends you to the Swamp of Sorrows and Dustwallow Marsh: skip it."}, note = "Ride east across the Cauldron to the Grimesilt Dig Site in the south-east. The prisoner in the wooden outhouse wants 15 Silk Cloth and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one.", title = "The Grimesilt outhouse"},
	{{"accept", 3367, at = {1427, 63.92, 60.99}, who = "Dorius Stonetender"}, {"complete", 3367}, {"turnin", 3367, at = {1427, 74.45, 19.29}, who = "Singed Letter"}, {"accept", 3368, at = {1427, 74.45, 19.29}, who = "Singed Letter"}, note = "The dwarf stands by the road at the dig site. Follow him north along the road and fight off the Dark Iron ambushes. When it is over, read the Singed Letter he leaves on the road in Dustfire Valley.", title = "Dorius Stonetender"},
	{{"note", "Hearth to Stoutlager Inn"}, title = "Thelsamar"},
} })

Pathwise.RegisterRoute({category = "Leveling", faction = "Alliance", id = "forever/alliance/40-50/07-un-goro-crater", levels = {48, 52}, map = 1449, next = "forever/alliance/50-60/01-burning-steppes", title = "Un'Goro Crater & Ironforge", steps = {
