	{{"complete", 4290, at = {1449, 68.74, 56.71}}, note = "The dead Threshadon lies by the water north of Torwa.", title = "Fresh Threshadon Carcass"},
	{{"turnin", 4290, at = {1449, 71.64, 75.96}, who = "Torwa Pathfinder"}, {"accept", 4291, at = {1449, 71.64, 75.96}, who = "Torwa Pathfinder"}, title = "Torwa Pathfinder"},
	{{"complete", 4291, at = {1449, 67, 73}}, {"accept", 3844, at = {1449, 63.02, 68.6}, who = "A Wrecked Raft"}, {"turnin", 3844, at = {1449, 63.11, 69.06}, who = "A Small Pack"}, {"accept", 3845, at = {1449, 63.11, 69.06}, who = "A Small Pack"}, {"complete", 3845, at = {1449, 63.1, 69.1}}, {"have", 11116, 1, at = {1449, 62.87, 66.68}, name = "A Mangled Journal", optional = true}, {"accept", 3884, optional = true}, note = "The Lar'korwi Mates prowl the jungle west of Torwa. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for Linken. Any beast in the crater may drop A Mangled Journal: right-click it.", title = "Lar'korwi Mates and the raft"},
	{{"turnin", 4291, at = {1449, 71.64, 75.96}, who = "Torwa Pathfinder"}, title = "Torwa Pathfinder"},
