	{{"turnin", 4243, at = {1449, 67.66, 16.76}, who = "A-Me 01"}, note = "Ride north to Ironstone Plateau, where the robot stands among the gorillas. Stay out of the deep cave there.", title = "A-Me 01"},
	{{"goto", 1446, 38.7, 20, "Zul'Farrak", optional = true}, note = "Running Zul'Farrak instead of grinding gets you there faster in a group. The troll city lies in the north-west of Tanaris, just north of Gadgetzan.", title = "Zul'Farrak (optional)"},
	{{"level", 50}, note = "The gorillas of Ironstone Plateau come in small groups and drop nothing for you yet; Torwa's pelt quest comes later. Stay out of the deepest cave: U'cha is level 55.", title = "Grind to 50"},
