	{{"complete", 4503, at = {1449, 50.78, 19.9}}, note = "Ride south down the east side. Young Diemetradons graze the eastern jungle and Fledgling Pterrordax fly near the eastern cliffs; both drop Shizzle's scales.", title = "The east side"},
	{{"goto", 1449, 77.2, 50, "Eastern Crystal Pylon"}, {"complete", 4287}, note = "The pylon stands on the eastern cliffs.", title = "Eastern Pylon"},
