	{{"complete", 3883, at = {1449, 48.69, 85.32}}, {"complete", 3764, at = {1449, 48.35, 85.25}}, {"complete", 4501, at = {1449, 50.4, 87.8}}, note = "Ride west from Torwa: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop Un'Goro Soil; Pterrordax nest on the southern cliffs if you still need kills.", title = "The Gorishi hive"},
	{{"complete", 3882, at = {1449, 38.64, 77.53}}, {"complete", 3881, at = {1449, 38.45, 66.06}}, {"complete", 4503, at = {1449, 38.9, 66.97}}, note = "Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's Research Equipment lies in the south-west jungle.", title = "Bones and equipment"},
	{{"goto", 1449, 23.9, 59.2, "Western Crystal Pylon"}, {"complete", 4288}, {"complete", 4501, at = {1449, 21, 58.4}}, {"complete", 4503, at = {1449, 21, 58.4}}, note = "The pylon stands on the western cliffs. Frenzied Pterrordax fly over the whole west side.", title = "Western Pylon"},
