	{{"complete", 4292, at = {1449, 79.65, 49.83}}, note = "Lar'korwi's lair lies in the jungle north of Torwa, below the eastern cliffs: use Torwa's Pouch there. Lar'korwi is level 56: start at full health.", title = "Lar'korwi"},
