	{{"accept", 4726, at = {1428, 65.24, 24}, who = "Tinkee Steamboil"}, {"accept", 4296, at = {1428, 65.15, 23.91}, who = "Maxwort Uberglint"}, note = "Follow the road west, then climb north to the goblin camp on Flame Crest.", title = "Flame Crest"},
	{{"complete", 3701, at = {1428, 65.26, 34.81}}, note = "The relics are the carved stones scattered through the Ruins of Thaurissan around Flame Crest: click them until the information is recovered.", title = "Thaurissan Relics"},
