	{{"accept", 3801, at = {1428, 28.96, 28.93}, optional = true, who = "Franclorn Forgewright"}, {"turnin", 3801, at = {1428, 28.96, 28.93}, optional = true, who = "Franclorn Forgewright"}, note = "Optional: Franclorn's ghost stands on his tomb on the great chain inside Blackrock Mountain, and only the dead can see him. If you die near the mountain anyway, run your spirit to him before resurrecting.", title = "Franclorn Forgewright"},
