	{{"note", "Fly to Aerie Peak"}, {"complete", 3661, at = {1425, 39.08, 52.94}}, note = "Ride back to Nethergarde Keep and fly to Aerie Peak. The Wildkin Feathers lie on the ground across the Hinterlands, south and east of Aerie Peak, where the owlbeasts roam; the mobs here are well below you now.", title = "Wildkin feathers"},
	{{"note", "Hearth to Ironforge"}, {"note", "Train new spells at your class trainer", only = {classes = {"WARRIOR", "PALADIN", "HUNTER", "ROGUE", "PRIEST", "SHAMAN", "MAGE", "WARLOCK"}}}, title = "Ironforge"},
