	{{"turnin", 3444, at = {1446, 52.71, 45.92}, who = "Marvon Rivetseeker"}, note = "Ride south-west to Marvon Rivetseeker's camp at the Broken Pillar.", title = "Broken Pillar"},
	{{"complete", 4507, at = {1449, 43.85, 81.39}}, note = "Take the road west down into the crater and ride to the Slithering Scar, the silithid cave in the south. The Gorishi Hive Queen waits in its deepest chamber.", title = "The Slithering Scar"},
	{{"complete", 5801, at = {1449, 48.9, 47}}, {"complete", 4513, at = {1449, 42.07, 50.54}}, note = "Climb Fire Plume Ridge in the middle of the crater and use the Skeleton Key Mold by the lava lake at the top, with two Thorium Bars in your bags. Fill Laris's Empty Pure Sample Jars on the Primal Oozes in the pools around the ridge.", title = "Fire Plume Ridge"},
	{{"complete", 5163, at = {1449, 43.66, 9.37}}, {"turnin", 4005, at = {1449, 41.92, 2.7}, who = "J.D. Collie"}, {"accept", 3961, at = {1449, 41.92, 2.7}, who = "J.D. Collie"}, {"turnin", 3961, at = {1449, 44.66, 8.1}, who = "Linken"}, note = "Ride north to Marshal's Refuge. Use Umi's Mechanical Yeti beside Quixxil.", title = "Marshal's Refuge"},
