	{{"turnin", 413, at = {1426, 86.28, 48.81}, who = "Mountaineer Barleybrew"}, note = "Follow the road all the way east to the South Gate Outpost at the Loch Modan tunnel.", title = "South Gate Outpost"},
	{{"turnin", 94449, at = {1426, 87.94, 44.8}, who = "Bruegs Kindleborn"}, {"accept", 94465, at = {1426, 87.94, 44.8}, who = "Bruegs Kindleborn"}, note = "Bruegs waits in a cave above the farm north-west of the South Gate Outpost; the path up starts behind the farm.", only = {classes = {"SHAMAN"}}, title = "Bruegs Kindleborn"},
	{{"turnin", 94465, at = {1432, 32.17, 65.97}, who = "Braldir Ashmantle"}, {"accept", 94466, at = {1432, 32.17, 65.97}, who = "Braldir Ashmantle"}, note = "Go through the tunnel into Loch Modan. Just past it, a path marked by stones climbs the hills on the right of the road north to Braldir's camp.", only = {classes = {"SHAMAN"}}, title = "Braldir Ashmantle"},
	{{"complete", 94466, at = {1432, 36.75, 77.75}}, note = "Stonesplinter Seers (level 13) stand among the troggs in the south of Stonesplinter Valley, south of Braldir; Tunnel Rat Geomancers (level 12) work the Silver Stream Mine at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time.", only = {classes = {"SHAMAN"}}, title = "Fire Tar and the Reagent Pouch"},
	{{"turnin", 94466, at = {1432, 32.17, 65.97}, who = "Braldir Ashmantle"}, {"accept", 94467, at = {1432, 32.17, 65.97}, who = "Braldir Ashmantle"}, {"note", "Use Fire Sapta"}, {"complete", 94467, at = {1432, 31.9, 64.5}}, {"turnin", 94467, at = {1432, 31.9, 64.5}, who = "Brazier of the Dormant Flame"}, {"accept", 94468, at = {1432, 31.9, 64.5}, who = "Brazier of the Dormant Flame"}, note = "Braldir gives you the Fire Sapta. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the Minor Manifestation of Fire, then place its Glowing Ember in the Brazier of the Dormant Flame, atop the Shrine of Eternal Flame.", only = {classes = {"SHAMAN"}}, title = "The Fire Spirit Stone"},
	{{"turnin", 94468, at = {1426, 87.94, 44.8}, who = "Bruegs Kindleborn"}, note = "Back through the tunnel to Bruegs' cave above the farm.", only = {classes = {"SHAMAN"}}, title = "Back to Bruegs Kindleborn"},
