	{{"accept", 312, at = {1426, 34.57, 51.65}, who = "Tundra MacGrann"}, {"complete", 312, at = {1426, 38.51, 53.93}}, {"turnin", 312, at = {1426, 34.57, 51.65}, who = "Tundra MacGrann"}, note = "Tundra MacGrann camps in Chill Breeze Valley, south of Brewnall. His meats are in the locker in Old Icebeard's cave, north-east of his camp. Old Icebeard is an elite yeti: wait out of sight until he wanders off on his patrol, then take the meats and leave before he comes back. You don't need to fight him.", title = "Tundra MacGrann"},
