	{{"turnin", 5637, at = {1453, 49.53, 44.6}, who = "High Priestess Laurena"}, note = "High Priestess Laurena is in the Cathedral of Light.", only = {classes = {"PRIEST"}, races = {"Dwarf"}}, title = "Desperate Prayer"},
	{{"turnin", 1715, at = {1453, 39.22, 85.23}, who = "Gakin the Darkbinder"}, {"accept", 1688, at = {1453, 39.22, 85.23}, who = "Gakin the Darkbinder"}, note = "Gakin the Darkbinder waits in the cellar of the Slaughtered Lamb, in the Mage Quarter.", only = {classes = {"WARLOCK"}}, title = "Gakin the Darkbinder"},
	{{"complete", 1688, at = {1429, 71.01, 80.77}}, note = "Leave Stormwind by the main gate, go south to Goldshire and east along the road to the Brackwell Pumpkin Patch. Surena Caledon (level 9) stands by its farmhouse.", only = {classes = {"WARLOCK"}}, title = "Surena Caledon"},
	{{"turnin", 1688, at = {1453, 39.22, 85.23}, who = "Gakin the Darkbinder"}, {"accept", 1689, at = {1453, 39.22, 85.23}, who = "Gakin the Darkbinder"}, {"complete", 1689}, {"turnin", 1689, at = {1453, 39.22, 85.23}, who = "Gakin the Darkbinder"}, note = "Back to Gakin. Use the Bloodstone Choker at the summoning circle in the Slaughtered Lamb's cellar and defeat the voidwalker it calls. Westfall is next, west of Goldshire.", only = {classes = {"WARLOCK"}}, title = "The Binding"},
