	{{"turnin", 6344, at = {1438, 56.26, 92.44}, who = "Nessa Shadowsong"}, {"accept", 6341, at = {1438, 56.26, 92.44}, who = "Nessa Shadowsong"}, {"goto", 1438, 58.4, 94.02, "Get the flight path at Rut'theran Village"}, {"turnin", 6341, at = {1438, 58.4, 94.02}, who = "Vesprystus"}, {"accept", 6342, at = {1438, 58.4, 94.02}, who = "Vesprystus"}, {"note", "Fly to Auberdine"}, note = "Take the portal down to Rut'theran Village. Nessa stands on the dock, Vesprystus by the hippogryphs. Once you have Flight to Auberdine, talk to Vesprystus again and choose the flight to Auberdine: it is free and lands beside Laird. If the flight map opens instead, close it and talk to him again holding Shift.", title = "Rut'theran Village"},
	{{"goto", 1439, 36.34, 45.58, "Get the flight path at Auberdine"}, {"turnin", 6342, at = {1439, 36.77, 44.28}, who = "Laird"}, {"accept", 6343, at = {1439, 36.77, 44.28}, who = "Laird"}, note = "Learn the flight path from Caylais Moonfeather where you land. Laird's fish stall is just north of her, by the docks.", title = "Auberdine"},
