	{{"turnin", 5921, at = {1450, 56.21, 30.64}, who = "Dendrite Starblaze"}, {"accept", 5929, at = {1450, 56.21, 30.64}, who = "Dendrite Starblaze"}, {"complete", 5929, at = {1450, 39.1, 27.5}}, {"turnin", 5929, at = {1450, 56.21, 30.64}, who = "Dendrite Starblaze"}, {"accept", 5931, at = {1450, 56.21, 30.64}, who = "Dendrite Starblaze"}, {"goto", 1450, 48.1, 67.34, "Get the flight path at Moonglade"}, {"note", "Fly to Rut'theran Village"}, note = "Cast Teleport: Moonglade. Dendrite Starblaze is in Nighthaven; the Great Bear Spirit sits in the woods to the north-west. Learn the Moonglade flight path in Nighthaven and fly to Rut'theran Village (by way of Auberdine).", only = {classes = {"DRUID"}}, title = "Moonglade"},
	{{"turnin", 6343, at = {1438, 56.26, 92.44}, who = "Nessa Shadowsong"}, {"turnin", 5931, at = {1457, 35.37, 8.4}, who = "Mathrengyl Bearwalker"}, {"accept", 6001, at = {1457, 35.37, 8.4}, who = "Mathrengyl Bearwalker"}, note = "Nessa stands on the Rut'theran dock where you land. Then take the portal up to Mathrengyl in the Cenarion Enclave.", only = {classes = {"DRUID"}}, title = "Back to Darnassus"},
	{{"note", "Fly to Auberdine"}, {"note", "Use Cenarion Moondust"}, {"complete", 6001}, note = "Go back down to Rut'theran Village and fly to Auberdine. The Moonkin Stone stands in the hills just east of the village: use the Cenarion Moondust there, defeat Lunaclaw and speak to the Lunaclaw Spirit.", only = {classes = {"DRUID"}}, title = "The Moonkin Stone"},
	{{"note", "Fly to Rut'theran Village"}, {"turnin", 6001, at = {1457, 35.37, 8.4}, who = "Mathrengyl Bearwalker"}, {"note", "Fly to Auberdine"}, note = "Fly to Rut'theran Village once more and take the portal up to Mathrengyl, then fly back to Auberdine for the boat.", only = {classes = {"DRUID"}}, title = "Body and Heart"},
	{{"goto", 1439, 30.76, 40.92, "Boat to Stormwind"}, {"note", "From Stormwind Harbor, head through the city gates into Elwynn Forest and follow the road west to Westfall."}, note = "Take the boat to Stormwind from Auberdine's docks.", title = "Boat to Stormwind"},
