	{{"goto", 1420, 54.5, 72, "Road to Silverpine"}, note = "The zeppelin lands at the towers outside the Ruins of Lordaeron. Walk west along the road past the ruins and south into Silverpine Forest; follow the road to the Sepulcher.", title = "Into Silverpine"},
