	{{"note", "Train new spells at your class trainer"}, note = "Follow the road north out of Silverpine into Tirisfal Glades and on to Brill: Shari Stilwell trains Paladins there. The zeppelin towers are a short walk south down the road.", only = {classes = {"PALADIN"}}, title = "Brill"},
	{{"goto", 1420, 60.7, 58.9, "Zeppelin tower"}, note = "Follow the road north out of Silverpine into Tirisfal Glades and east to the zeppelin towers outside the Ruins of Lordaeron. Take the zeppelin to Orgrimmar.", title = "Zeppelin to Orgrimmar"},
