Pathwise.RegisterRoute({category = "Leveling", faction = "Horde", id = "forever/horde/04-the-barrens", levels = {19, 24}, map = 1413, next = "forever/horde/05-stonetalon-mountains", title = "The Barrens", steps = {
	{{"note", "Fly to Ratchet"}, note = "Doras, the wind rider master, stands on the tower in the Valley of Strength.", title = "Fly to Ratchet"},
