	{{"complete", 92706, at = {1413, 63.7, 38.7}, optional = true}, note = "Bruuz swims in the harbour just off Ratchet's docks. Bruuz is elite: grouping up is advised.", title = "Bruuz"},
	{{"complete", 895, at = {1413, 64.22, 47.13}}, note = "The pirates camp on the beach south of Ratchet; Baron Longshore stands at its southern end.", title = "Baron Longshore"},
	{{"complete", 891, at = {1413, 62.01, 51.66}}, note = "Northwatch Hold, on the coast further south. The Theramore Marines and Preservers (15-16) drop the medals; Captain Fairmount (20) and the two cannoneers (19) stand in the keep and on its walls, and they are why the hold waits until now.", title = "Northwatch Hold"},
	{{"accept", 898, at = {1413, 61.96, 54.96}, who = "Gilthares Firebough"}, {"complete", 898}, note = "Gilthares Firebough is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to Ratchet.", title = "Free From the Hold"},
	{{"turnin", 898, at = {1413, 62.29, 39.03}, who = "Captain Thalo'thas Brightsun"}, {"turnin", 891, at = {1413, 62.29, 39.03}, who = "Captain Thalo'thas Brightsun"}, {"turnin", 895, at = {1413, 62.68, 36.23}, who = "Gazlowe"}, {"turnin", 92706, at = {1413, 62.68, 36.23}, optional = true, who = "Gazlowe"}, title = "Ratchet"},
	{{"complete", 865, at = {1413, 61.23, 34.04}}, note = "Sunscale Scytheclaws hunt the plains south of the Crossroads, around the Raptor Grounds; they drop the horns. Hand them in on your next pass through Ratchet.", title = "Raptor Horns"},
