	{{"complete", 6127, at = {1413, 48.4, 18.9}}, {"turnin", 6127, at = {1413, 52.26, 31.93}, who = "Tonga Runetotem"}, {"accept", 6128, at = {1413, 52.26, 31.93}, who = "Tonga Runetotem"}, {"have", 2449, 5, at = {1413, 51.39, 30.2}, name = "Earthroot", optional = true}, note = "Head north from the Crossroads to Dreadmist Peak and fill the Empty Dreadmist Peak Sampler at the Dreadmist Peak Pool, then back to Tonga Runetotem in the Crossroads. No Herbalism? Hula'mahi beside him sells Earthroot, three at a time until he restocks.", only = {classes = {"DRUID"}, races = {"Tauren"}}, title = "Dreadmist Peak"},
	{{"level", 20}, note = "The level-20 class quests in Orgrimmar (Sorek, Searn Firewarder, the Warlock and Rogue trainers) are only offered from level 20, so finish the level here before you fly. The Thunderhawk Hatchlings (18) on the plains south-west of the Crossroads and the Kolkar (14-15) at the Stagnant Oasis are the nearest mobs worth killing; you need well under a level.", title = "Level 20"},
	{{"note", "Fly to Orgrimmar"}, {"note", "Train new spells at your class trainer"}, {"accept", 1823, at = {1454, 80.39, 32.38}, only = {classes = {"WARRIOR"}}, who = "Sorek"}, {"accept", 1528, at = {1454, 37.96, 37.73}, only = {classes = {"SHAMAN"}}, who = "Searn Firewarder"}, note = "Fly to Orgrimmar to train your level 20 ranks. Sorek is in the Valley of Honor, Searn Firewarder in the Valley of Wisdom.", only = {classes = {"WARRIOR", "HUNTER", "ROGUE", "PRIEST", "SHAMAN", "MAGE", "WARLOCK"}}, title = "Orgrimmar"},
	{{"accept", 1507, at = {1454, 48.25, 45.28}, who = "Gan'rul Bloodeye"}, {"turnin", 1507, at = {1454, 47.06, 46.43}, who = "Cazul"}, {"accept", 1508, at = {1454, 47.06, 46.43}, who = "Cazul"}, {"turnin", 1508, at = {1454, 37.04, 59.45}, who = "Zankaja"}, {"accept", 1509, at = {1454, 37.04, 59.45}, who = "Zankaja"}, note = "The Cleft of Shadow is the canyon under the Valley of Strength.", only = {classes = {"WARLOCK"}}, title = "Gan'rul Bloodeye"},
	{{"accept", 2460, at = {1454, 43.05, 53.74}, who = "Shenthul"}, {"complete", 2460}, {"turnin", 2460, at = {1454, 43.05, 53.74}, who = "Shenthul"}, {"accept", 2458, at = {1454, 43.05, 53.74}, who = "Shenthul"}, note = "Shenthul stands in the Cleft of Shadow. Target him and type /salute to finish The Shattered Salute. Before leaving town, learn Lockpicking and bring Thieves' Tools; practise before attempting the tower lockbox. Keep the Flare Gun supplied with Deep Cover. Gallywix is elite, so arrange help or leave that optional part for later.", only = {classes = {"ROGUE"}}, title = "Shenthul"},
	{{"accept", 5680, at = {1454, 35.59, 87.82}, only = {races = {"Troll"}}, who = "Ur'kyo"}, {"turnin", 5680, at = {1454, 35.59, 87.82}, only = {races = {"Troll"}}, who = "Ur'kyo"}, {"accept", 5646, at = {1454, 35.59, 87.82}, only = {races = {"Scourge"}}, who = "Ur'kyo"}, note = "Ur'kyo stands in the Valley of Spirits, on the city's west side.", only = {classes = {"PRIEST"}}, title = "Ur'kyo"},
