	{{"turnin", 850, at = {1413, 45.34, 28.41}, who = "Regthar Deathgate"}, {"accept", 851, at = {1413, 45.34, 28.41}, who = "Regthar Deathgate"}, title = "Regthar Deathgate"},
	{{"turnin", 1510, at = {1442, 73.25, 95.13}, who = "Ken'zigla"}, {"accept", 1511, at = {1442, 73.25, 95.13}, who = "Ken'zigla"}, note = "Ken'zigla lives in Malaka'jin, the troll village just inside Stonetalon at the end of the road west from Regthar.", only = {classes = {"WARLOCK"}}, title = "Ken'zigla"},
	{{"accept", 95494, at = {1413, 43.8, 12.21}, who = "Vrang Wildgore"}, {"accept", 95507, at = {1413, 43.8, 12.21}, who = "Vrang Wildgore"}, note = "North to the Dry Hills. Vrang Wildgore camps below the hills; Walton, the hermit on the ridge behind him, has work for you only once Vrang sends you up.", title = "Vrang Wildgore"},
