	{{"turnin", 95621, at = {1413, 42.01, 11.44}, who = "Walton"}, {"accept", 95508, at = {1413, 42.01, 11.44}, who = "Walton"}, {"complete", 95508}, {"turnin", 95508, at = {1413, 42.01, 11.44}, who = "Walton"}, title = "Walton"},
	{{"have", 15883, 1, at = {1413, 56.67, 8.32}, name = "Half Pendant of Aquatic Agility"}, note = "The Strange Lockbox lies at the north edge of the Sludge Fen, by the Venture Co. tower. It holds the Half Pendant of Aquatic Agility for Trial of the Sea Lion.", only = {classes = {"DRUID"}, races = {"Tauren"}}, title = "Strange Lockbox"},
	{{"accept", 858, at = {1413, 56.52, 7.45}, who = "Wizzlecrank's Shredder"}, {"complete", 858, at = {1413, 56.27, 8.58}}, {"turnin", 858, at = {1413, 56.52, 7.45}, who = "Wizzlecrank's Shredder"}, {"accept", 863, at = {1413, 56.52, 7.45}, who = "Wizzlecrank's Shredder"}, note = "East to the Sludge Fen. Wizzlecrank's Shredder stands inside the Venture Co. camp; Supervisor Lugwizzle carries the key.", title = "Ignition"},
	{{"complete", 863}, note = "Wizzlecrank drives his shredder out of the camp: stay with him and kill whatever attacks him. Sputtervalve takes it in Ratchet.", title = "The Escape"},
	{{"turnin", 2458, at = {1413, 55.44, 5.56}, who = "Taskmaster Fizzule"}, {"accept", 2478, at = {1413, 55.44, 5.56}, optional = true, who = "Taskmaster Fizzule"}, note = "Fizzule is by the Venture Co. tower north of the Sludge Fen. Use Flare Gun to fire TWO flares before approaching him, then target him and /salute. Keep that order: he attacks strangers who have not signalled first.", only = {classes = {"ROGUE"}}, title = "Taskmaster Fizzule"},
	{{"goto", 1413, 54.8, 5.6, "Venture Co. tower", optional = true}, {"complete", 2478, at = {1413, 54.8, 5.97}, optional = true}, note = "Pickpocket Foreman Silixiz for the tower key before opening the lockbox. Gallywix and his lockbox are at the top; the key does not open that box, which still needs Lockpicking. Gallywix is elite: grouping up is advised. If you postpone this optional job, resume it in the Class guide Poisons (Horde).", only = {classes = {"ROGUE"}}, title = "Mission: Possible But Not Probable"},
	{{"complete", 896, at = {1413, 59.63, 3.78}}, note = "The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the Cats Eye Emerald.", title = "Boulder Lode Mine"},
	{{"note", "Hearth to The Crossroads"}, {"turnin", 876, at = {1413, 51.62, 30.9}, who = "Darsok Swiftdagger"}, {"turnin", 6128, at = {1413, 52.26, 31.93}, only = {classes = {"DRUID"}, races = {"Tauren"}}, who = "Tonga Runetotem"}, {"accept", 6129, at = {1413, 52.26, 31.93}, only = {classes = {"DRUID"}, races = {"Tauren"}}, who = "Tonga Runetotem"}, title = "Hearth to the Crossroads"},
	{{"complete", 851, at = {1413, 53.06, 41.74}}, {"complete", 6129, at = {1413, 53.28, 37.96}, only = {classes = {"DRUID"}, races = {"Tauren"}}}, note = "Verog walks among the Kolkar at the Stagnant Oasis south-east of the Crossroads.", title = "Verog the Dervish"},
	{{"goto", 1413, 44.45, 59.15, "Get the flight path at Camp Taurajo"}, {"turnin", 3261, at = {1413, 44.86, 59.14}, who = "Jorn Skyseer"}, {"accept", 882, at = {1413, 44.86, 59.14}, who = "Jorn Skyseer"}, {"accept", 878, at = {1413, 44.55, 59.26}, who = "Mangletooth"}, {"turnin", 1511, at = {1413, 44.62, 59.27}, only = {classes = {"WARLOCK"}}, who = "Grunt Logmar"}, {"accept", 1515, at = {1413, 44.62, 59.27}, only = {classes = {"WARLOCK"}}, who = "Grunt Logmar"}, {"turnin", 1823, at = {1413, 44.67, 59.42}, only = {classes = {"WARRIOR"}}, who = "Ruga Ragetotem"}, {"accept", 1824, at = {1413, 44.67, 59.42}, only = {classes = {"WARRIOR"}}, who = "Ruga Ragetotem"}, {"accept", 893, at = {1413, 45.1, 57.68}, who = "Tatternack Steelforge"}, note = "Follow the Gold Road south to Camp Taurajo.", title = "Camp Taurajo"},
	{{"complete", 899, at = {1413, 45.09, 55.26}}, {"complete", 4921, at = {1413, 49.3, 50.3}}, {"complete", 878, at = {1413, 47.72, 52.79}}, {"have", 5075, 1, at = {1413, 43.81, 48.17}, name = "Blood Shard"}, {"have", 5099, 1, at = {1413, 46.13, 49.28}, name = "Hoof of Lakota'mani", optional = true}, {"accept", 883, optional = true}, note = "The Bristleback quilboar camps spread over the plains north of Camp Taurajo, either side of the Gold Road. Every Bristleback drops a tusk; Mankrik's wife lies at the north edge. Keep one Blood Shard. Lakota'mani, a grey kodo, sometimes wanders here: his hoof starts a quest.", title = "Bristleback camps"},
	{{"turnin", 1515, at = {1413, 43.3, 47.89}, who = "Grunt Dogran"}, {"accept", 1512, at = {1413, 43.3, 47.89}, who = "Grunt Dogran"}, note = "Dogran is chained up in the quilboar camp west of the road.", only = {classes = {"WARLOCK"}}, title = "Grunt Dogran"},
	{{"turnin", 878, at = {1413, 44.55, 59.26}, who = "Mangletooth"}, {"accept", 5052, at = {1413, 44.55, 59.26}, who = "Mangletooth"}, {"turnin", 5052, at = {1413, 44.55, 59.26}, who = "Mangletooth"}, {"accept", 879, at = {1413, 44.55, 59.26}, who = "Mangletooth"}, {"turnin", 883, at = {1413, 44.86, 59.14}, optional = true, who = "Jorn Skyseer"}, title = "Camp Taurajo"},
	{{"complete", 3281, at = {1413, 58.04, 53.87}}, note = "East across the plains toward the coast: the stolen silver lies in a raptor nest north-west of Northwatch Hold.", title = "Stolen Silver"},
	{{"turnin", 1528, at = {1413, 65.83, 43.78}, who = "Islen Waterseer"}, {"accept", 1530, at = {1413, 65.83, 43.78}, who = "Islen Waterseer"}, note = "Islen waits on the hill south of Ratchet, on your way north.", only = {classes = {"SHAMAN"}}, title = "Islen Waterseer"},
	{{"turnin", 896, at = {1413, 63.35, 38.45}, who = "Wharfmaster Dizzywig"}, {"turnin", 863, at = {1413, 62.98, 37.22}, who = "Sputtervalve"}, {"turnin", 865, at = {1413, 62.37, 37.62}, who = "Mebok Mizzyrix"}, {"note", "Sell and repair"}, title = "Ratchet"},
	{{"have", 10338, 1, at = {1413, 62.55, 33}, name = "Fresh Zhevra Carcass"}, {"complete", 882, at = {1413, 59.95, 30.21}}, note = "Ishamuhale, a big Sunscale raptor, only comes to a fresh kill: loot a Fresh Zhevra Carcass from a zhevra, then use it at the Dead Tree north-west of Ratchet, north of the road to the Crossroads, and be ready when he arrives.", title = "Ishamuhale"},
	{{"turnin", 899, at = {1413, 51.95, 31.58}, who = "Mankrik"}, {"turnin", 4921, at = {1413, 51.95, 31.58}, who = "Mankrik"}, {"accept", 95774, at = {1413, 51.95, 31.58}, who = "Mankrik"}, {"turnin", 3281, at = {1413, 51.93, 30.32}, who = "Gazrog"}, title = "The Crossroads"},
	{{"turnin", 851, at = {1413, 45.34, 28.41}, who = "Regthar Deathgate"}, {"accept", 852, at = {1413, 45.34, 28.41}, who = "Regthar Deathgate"}, title = "Regthar Deathgate"},
	{{"complete", 852, at = {1413, 46, 41.1}}, note = "Hezrul leads the Kolkar on the west shore of Lushwater Oasis, south of Regthar. Hand his head to Regthar on your last Crossroads stop.", title = "Hezrul Bloodmark"},
	{{"complete", 95774, at = {1413, 49.78, 45.75}}, note = "On the way back down the Gold Road to Camp Taurajo: the Razormane Raiders among the Bristleback camps, either side of the road north of the camp, carry Olgra's Adornments. Hand them to Mankrik on your last Crossroads stop.", title = "Olgra's Adornments"},
	{{"bind", "Camp Taurajo", at = {1413, 45.58, 59.04}, who = "Innkeeper Byula"}, {"turnin", 882, at = {1413, 44.86, 59.14}, who = "Jorn Skyseer"}, {"accept", 907, at = {1413, 44.86, 59.14}, who = "Jorn Skyseer"}, {"accept", 6382, at = {1413, 44.86, 59.14}, who = "Jorn Skyseer"}, note = "Down the Gold Road to Camp Taurajo again.", title = "Camp Taurajo"},
	{{"complete", 907, at = {1413, 43.81, 60.64}}, {"have", 5102, 1, at = {1413, 44.2, 62}, name = "Owatanka's Tailspike", optional = true}, {"accept", 884, optional = true}, note = "Thunderheads graze on the plains just south of Camp Taurajo. Owatanka, a blue thunder lizard, roams among them: his Tailspike starts a quest.", title = "Enraged Thunder Lizards"},
	{{"turnin", 907, at = {1413, 44.86, 59.14}, who = "Jorn Skyseer"}, {"accept", 913, at = {1413, 44.86, 59.14}, who = "Jorn Skyseer"}, {"turnin", 884, at = {1413, 44.86, 59.14}, optional = true, who = "Jorn Skyseer"}, title = "Jorn Skyseer"},
	{{"complete", 913, at = {1413, 46.69, 61.49}}, note = "Thunderhawk Cloudscrapers circle over the same plains south of the camp.", title = "Cry of the Thunderhawk"},
	{{"turnin", 913, at = {1413, 44.86, 59.14}, who = "Jorn Skyseer"}, title = "Jorn Skyseer"},
	{{"complete", 868, at = {1413, 44.94, 69.4}}, {"have", 5138, 1, at = {1413, 42, 70}, name = "Harvester's Head", optional = true}, {"accept", 897, optional = true}, note = "South of Camp Taurajo the Silithid Mounds dot the Field of Giants; the eggs lie in them, and Silithid Swarmers come out to defend them. Silithid Harvesters are rare: if you see one, kill it for its head.", title = "Field of Giants"},
	{{"accept", 843, at = {1413, 45.89, 77}, who = "Gann Stonespire"}, {"accept", 98093, at = {1413, 47.8, 77.6}, who = "Sulhasa"}, {"turnin", 1530, at = {1413, 43.42, 77.41}, only = {classes = {"SHAMAN"}}, who = "Brine"}, {"accept", 1535, at = {1413, 43.42, 77.41}, only = {classes = {"SHAMAN"}}, who = "Brine"}, {"complete", 1535, at = {1413, 44.3, 76.8}, only = {classes = {"SHAMAN"}}}, {"turnin", 1535, at = {1413, 43.42, 77.41}, only = {classes = {"SHAMAN"}}, who = "Brine"}, {"accept", 1536, at = {1413, 43.42, 77.41}, only = {classes = {"SHAMAN"}}, who = "Brine"}, note = "Gann waits in a small camp further south, on the road toward Bael Modan.", title = "Gann Stonespire"},
	{{"goto", 1413, 42.5, 81, "Blackthorn Ridge"}, {"complete", 879, at = {1413, 45.12, 80.07}}, {"complete", 893, at = {1413, 41.84, 79.22}}, {"complete", 98093, at = {1413, 43.19, 78.39}}, {"have", 5103, 1, at = {1413, 44.81, 78.88}, name = "Washte Pawne's Feather", optional = true}, {"accept", 885, optional = true}, note = "West of Gann, the Razormane hold Blackthorn Ridge. Kuz is on the east side, Nak to the south, Lok Orcbane at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; Hagg Taurenbane, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. Stormhide lizards and Hecklefang Stalkers roam the plain between Gann and the ridge. Washte Pawne, a rare red wind serpent, flies over the ridge: its feather starts a quest.", title = "Blackthorn Ridge"},
	{{"complete", 843, at = {1413, 47.06, 83.87}}, note = "South of Gann, the Bael'dun dwarves dig at Bael Modan. Excavators and Foremen work the pit; Prospector Khazgorm (26) carries the journal: pull him alone.", title = "Bael Modan"},
	{{"turnin", 843, at = {1413, 45.89, 77}, who = "Gann Stonespire"}, {"accept", 846, at = {1413, 45.89, 77}, who = "Gann Stonespire"}, {"turnin", 98093, at = {1413, 47.8, 77.6}, who = "Sulhasa"}, title = "Gann Stonespire"},
	{{"complete", 846, at = {1413, 48.45, 83.77}}, note = "The Bael'dun Soldiers, Riflemen and Officers guard the fortress on the east side of the dig; all three items drop from them.", title = "Bael'dun fortress"},
	{{"turnin", 846, at = {1413, 45.89, 77}, who = "Gann Stonespire"}, {"accept", 849, at = {1413, 45.89, 77}, who = "Gann Stonespire"}, title = "Gann Stonespire"},
	{{"complete", 849, at = {1413, 46.97, 85.63}}, note = "The dwarves' flying machine sits on its platform inside the dig site.", title = "The flying machine"},
	{{"turnin", 849, at = {1413, 45.89, 77}, who = "Gann Stonespire"}, title = "Gann Stonespire"},
	{{"complete", 1824, at = {1413, 45.39, 72.55}}, note = "The antennae vanish fifteen minutes after they drop, so gather them now, on the way back north: kill the Silithid Swarmers and Creepers at the Field of Giants' mounds until you have five, then hearth to Camp Taurajo straight away.", only = {classes = {"WARRIOR"}}, title = "Twitching Antennae"},
	{{"note", "Hearth to Camp Taurajo"}, {"turnin", 879, at = {1413, 44.55, 59.26}, who = "Mangletooth"}, {"accept", 906, at = {1413, 44.55, 59.26}, who = "Mangletooth"}, {"turnin", 893, at = {1413, 45.1, 57.68}, who = "Tatternack Steelforge"}, {"turnin", 885, at = {1413, 44.86, 59.14}, optional = true, who = "Jorn Skyseer"}, {"turnin", 897, at = {1413, 44.86, 59.14}, optional = true, who = "Jorn Skyseer"}, {"turnin", 1824, at = {1413, 44.67, 59.42}, only = {classes = {"WARRIOR"}}, who = "Ruga Ragetotem"}, {"accept", 1825, at = {1413, 44.67, 59.42}, only = {classes = {"WARRIOR"}}, who = "Ruga Ragetotem"}, {"note", "Sell and repair"}, title = "Camp Taurajo"},
	{{"note", "Fly to Crossroads"}, {"turnin", 906, at = {1413, 51.5, 30.87}, who = "Thork"}, {"turnin", 868, at = {1413, 51.07, 29.63}, who = "Korran"}, {"turnin", 95774, at = {1413, 51.95, 31.58}, who = "Mankrik"}, title = "The Crossroads"},
	{{"turnin", 852, at = {1413, 45.34, 28.41}, who = "Regthar Deathgate"}, title = "Regthar Deathgate"},
	{{"turnin", 1825, at = {1413, 57.23, 30.34}, who = "Thun'grim Firegaze"}, {"note", "He offers Brutal Armor next (1838, level 30): it needs Razorfen Kraul and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide Brutal Armor covers it."}, note = "Thun'grim camps beside the road east of the Crossroads.", only = {classes = {"WARRIOR"}}, title = "Thun'grim Firegaze"},
	{{"note", "Fly to Orgrimmar"}, {"note", "Train new spells at your class trainer"}, note = "Fly to Orgrimmar to train.", only = {classes = {"WARRIOR", "HUNTER", "ROGUE", "PRIEST", "SHAMAN", "MAGE", "WARLOCK"}}, title = "Orgrimmar"},
	{{"note", "Fly to Camp Taurajo"}, {"goto", 1456, 47, 49.83, "Get the flight path at Thunder Bluff"}, {"note", "Train new spells at your class trainer"}, note = "Alodan the Hopeful teaches Paladins in Thunder Bluff. You have no flight path there yet: fly to Camp Taurajo, head west through Mulgore and up a lift, and take the flight path from Tal on the central rise.", only = {classes = {"PALADIN"}}, title = "Thunder Bluff"},
	{{"turnin", 1512, at = {1454, 48.25, 45.28}, who = "Gan'rul Bloodeye"}, {"accept", 1513, at = {1454, 48.25, 45.28}, who = "Gan'rul Bloodeye"}, {"note", "Use Dogran's Pendant"}, {"complete", 1513, at = {1454, 49.4, 50}}, {"turnin", 1513, at = {1454, 48.25, 45.28}, who = "Gan'rul Bloodeye"}, note = "Gan'rul Bloodeye stands in the Cleft of Shadow. Use Dogran's Pendant on the summoning circle there and defeat the succubus to bind her.", only = {classes = {"WARLOCK"}}, title = "The Binding"},
	{{"turnin", 2478, at = {1454, 43.05, 53.74}, optional = true, who = "Shenthul"}, {"accept", 2479, at = {1454, 43.05, 53.74}, optional = true, who = "Shenthul"}, only = {classes = {"ROGUE"}}, title = "Shenthul"},
	{{"note", "Fly to Thunder Bluff"}, {"note", "Train new spells at your class trainer"}, {"accept", 98340, at = {1456, 76.48, 27.22}, who = "Turak Runetotem"}, note = "Fly to Thunder Bluff to train: Turak Runetotem is on Elder Rise.", only = {classes = {"DRUID"}}, title = "The Great Cat Spirit"},
	{{"complete", 30, at = {1450, 36, 41.42}, only = {races = {"Tauren"}}}, {"turnin", 30, at = {1450, 56.21, 30.64}, only = {races = {"Tauren"}}, who = "Dendrite Starblaze"}, {"accept", 31, at = {1450, 56.21, 30.64}, only = {races = {"Tauren"}}, who = "Dendrite Starblaze"}, {"turnin", 6129, at = {1450, 56.21, 30.64}, only = {races = {"Tauren"}}, who = "Dendrite Starblaze"}, {"accept", 6130, at = {1450, 56.21, 30.64}, only = {races = {"Tauren"}}, who = "Dendrite Starblaze"}, {"turnin", 94913, at = {1450, 56.21, 30.64}, only = {races = {"Skyborne"}}, who = "Dendrite Starblaze"}, {"turnin", 98340, at = {1450, 56.21, 30.64}, who = "Dendrite Starblaze"}, {"accept", 98405, at = {1450, 56.21, 30.64}, only = {races = {"Tauren"}}, who = "Dendrite Starblaze"}, {"accept", 98341, at = {1450, 56.21, 30.64}, only = {races = {"Skyborne"}}, who = "Dendrite Starblaze"}, note = "Cast Teleport: Moonglade. Tauren: join the two pendant halves at the Shrine of Remulos, on the north-west shore of the lake, before you see Dendrite Starblaze in Nighthaven.", only = {classes = {"DRUID"}}, title = "Moonglade"},
	{{"turnin", 98405, at = {1450, 58.39, 73.52}, only = {races = {"Tauren"}}, who = "Great Cat Spirit"}, {"accept", 98342, at = {1450, 58.39, 73.52}, only = {races = {"Tauren"}}, who = "Great Cat Spirit"}, {"turnin", 98341, at = {1450, 44.01, 73.48}, only = {races = {"Skyborne"}}, who = "Avatar of Saeyleenan"}, {"accept", 98404, at = {1450, 44.01, 73.48}, only = {races = {"Skyborne"}}, who = "Avatar of Saeyleenan"}, {"complete", 98342, at = {1450, 72.4, 66}, only = {races = {"Tauren"}}}, {"complete", 98404, at = {1450, 72.4, 66}, only = {races = {"Skyborne"}}}, {"turnin", 98342, at = {1450, 58.39, 73.52}, only = {races = {"Tauren"}}, who = "Great Cat Spirit"}, {"accept", 98739, at = {1450, 58.39, 73.52}, only = {races = {"Tauren"}}, who = "Great Cat Spirit"}, {"turnin", 98404, at = {1450, 44.01, 73.48}, only = {races = {"Skyborne"}}, who = "Avatar of Saeyleenan"}, {"accept", 98738, at = {1450, 44.01, 73.48}, only = {races = {"Skyborne"}}, who = "Avatar of Saeyleenan"}, note = "Tauren: the Great Cat Spirit waits on the southern hill above the bridge. Skyborne: the Avatar of Saeyleenan stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the Relic of the Silent Shadow lies at the foot of the white cat statue.", only = {classes = {"DRUID"}}, title = "The Stormrage Barrow Dens"},
	{{"turnin", 98739, at = {1450, 56.21, 30.64}, only = {races = {"Tauren"}}, who = "Dendrite Starblaze"}, {"turnin", 98738, at = {1450, 56.21, 30.64}, only = {races = {"Skyborne"}}, who = "Dendrite Starblaze"}, {"accept", 98362, at = {1450, 56.21, 30.64}, who = "Dendrite Starblaze"}, only = {classes = {"DRUID"}}, title = "Dendrite Starblaze"},
	{{"note", "Fly to Thunder Bluff"}, {"turnin", 31, at = {1456, 76.48, 27.22}, only = {races = {"Tauren"}}, who = "Turak Runetotem"}, {"turnin", 6130, at = {1456, 76.48, 27.22}, only = {races = {"Tauren"}}, who = "Turak Runetotem"}, {"turnin", 98362, at = {1456, 76.48, 27.22}, who = "Turak Runetotem"}, only = {classes = {"DRUID"}}, title = "Turak Runetotem"},
