Pathwise.RegisterRoute({category = "Leveling", faction = "Horde", id = "forever/horde/05-stonetalon-mountains", levels = {23, 25}, map = 1442, next = "forever/horde/06-hillsbrad-foothills", title = "Stonetalon Mountains & Ashenvale", steps = {
	{{"turnin", 6541, at = {1413, 48.12, 5.42}, who = "Kadrak"}, {"accept", 6543, at = {1413, 48.12, 5.42}, who = "Kadrak"}, {"have", 16746, 1, name = "Warsong Report"}, note = "From the Crossroads follow the road north. Kadrak stands on the watch tower of the Mor'shan Rampart where the road enters Ashenvale. Open the Bundle of Reports he gives you.", title = "Kadrak"},
	{{"complete", 6543, at = {1440, 71.05, 68.36}}, note = "Keep north on the road. The Warsong Scout waits at the Warsong lumber camp, south of Splintertree.", title = "Warsong Scout"},
	{{"goto", 1440, 73.18, 61.59, "Get the flight path at Splintertree Post"}, {"bind", "Splintertree Post", at = {1440, 73.99, 60.65}, who = "Innkeeper Kaylisk"}, {"note", "Sell and repair"}, note = "Splintertree Post is just north up the road.", title = "Splintertree Post"},
	{{"turnin", 6382, at = {1440, 73.78, 61.46}, who = "Senani Thunderheart"}, {"accept", 6383, at = {1440, 73.78, 61.46}, who = "Senani Thunderheart"}, {"turnin", 6383, at = {1440, 73.78, 61.46}, who = "Senani Thunderheart"}, {"note", "Senani's hunt targets (Ursangous, Shadumbra, Sharptalon) are for the next Ashenvale visit, at 27."}, note = "Senani Thunderheart stands at Night Run, the Warsong camp just north-east of Splintertree, beside the hunt board.", title = "Night Run"},
	{{"complete", 6543, at = {1440, 81.83, 53.51}}, note = "The Warsong Outrider patrols the road east of Night Run toward the Satyrnaar.", title = "Warsong Outrider"},
	{{"accept", 98251, at = {1440, 40.4, 61.5}, who = "Va'xug Firefure"}, {"complete", 98251, at = {1440, 39.95, 63.48}}, {"turnin", 98251, at = {1440, 40.43, 61.48}, who = "Va'xug Firefure"}, {"accept", 98252, at = {1440, 40.43, 61.48}, who = "Va'xug Firefure"}, note = "On the way west, Va'xug Firefure is stuck in a ravine south of the main road, south-east of Astranaar. Shadowhorn Stags and Ashenvale Bears roam the woods all around it.", title = "Va'xug Firefure"},
	{{"turnin", 98252, at = {1440, 38.2, 58.1}, who = "Eye of Kilrogg"}, note = "Steer Va'xug's Eye of Kilrogg out of the ravine to the main road within four minutes; if the channel breaks, ask Va'xug again.", title = "A Void Path"},
	{{"goto", 1440, 12.24, 33.8, "Get the flight path at Zoram'gar Outpost"}, {"complete", 6543, at = {1440, 12.22, 34.22}}, {"accept", 6442, at = {1440, 11.69, 34.91}, who = "Marukai"}, note = "Head west along the main road across Ashenvale, past Astranaar (Alliance: keep to the road), to the coast. Zoram'gar Outpost is on the Zoram Strand in the north-west. Its other quests are for the next visit, at 27.", title = "Zoram'gar Outpost"},
	{{"complete", 6442, at = {1440, 11.84, 31.86}}, note = "Every Wrathtail naga along the strand north of the outpost drops heads.", title = "Naga heads"},
	{{"turnin", 6442, at = {1440, 11.69, 34.91}, who = "Marukai"}, title = "Zoram'gar Outpost"},
	{{"note", "Fly to Splintertree Post"}, {"turnin", 6543, at = {1413, 48.12, 5.42}, who = "Kadrak"}, note = "Fly to Splintertree Post and head south down the road to the Mor'shan Rampart.", title = "Back to Kadrak"},
	{{"accept", 1058, at = {1442, 74.54, 97.94}, who = "Witch Doctor Jin'Zil"}, note = "Head south to the Crossroads, then west along the road out of the Barrens into Stonetalon. The troll village of Malaka'jin sits at the entrance of the canyon.", title = "Malaka'jin"},
	{{"turnin", 1483, at = {1442, 58.99, 62.6}, who = "Ziz Fizziks"}, {"accept", 1093, at = {1442, 58.99, 62.6}, who = "Ziz Fizziks"}, note = "The road climbs north as the Webwinder Path. Ziz Fizziks has a hut where the road forks east to Windshear Crag.", title = "Ziz Fizziks"},
	{{"complete", 1093, at = {1442, 62.51, 53.84}}, {"accept", 1090, at = {1442, 71.87, 60}, who = "Piznik"}, {"complete", 1090}, {"turnin", 1090, at = {1442, 71.87, 60}, who = "Piznik"}, {"accept", 1092, at = {1442, 71.87, 60}, who = "Piznik"}, note = "East of Ziz, the Venture Company is clear-cutting Windshear Crag; one of the Operators carries the blueprints. Piznik mines in the small mine on the east side: stay with him while he mines, Venture Co. thugs come for him.", title = "Windshear Crag"},
	{{"turnin", 1092, at = {1442, 58.99, 62.6}, who = "Ziz Fizziks"}, {"turnin", 1093, at = {1442, 58.99, 62.6}, who = "Ziz Fizziks"}, {"accept", 1094, at = {1442, 58.99, 62.6}, who = "Ziz Fizziks"}, title = "Ziz Fizziks"},
	{{"goto", 1442, 45.12, 59.84, "Get the flight path at Sun Rock Retreat"}, {"bind", "Sun Rock Retreat", at = {1442, 47.47, 62.13}, who = "Innkeeper Jayka"}, {"accept", 5881, at = {1442, 47.2, 61.16}, who = "Maggran Earthbinder"}, {"accept", 6282, at = {1442, 47.2, 61.16}, who = "Maggran Earthbinder"}, {"accept", 86576, at = {1442, 47.2, 61.16}, who = "Maggran Earthbinder"}, {"accept", 1087, at = {1442, 45.94, 60.42}, who = "Braelyn Firehand"}, {"accept", 6393, at = {1442, 47.36, 64.25}, who = "Tsunaman"}, {"accept", 6562, at = {1442, 47.36, 64.25}, who = "Tsunaman"}, {"accept", 6301, at = {1442, 47.46, 58.38}, who = "Tammra Windfield"}, {"note", "Sell and repair"}, note = "Follow the road west to Sun Rock Retreat.", title = "Sun Rock Retreat"},
	{{"complete", 6301, at = {1442, 49.74, 45.11}}, note = "The Gaea Seeds lie in the grass around the southern shore of Mirkfallon Lake, north of Sun Rock.", title = "Gaea Seeds"},
	{{"complete", 1058, at = {1442, 46.76, 38.18}}, {"complete", 1087, at = {1442, 38.22, 11.42}}, note = "Follow the road north toward Stonetalon Peak. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there.", title = "Stonetalon Peak"},
	{{"note", "Hearth to Sun Rock Retreat"}, {"turnin", 6301, at = {1442, 47.46, 58.38}, who = "Tammra Windfield"}, {"accept", 6381, at = {1442, 47.46, 58.38}, who = "Tammra Windfield"}, {"turnin", 1087, at = {1442, 45.94, 60.42}, who = "Braelyn Firehand"}, {"note", "Braelyn's next quest, Ordanus, is on the Alliance side of Ashenvale. Skip it."}, title = "Sun Rock Retreat"},
	{{"complete", 6381, at = {1442, 37.8, 66.2}}, {"complete", 6393, at = {1442, 35.42, 66.27}}, {"complete", 6282, at = {1442, 35.25, 63.21}}, {"complete", 86576, at = {1442, 29.49, 68.63}}, note = "South-west of Sun Rock lies the burned Charred Vale. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop Incendrites. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south.", title = "The Charred Vale"},
	{{"turnin", 6381, at = {1442, 47.46, 58.38}, who = "Tammra Windfield"}, {"turnin", 6282, at = {1442, 47.2, 61.16}, who = "Maggran Earthbinder"}, {"turnin", 6393, at = {1442, 47.36, 64.25}, who = "Tsunaman"}, {"turnin", 86576, at = {1442, 47.22, 64.04}, who = "Mor'rogal"}, title = "Sun Rock Retreat"},
	{{"turnin", 1058, at = {1442, 74.54, 97.94}, who = "Witch Doctor Jin'Zil"}, note = "Head back down the Webwinder Path to Malaka'jin.", title = "Malaka'jin"},
	{{"goto", 1458, 63.25, 48.56, "Get the flight path at Undercity"}, {"complete", 93739, at = {1458, 58.05, 91.79}, only = {races = {"Skyborne"}}, optional = true}, note = "Head east to the Crossroads and fly to Orgrimmar. Take the zeppelin from the towers outside Orgrimmar to Tirisfal Glades; the Undercity lies below the Ruins of Lordaeron. The bat handler is in the Trade Quarter.", title = "To the Undercity"},
	{{"turnin", 5646, at = {1458, 49.26, 17.12}, who = "Aelthalyste"}, note = "Aelthalyste stands in the War Quarter.", only = {classes = {"PRIEST"}, races = {"Scourge"}}, title = "Aelthalyste"},
	{{"accept", 95884}, {"turnin", 95884, at = {1421, 58.1, 69.8}, who = "Offering Stone"}, {"accept", 95883, at = {1421, 58.09, 69.84}, who = "Offering Stone"}, {"complete", 95883, at = {1421, 58.06, 69.89}}, {"turnin", 95883, at = {1421, 58.09, 69.84}, who = "Offering Stone"}, note = "If you already know the Tarren Mill flight path, fly there and skip to Tarren Mill. Otherwise fly from the Undercity to the Sepulcher and head south down the road past Pyrewood. The Ravenclaw undead haunt the ruins of Beren's Peril east of the road in the south-east of the forest; a Ravenclaw Guardian drops the Note Scrap that leads to the Offering Stone.", title = "Beren's Peril"},
	{{"goto", 1421, 58.1, 69.8, "Offering Stone"}, {"accept", 95885, at = {1421, 58.09, 69.84}, optional = true, who = "Offering Stone"}, {"complete", 95885, at = {1421, 57.98, 70.08}, optional = true}, {"turnin", 95885, at = {1421, 58.09, 69.84}, optional = true, who = "Offering Stone"}, note = "Use the Tortured Soul at the Offering Stone for a willing sacrifice and kill the Tortured Soul that answers. The Tortured Soul is elite: grouping up is advised.", title = "The Offering of Blood"},
	{{"accept", 494, at = {1424, 20.79, 47.4}, optional = true, who = "Deathstalker Lesh"}, note = "Back on the road south. Where it turns east into Hillsbrad, Deathstalker Lesh waits at Southpoint Tower.", title = "Southpoint Tower"},
	{{"goto", 1424, 60.14, 18.62, "Get the flight path at Tarren Mill"}, {"bind", "Tarren Mill", at = {1424, 62.78, 19.03}, who = "Innkeeper Shay"}, note = "Follow the road east along the river, then north-east up into the hills to Tarren Mill.", title = "Tarren Mill"},
} })

Pathwise.RegisterRoute({category = "Leveling", faction = "Horde", id = "forever/horde/06-hillsbrad-foothills", levels = {24, 28}, map = 1424, next = "forever/horde/07-ashenvale", title = "Hillsbrad Foothills, Undercity & The Barrens", steps = {
	{{"bind", "Tarren Mill", at = {1424, 62.78, 19.03}, who = "Innkeeper Shay"}, {"turnin", 493, at = {1424, 61.44, 19.06}, who = "Apothecary Lydon"}, {"turnin", 494, at = {1424, 62.33, 20.45}, who = "High Executor Darthalia"}, {"accept", 498, at = {1424, 63.24, 20.66}, who = "Krusk"}, {"accept", 549, at = {1424, 62.63, 20.75}, who = "WANTED"}, {"accept", 567, at = {1424, 62.51, 19.74}, who = "Dangerous!"}, {"accept", 527, at = {1424, 62.33, 20.45}, who = "High Executor Darthalia"}, {"accept", 496, at = {1424, 61.44, 19.06}, who = "Apothecary Lydon"}, {"accept", 501, at = {1424, 61.44, 19.06}, who = "Apothecary Lydon"}, {"accept", 509, at = {1424, 61.44, 19.06}, who = "Apothecary Lydon"}, {"complete", 1536, at = {1424, 62.18, 20.79}, only = {classes = {"SHAMAN"}}}, note = "Tarren Mill is your base for this guide: the hearth brings you back here twice. Everyone stands around the town square.", title = "Tarren Mill"},
	{{"turnin", 2479, at = {1424, 61.63, 19.19}, optional = true, who = "Serge Hinott"}, {"accept", 2480, at = {1424, 61.63, 19.19}, optional = true, who = "Serge Hinott"}, {"complete", 2480, optional = true}, {"turnin", 2480, at = {1424, 61.63, 19.19}, optional = true, who = "Serge Hinott"}, {"note", "Poison chain unfinished? Resume your current stage in the Class guide Poisons (Horde); completed quests do not need restarting. Arrange a group for Gallywix, finish the Hinott follow-up, then return to this leveling guide."}, note = "After returning Mission: Possible But Not Probable to Shenthul, bring Hinott's Assistance to Serge Hinott in Tarren Mill. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill.", only = {classes = {"ROGUE"}}, title = "Serge Hinott"},
	{{"complete", 496, at = {1424, 54.3, 39.6}}, {"complete", 501, at = {1424, 54.3, 39.6}}, note = "West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop Creeper Ichor rarely; you need only one.", title = "Bears, creepers and lions"},
	{{"complete", 527, at = {1424, 36.82, 39.58}}, {"complete", 567, at = {1424, 35.88, 46.57}}, note = "The farms east of Hillsbrad town. Farmer Ray works the field by the northern farmhouse, Farmer Getz the one further south-east; Farmhands and Farmers are everywhere. Farmer Kalaba tends the field south of the farms.", title = "Hillsbrad Fields"},
	{{"turnin", 496, at = {1424, 61.44, 19.06}, who = "Apothecary Lydon"}, {"accept", 499, at = {1424, 61.44, 19.06}, who = "Apothecary Lydon"}, {"turnin", 499, at = {1424, 61.55, 19.14}, who = "Umpi"}, {"turnin", 501, at = {1424, 61.44, 19.06}, who = "Apothecary Lydon"}, {"accept", 502, at = {1424, 61.44, 19.06}, who = "Apothecary Lydon"}, {"turnin", 527, at = {1424, 62.33, 20.45}, who = "High Executor Darthalia"}, {"accept", 528, at = {1424, 62.33, 20.45}, who = "High Executor Darthalia"}, {"accept", 546, at = {1424, 62.11, 19.7}, who = "Deathguard Samsa"}, title = "Tarren Mill"},
	{{"turnin", 502, at = {1424, 32.66, 35.32}, who = "Stanley"}, note = "Stanley is Farmer Ray's dog, at the northern farmhouse in Hillsbrad Fields.", title = "Stanley"},
	{{"complete", 528, at = {1424, 30.27, 40.31}}, {"complete", 546, at = {1424, 30.3, 40.3}}, note = "The Peasants work the fields south of the farmhouses. Every Hillsbrad human drops skulls; the Peasants drop them most often.", title = "Peasants and skulls"},
	{{"turnin", 528, at = {1424, 62.33, 20.45}, who = "High Executor Darthalia"}, {"accept", 529, at = {1424, 62.33, 20.45}, who = "High Executor Darthalia"}, {"turnin", 546, at = {1424, 62.11, 19.7}, who = "Deathguard Samsa"}, {"accept", 98094, at = {1424, 62.33, 20.45}, who = "High Executor Darthalia"}, title = "Tarren Mill"},
	{{"complete", 549, at = {1424, 66.08, 45.6}}, note = "From Tarren Mill go south-east into the hills on the way to Durnholde Keep. Rogues and Watchmen hold the camps along the way.", title = "Syndicate camps"},
	{{"complete", 498, at = {1424, 75.33, 41.5}}, note = "Drull and Tog'thar are chained inside Durnholde Keep's courtyard buildings; open both locks.", title = "Durnholde Keep"},
	{{"turnin", 98094, at = {1424, 64.2, 54}, who = "Deathstalker Masoj"}, note = "Masoj hides on the hillside above Dun Garok, south of Durnholde, on the way down to the blossoms.", title = "Deathstalker Masoj"},
	{{"complete", 509, at = {1424, 63.95, 59.72}}, note = "South-west of Durnholde, the Mudsnout Blossoms grow on the hillsides above the river.", title = "Mudsnout Blossoms"},
	{{"note", "Hearth to Tarren Mill"}, {"turnin", 549, at = {1424, 62.33, 20.45}, who = "High Executor Darthalia"}, {"turnin", 498, at = {1424, 63.24, 20.66}, who = "Krusk"}, {"turnin", 509, at = {1424, 61.44, 19.06}, who = "Apothecary Lydon"}, {"accept", 513, at = {1424, 61.44, 19.06}, who = "Apothecary Lydon"}, title = "Tarren Mill"},
	{{"complete", 529, at = {1424, 32.11, 44.42}}, {"complete", 567, at = {1424, 32.62, 39.79}}, note = "The smithy stands in the middle of Hillsbrad town. Blacksmith Verringtan and his apprentices work at the forge; the Shipment of Iron is stacked beside it. Citizen Wilkes walks the street north of it.", title = "The smithy"},
	{{"turnin", 529, at = {1424, 62.33, 20.45}, who = "High Executor Darthalia"}, {"accept", 532, at = {1424, 62.33, 20.45}, who = "High Executor Darthalia"}, title = "Tarren Mill"},
	{{"complete", 532, at = {1424, 29.67, 41.64}}, {"complete", 567, at = {1424, 29.51, 42.41}}, note = "The town hall is on the west side of Hillsbrad. Magistrate Burnside (30) and Clerk Horrace Whitesteed are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town.", title = "Town hall"},
	{{"note", "Hearth to Tarren Mill"}, {"turnin", 532, at = {1424, 62.33, 20.45}, who = "High Executor Darthalia"}, {"accept", 539, at = {1424, 62.33, 20.45}, who = "High Executor Darthalia"}, title = "Tarren Mill"},
	{{"complete", 539, at = {1424, 32.4, 52.05}}, {"complete", 567, at = {1424, 31.8, 52.7}}, note = "The Azurelode Mine lies south of Hillsbrad town. Miners work the tunnels; Foreman Bonds (30) and Miner Hackett (29) are deep inside.", title = "Azurelode Mine"},
	{{"turnin", 539, at = {1424, 62.33, 20.45}, who = "High Executor Darthalia"}, {"turnin", 567, at = {1424, 62.33, 20.45}, who = "High Executor Darthalia"}, title = "Tarren Mill"},
	{{"note", "Fly to Undercity"}, {"turnin", 513, at = {1458, 48.82, 69.28}, who = "Master Apothecary Faranell"}, {"accept", 515, at = {1458, 48.82, 69.28}, who = "Master Apothecary Faranell"}, {"note", "Train new spells at your class trainer", only = {classes = {"WARRIOR", "PALADIN", "ROGUE", "PRIEST", "MAGE", "WARLOCK"}}}, {"note", "Sell and repair"}, title = "Master Apothecary Faranell"},
	{{"note", "Train new spells at your class trainer"}, note = "Take the zeppelin from the towers outside the Undercity to Orgrimmar and train before you fly on.", only = {classes = {"HUNTER", "SHAMAN"}}, title = "Orgrimmar"},
	{{"note", "Fly to Thunder Bluff"}, {"note", "Train new spells at your class trainer"}, note = "From Orgrimmar (zeppelin from the towers outside the Undercity) fly to Thunder Bluff and train on Elder Rise, then fly on to Camp Taurajo.", only = {classes = {"DRUID"}}, title = "Thunder Bluff"},
	{{"note", "Fly to Camp Taurajo"}, {"bind", "Camp Taurajo", at = {1413, 45.58, 59.04}, who = "Innkeeper Byula"}, {"accept", 874, at = {1413, 44.86, 59.14}, who = "Jorn Skyseer"}, note = "From Orgrimmar (zeppelin from the towers outside the Undercity) fly to Camp Taurajo.", title = "Camp Taurajo"},
	{{"turnin", 1536, at = {1413, 43.42, 77.41}, who = "Brine"}, {"accept", 1534, at = {1413, 43.42, 77.41}, who = "Brine"}, note = "Brine's hut stands on the ridge above the quilboar watering hole, south of Camp Taurajo, on the way to Bael Modan.", only = {classes = {"SHAMAN"}}, title = "Brine"},
	{{"accept", 857, at = {1413, 48.97, 86.31}, who = "Feegly the Exiled"}, {"complete", 857, at = {1413, 49.1, 84.3}}, {"turnin", 857, at = {1413, 48.97, 86.31}, who = "Feegly the Exiled"}, note = "Follow the road south to the dwarf dig site at Bael Modan. Feegly the Exiled hides at the south edge of the dig; General Twinbraid's Strongbox sits at the bottom of the excavation.", title = "Tear of the Moons"},
	{{"turnin", 5881, at = {1441, 31.86, 21.66}, who = "Grish Longrunner"}, note = "South-west of Bael Modan, Grish Longrunner waits at the top of the Great Lift.", title = "Great Lift"},
	{{"note", "Hearth to Camp Taurajo"}, {"note", "Fly to Ratchet"}, {"turnin", 874, at = {1413, 65.84, 43.86}, who = "Mahren Skyseer"}, {"accept", 873, at = {1413, 65.84, 43.86}, who = "Mahren Skyseer"}, note = "Hearth to Camp Taurajo and fly to Ratchet. Mahren Skyseer camps on the shore north of Ratchet.", title = "Merchant Coast"},
	{{"complete", 873, at = {1413, 65.6, 46.8}}, note = "Isha Awak, a big threshadon, swims in the shallows off the Merchant Coast, east of Mahren.", title = "Isha Awak"},
	{{"turnin", 873, at = {1413, 65.84, 43.86}, who = "Mahren Skyseer"}, {"turnin", 1094, at = {1413, 62.98, 37.22}, who = "Sputtervalve"}, {"note", "Sell and repair"}, title = "Ratchet"},
} })

Pathwise.RegisterRoute({category = "Leveling", faction = "Horde", id = "forever/horde/07-ashenvale", levels = {27, 31}, map = 1440, next = "forever/horde/30-40/01-desolace", title = "Ashenvale & Thousand Needles", steps = {
	{{"note", "Fly to Zoram'gar Outpost"}, {"turnin", 6562, at = {1440, 11.56, 34.29}, who = "Je'neu Sancrea"}, {"accept", 6563, at = {1440, 11.56, 34.29}, who = "Je'neu Sancrea"}, {"accept", 216, at = {1440, 11.9, 34.54}, who = "Karang Amakkar"}, {"accept", 6462, at = {1440, 11.65, 34.85}, who = "Mitsuwa"}, {"accept", 6641, at = {1440, 12.06, 34.63}, who = "Muglash"}, note = "Fly from Ratchet to Zoram'gar Outpost on the Ashenvale coast.", title = "Zoram'gar Outpost"},
	{{"goto", 1440, 9.6, 27.6, "Naga brazier"}, {"complete", 6641}, note = "Muglash walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead.", title = "Vorsha the Lasher"},
	{{"goto", 1440, 14.5, 14.2, "Blackfathom Deeps ruins"}, note = "The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit.", title = "Blackfathom Deeps ruins"},
	{{"complete", 6563, at = {1440, 13.59, 13.14}}, note = "The Sapphires are blue crystals on the walls of the tunnels leading to the Blackfathom Deeps portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep.", title = "Sapphires of Aku'Mai"},
	{{"turnin", 6563, at = {1440, 11.56, 34.29}, who = "Je'neu Sancrea"}, {"turnin", 6641, at = {1440, 12.22, 34.22}, who = "Warsong Runner"}, {"note", "Je'neu offers a Blackfathom Deeps quest next; leave it unless you have a group."}, title = "Zoram'gar Outpost"},
	{{"complete", 216, at = {1440, 31.74, 38}}, note = "East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold.", title = "Thistlefur Village"},
	{{"complete", 6462, at = {1440, 39.88, 34.17}}, {"accept", 6482, at = {1440, 41.53, 34.49}, who = "Ruul Snowhoof"}, {"complete", 6482}, note = "Inside the hold, Troll Chests lie along the tunnels. Ruul Snowhoof is held deep inside: free him and protect him all the way out, then he runs home to Night Run.", title = "Thistlefur Hold"},
	{{"turnin", 216, at = {1440, 11.9, 34.54}, who = "Karang Amakkar"}, {"accept", 6621, at = {1440, 11.9, 34.54}, who = "Karang Amakkar"}, {"turnin", 6462, at = {1440, 11.65, 34.85}, who = "Mitsuwa"}, note = "Back west to Zoram'gar before heading east for good.", title = "Zoram'gar Outpost"},
	{{"have", 16303, 1, at = {1440, 39.76, 65.21}, name = "Ursangous's Paw"}, {"accept", 23}, note = "Follow the main road east past Astranaar (Alliance: keep to the road). Ursangous, a big grizzly, roams the Ruins of Stardust south of the road, west of Mystral Lake. His paw starts the next hunt quest.", title = "Ursangous"},
	{{"complete", 1534, at = {1440, 33.55, 67.47}}, note = "The fountain stands in the middle of the Ruins of Stardust: use the Empty Blue Waterskin there.", only = {classes = {"SHAMAN"}}, title = "Ruins of Stardust fountain"},
	{{"goto", 1440, 42.4, 70, "Alonso"}, {"accept", 78132, at = {1440, 42.4, 70}, optional = true, who = "Alonso"}, {"turnin", 78132, at = {1440, 42.4, 70}, who = "Alonso"}, {"accept", 78133, at = {1440, 42.4, 70}, optional = true, who = "Alonso"}, {"turnin", 78133, at = {1440, 42.4, 70}, who = "Alonso"}, {"accept", 78134, at = {1440, 42.4, 70}, optional = true, who = "Alonso"}, {"turnin", 78134, at = {1440, 42.4, 70}, who = "Alonso"}, note = "Alonso, a Forever addition, stands on the west shore of Mystral Lake with three quick Dragonslayer quests.", title = "Alonso"},
	{{"have", 16408, 1, at = {1440, 46, 70}, name = "Befouled Water Globe"}, {"accept", 1918}, note = "Tideress, a corrupted water elemental, drifts in Mystral Lake. Her Befouled Water Globe starts a quest for Splintertree.", title = "Tideress"},
	{{"complete", 6621, at = {1440, 56.43, 63.5}}, note = "The Foulweald furbolgs hold the woods east of Mystral Lake, south of the road. Place Karang's Banner on the Foulweald Totem Mound and guard it: the furbolgs come to tear it down. Chief Murgut comes last; his totem drops in the basket.", title = "King of the Foulweald"},
	{{"accept", 6544, at = {1440, 68.34, 75.3}, who = "Torek"}, {"complete", 6544}, note = "Keep east on the road. Torek waits south-west of the Warsong lumber camp. He and his grunts storm the Silverwing Outpost: let them take aggro and stay with Torek until Duriel Moonfire is dead.", title = "Torek's Assault"},
	{{"accept", 6503, at = {1440, 71.11, 68.12}, who = "Kuray'bin"}, {"complete", 6503, at = {1440, 72.52, 69.5}}, {"turnin", 6503, at = {1440, 71.11, 68.12}, who = "Kuray'bin"}, note = "Kuray'bin stands at the lumber camp. The night elf Outrunners stalk the woods south-east of it; they stealth, so watch for them.", title = "Ashenvale Outrunners"},
	{{"bind", "Splintertree Post", at = {1440, 73.99, 60.65}, who = "Innkeeper Kaylisk"}, {"turnin", 6544, at = {1440, 73.03, 62.47}, who = "Ertog Ragetusk"}, {"turnin", 6482, at = {1440, 74.11, 60.92}, who = "Yama Snowhoof"}, {"turnin", 23, at = {1440, 73.78, 61.46}, who = "Senani Thunderheart"}, {"turnin", 1918, at = {1440, 73.67, 60}, who = "Mastok Wrilehiss"}, {"accept", 824, at = {1440, 73.67, 60}, who = "Mastok Wrilehiss"}, {"accept", 25, at = {1440, 73.67, 60}, who = "Mastok Wrilehiss"}, {"accept", 6441, at = {1440, 73.06, 61.48}, who = "Pixel"}, {"accept", 6504, at = {1440, 70.01, 71.16}, optional = true, who = "Gurda Ragescar"}, {"turnin", 6504, at = {1440, 70.01, 71.16}, optional = true, who = "Gurda Ragescar"}, {"note", "Sell and repair"}, note = "North up the road to Splintertree Post and Night Run beside it.", title = "Splintertree Post"},
	{{"have", 16305, 1, at = {1440, 74.98, 70.06}, name = "Sharptalon's Claw"}, {"accept", 2}, note = "Sharptalon, a big nightsaber, prowls the woods south-east of the Warsong lumber camp. Her claw starts the next hunt quest.", title = "Sharptalon"},
	{{"complete", 6441, at = {1440, 66.73, 57.17}}, note = "North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns.", title = "Felmusk satyrs"},
	{{"have", 16304, 1, at = {1440, 57.5, 56.05}, name = "Shadumbra's Head"}, {"accept", 24}, note = "Shadumbra, a shadow panther, stalks the woods around Raynewood Retreat, west of the Felmusk camp. Her head starts the next hunt quest.", title = "Shadumbra"},
	{{"complete", 25, at = {1440, 50.92, 67.42}}, {"goto", 1440, 48.9, 69.6, "Gazebo"}, note = "Back south-west to Mystral Lake. Befouled Water Elementals drift around its shores; the gazebo stands on the island, overlooking the Alliance outpost.", title = "Mystral Lake"},
	{{"note", "Hearth to Splintertree Post"}, {"turnin", 25, at = {1440, 73.67, 60}, who = "Mastok Wrilehiss"}, {"turnin", 6441, at = {1440, 73.06, 61.48}, who = "Pixel"}, {"turnin", 2, at = {1440, 73.78, 61.46}, who = "Senani Thunderheart"}, {"turnin", 24, at = {1440, 73.78, 61.46}, who = "Senani Thunderheart"}, {"accept", 247, at = {1440, 73.78, 61.46}, who = "Senani Thunderheart"}, {"turnin", 247, at = {1440, 73.78, 61.46}, who = "Senani Thunderheart"}, title = "Splintertree Post"},
	{{"note", "Fly to Zoram'gar Outpost"}, {"turnin", 6621, at = {1440, 11.9, 34.54}, who = "Karang Amakkar"}, {"turnin", 824, at = {1440, 11.56, 34.29}, who = "Je'neu Sancrea"}, title = "Zoram'gar Outpost"},
	{{"goto", 1456, 47, 49.83, "Get the flight path at Thunder Bluff"}, {"complete", 93739, at = {1456, 60.3, 51.68}, only = {races = {"Skyborne"}}, optional = true}, note = "Fly to Thunder Bluff if you know the flight path. If not, fly to Camp Taurajo, head west into Mulgore past Bloodhoof Village to Thunder Bluff and take its flight path from Tal on the central rise.", title = "Thunder Bluff"},
	{{"accept", 96241, at = {1412, 32.5, 20.6}, who = "Mazu'kon"}, {"accept", 96260, at = {1412, 32.46, 19.99}, who = "Yorn Grimtotem"}, {"accept", 96259, at = {1412, 33.42, 22.52}, who = "Muln Earthfury"}, note = "Take a lift down from Thunder Bluff. The Earthen Ring camp stands north of the bluffs: Mazu'kon, Yorn Grimtotem and Muln Earthfury.", title = "The Earthen Ring"},
	{{"complete", 96241, at = {1412, 33.62, 12.77}}, {"complete", 96260, at = {1412, 33.16, 11.93}}, {"complete", 96259, at = {1412, 33.11, 11.85}}, {"have", 273658, 1, at = {1412, 33.4, 7.6}, name = "Bloody Parchment"}, {"accept", 96294}, note = "North of the camp, spiders overrun the burial ground at Gloomrise. Use Mazu'kon's Toxin Extractor on the Gnawed Corpses; the Spinners drop the Crystalline Silk. Broodmother Valraxx sits at the north end: her Bloody Parchment starts A Darker Truth.", title = "Gloomrise"},
	{{"turnin", 96241, at = {1412, 32.52, 20.6}, who = "Mazu'kon"}, {"turnin", 96260, at = {1412, 32.46, 19.99}, who = "Yorn Grimtotem"}, {"turnin", 96259, at = {1412, 33.42, 22.52}, who = "Muln Earthfury"}, {"turnin", 96294, at = {1412, 33.42, 22.52}, who = "Muln Earthfury"}, note = "Back south to the camp, then up into Thunder Bluff for the flight to Camp Taurajo.", title = "The Earthen Ring"},
	{{"note", "Fly to Camp Taurajo"}, {"turnin", 1534, at = {1413, 43.42, 77.41}, who = "Brine"}, {"accept", 220, at = {1413, 43.42, 77.41}, who = "Brine"}, note = "Fly from Thunder Bluff to Camp Taurajo. Brine's hut stands on the ridge above the quilboar watering hole south of the camp, on the road to the Great Lift.", only = {classes = {"SHAMAN"}}, title = "Brine"},
	{{"note", "Fly to Camp Taurajo"}, {"goto", 1413, 44.2, 92.2, "The Great Lift"}, {"accept", 4542, at = {1441, 32.24, 22.17}, who = "Brave Moonhorn"}, note = "Fly from Thunder Bluff to Camp Taurajo and take the road south to the Great Lift at the bottom of the Barrens.", title = "The Great Lift"},
	{{"goto", 1441, 45.14, 49.11, "Get the flight path at Freewind Post"}, {"bind", "Freewind Post", at = {1441, 46.07, 51.52}, who = "Innkeeper Abeqwa"}, {"turnin", 4542, at = {1441, 45.67, 50.74}, who = "Cliffwatcher Longhorn"}, {"accept", 4841, at = {1441, 45.67, 50.74}, who = "Cliffwatcher Longhorn"}, {"accept", 4821, at = {1441, 44.64, 50.29}, who = "Hagar Lightninghoof"}, {"accept", 4767, at = {1441, 44.93, 48.92}, who = "Elu"}, {"accept", 98070, at = {1441, 46.21, 51.51}, who = "Jandia"}, {"accept", 5147, at = {1441, 46, 50.86}, who = "Wanted Poster - Arnak Grimtotem"}, note = "Ride the lift down, then follow the road east through the canyons to Freewind Post, a Tauren village on top of the mesas. Its lift is on the north side.", title = "Freewind Post"},
	{{"complete", 4821, at = {1441, 52.34, 55.25}}, note = "Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1).", title = "Alien Egg"},
	{{"turnin", 4821, at = {1441, 44.64, 50.29}, who = "Hagar Lightninghoof"}, {"accept", 4865, at = {1441, 44.64, 50.29}, who = "Hagar Lightninghoof"}, title = "Freewind Post"},
	{{"complete", 4841, at = {1441, 45.53, 43.54}}, {"have", 12564, 1, at = {1441, 39.43, 33.1}, name = "Assassination Note"}, {"accept", 4881}, note = "The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone Galak Messenger walks between the camps: kill him when you meet him, his note starts a quest for Whitereach Post.", title = "Galak centaurs"},
	{{"accept", 1149, at = {1441, 53.95, 41.49}, who = "Dorn Plainstalker"}, {"complete", 1149}, {"turnin", 1149, at = {1441, 53.95, 41.49}, who = "Dorn Plainstalker"}, {"accept", 1150, at = {1441, 53.95, 41.49}, who = "Dorn Plainstalker"}, note = "Dorn Plainstalker stands on a mesa top east of the Galak camps. For the Test of Faith, walk off the end of the planks beside him: you land safely.", title = "Dorn Plainstalker"},
	{{"turnin", 4841, at = {1441, 45.67, 50.74}, who = "Cliffwatcher Longhorn"}, {"accept", 5064, at = {1441, 45.67, 50.74}, who = "Cliffwatcher Longhorn"}, title = "Freewind Post"},
	{{"complete", 5064, at = {1441, 39.34, 41.53}}, note = "West of Freewind, the Grimtotem camps below Darkcloud Pinnacle. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps.", title = "Grimtotem camps"},
	{{"complete", 5147, at = {1441, 38.1, 26.9}}, {"accept", 4904, at = {1441, 37.95, 26.45}, who = "Lakota Windsong"}, {"complete", 4904}, note = "Climb the path to the top of Darkcloud Pinnacle. Lakota Windsong is held captive beside Arnak Grimtotem (29): clear the guards and Arnak first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way.", title = "Lakota Windsong"},
	{{"turnin", 4865, at = {1441, 21.54, 32.35}, who = "Motega Firemane"}, {"note", "Motega's next quest, Sacred Fire, ends in Thunder Bluff, off this route. Skip it."}, {"turnin", 4881, at = {1441, 21.25, 32.06}, who = "Kanati Greycloud"}, {"accept", 4966, at = {1441, 21.25, 32.06}, who = "Kanati Greycloud"}, {"complete", 4966}, {"turnin", 4966, at = {1441, 21.25, 32.06}, who = "Kanati Greycloud"}, note = "Follow the canyon west to Whitereach Post.", title = "Whitereach Post"},
	{{"complete", 4767, at = {1441, 17.16, 40.79}}, {"accept", 4770, at = {1441, 17.89, 40.57}, who = "Pao'ka Swiftmountain"}, {"complete", 4770}, note = "West of Whitereach the wyverns nest on the Highperch cliffs; the eggs lie in the nests. Pao'ka Swiftmountain waits on the east side of the nesting grounds: free him and keep him alive on the walk back to Whitereach Post.", title = "Highperch"},
	{{"turnin", 4770, at = {1441, 21.54, 32.35}, who = "Motega Firemane"}, title = "Whitereach Post"},
	{{"complete", 1150, at = {1441, 26, 55.4}}, {"complete", 98070, at = {1441, 26.01, 54.97}}, note = "South of Darkcloud, the harpies of Roguefeather Den. Grenka Bloodscreech (31) walks among them: thin out the harpies around her before you pull her. The Screeching Harpies, Roguefeathers and Windcallers there are Jandia's.", title = "Roguefeather Den"},
	{{"turnin", 5064, at = {1441, 45.67, 50.74}, who = "Cliffwatcher Longhorn"}, {"turnin", 5147, at = {1441, 45.67, 50.74}, who = "Cliffwatcher Longhorn"}, {"turnin", 4904, at = {1441, 45.97, 51.61}, who = "Thalia Amberhide"}, {"turnin", 4767, at = {1441, 44.93, 48.92}, who = "Elu"}, {"turnin", 98070, at = {1441, 46.21, 51.51}, who = "Jandia"}, {"note", "Sell and repair"}, title = "Freewind Post"},
	{{"turnin", 1150, at = {1441, 53.95, 41.49}, who = "Dorn Plainstalker"}, {"accept", 1151, at = {1441, 53.95, 41.49}, optional = true, who = "Dorn Plainstalker"}, title = "Test of Endurance"},
	{{"complete", 1151, at = {1441, 17.1, 38.1}, optional = true}, {"turnin", 1151, at = {1441, 53.95, 41.49}, optional = true, who = "Dorn Plainstalker"}, note = "Rok'Alim, a hard-hitting rock elemental, walks the cliffs of Highperch. Rok'Alim the Pounder is elite: grouping up is advised.", title = "Rok'Alim the Pounder"},
	{{"accept", 1110, at = {1441, 77.79, 77.27}, who = "Kravel Koalbeard"}, {"accept", 5762, at = {1441, 77.79, 77.27}, who = "Kravel Koalbeard"}, {"accept", 1104, at = {1441, 78.06, 77.13}, who = "Fizzle Brassbolts"}, {"accept", 1105, at = {1441, 78.14, 77.12}, who = "Wizzle Brassbolts"}, {"accept", 1175, at = {1441, 81.63, 77.95}, who = "Trackmaster Zherin"}, {"accept", 1176, at = {1441, 80.18, 75.88}, who = "Pozzik"}, note = "Follow the canyon east out of the mesas onto the salt flats. The goblins and gnomes of the Mirage Raceway are neutral and give quests to both factions.", title = "Mirage Raceway"},
	{{"complete", 1110, at = {1441, 77.8, 84.15}}, {"complete", 1104, at = {1441, 81.4, 86.83}}, {"complete", 1105, at = {1441, 82.17, 85.06}}, {"complete", 1176, at = {1441, 79.32, 89.16}}, {"complete", 1175, at = {1441, 77.6, 64.88}}, note = "Rocket Car Rubble lies all over the flats north of the raceway. Scorpid Reavers and Sparkleshell Tortoises roam the north half, Salt Flats Scavengers circle overhead, and Saltstone Basilisks graze west of the track. The Crystalhides roam the middle of the flats and the Gazers (34-35, five levels above you: one at a time) the far south.", title = "The salt flats"},
	{{"turnin", 1175, at = {1441, 81.63, 77.95}, who = "Trackmaster Zherin"}, {"turnin", 1176, at = {1441, 80.18, 75.88}, who = "Pozzik"}, {"turnin", 1110, at = {1441, 77.79, 77.27}, who = "Kravel Koalbeard"}, {"turnin", 1104, at = {1441, 78.06, 77.13}, who = "Fizzle Brassbolts"}, {"turnin", 1105, at = {1441, 78.14, 77.12}, who = "Wizzle Brassbolts"}, {"accept", 1106, at = {1441, 78.06, 77.13}, who = "Fizzle Brassbolts"}, title = "Mirage Raceway"},
	{{"note", "Hearth to Freewind Post"}, {"note", "The next guide flies on from here to Orgrimmar."}, title = "Freewind Post"},
} })

Pathwise.RegisterRoute({category = "Leveling", faction = "Horde", id = "forever/horde/30-40/01-desolace", levels = {30, 33}, map = 1443, next = "forever/horde/30-40/02-stranglethorn-vale", title = "Desolace & Hillsbrad Foothills", steps = {
	{{"note", "Fly to Orgrimmar"}, note = "From Freewind Post, fly to Orgrimmar.", title = "Fly to Orgrimmar"},
	{{"accept", 1431, at = {1454, 51.3, 45.9}, who = "Craven Drok"}, {"turnin", 1431, at = {1454, 22.56, 52.63}, who = "Keldran"}, {"accept", 1432, at = {1454, 22.56, 52.63}, who = "Keldran"}, {"turnin", 93739, at = {1454, 31.73, 37.82}, only = {races = {"Skyborne"}}, optional = true, who = "Thrall"}, note = "Craven Drok waits in the Drag; Keldran stands in the Valley of Spirits on the west side of the city. Skyborne: Thrall waits in Grommash Hold, in the Valley of Wisdom.", title = "Alliance Relations"},
	{{"note", "Train new spells at your class trainer"}, note = "Train your new spells.", only = {classes = {"WARRIOR", "HUNTER", "ROGUE", "PRIEST", "SHAMAN", "MAGE", "WARLOCK"}}, title = "Train"},
	{{"note", "Fly to Thunder Bluff"}, {"note", "Train new spells at your class trainer"}, note = "Your trainer is in Thunder Bluff, one flight away: Turak Runetotem (Druids) on Elder Rise, Alodan the Hopeful (Paladins). Fly on to Sun Rock Retreat from there.", only = {classes = {"PALADIN", "DRUID"}}, title = "Thunder Bluff"},
	{{"accept", 1531, at = {1454, 37.96, 37.73}, who = "Searn Firewarder"}, note = "Searn Firewarder stands in the Valley of Wisdom.", only = {classes = {"SHAMAN"}}, title = "Orgrimmar class quests"},
	{{"note", "Fly to Ratchet"}, {"turnin", 220, at = {1413, 65.83, 43.78}, who = "Islen Waterseer"}, {"accept", 63, at = {1413, 65.83, 43.78}, who = "Islen Waterseer"}, note = "Fly to Ratchet. Islen Waterseer camps on the coast a short walk south of the town.", only = {classes = {"SHAMAN"}}, title = "Ratchet"},
	{{"note", "Fly to Freewind Post"}, {"turnin", 1531, at = {1441, 53.54, 42.65}, who = "Prate Cloudseer"}, {"note", "Prate also starts Elemental Aid (Razorfen Kraul), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."}, note = "Fly to Freewind Post. Prate Cloudseer hides in a small cave in the canyon wall north-east of the post.", only = {classes = {"SHAMAN"}}, title = "Prate Cloudseer"},
	{{"note", "Fly to Sun Rock Retreat"}, title = "Fly to Sun Rock Retreat"},
	{{"accept", 5821, at = {1443, 66.54, 37.51}, optional = true, who = "Cork Gizelton"}, note = "Follow the road south-west out of Sun Rock into Desolace and on south past Nijel's Point. Cork Gizelton's kodo caravan waits by the road north of Kolkar Village; if it has already left, head on.", title = "Gizelton caravan"},
	{{"complete", 5821, optional = true}, note = "The caravan rolls south past Kolkar Village. Kolkar raiders ambush it in waves: kill them before they reach Cork. It stops by Scrabblescrew's Camp, east of Ghost Walker Post.", title = "Bodyguard for Hire"},
	{{"turnin", 5821, at = {1443, 60.86, 61.86}, optional = true, who = "Smeed Scrabblescrew"}, {"accept", 5561, at = {1443, 60.86, 61.86}, who = "Smeed Scrabblescrew"}, title = "Scrabblescrew's Camp"},
	{{"accept", 1365, at = {1443, 56.19, 59.57}, who = "Felgur Twocuts"}, {"turnin", 1432, at = {1443, 52.57, 54.39}, who = "Takata Steelblade"}, {"accept", 1433, at = {1443, 52.57, 54.39}, who = "Takata Steelblade"}, {"accept", 1434, at = {1443, 52.57, 54.39}, who = "Takata Steelblade"}, {"turnin", 1433, at = {1443, 52.25, 53.44}, who = "Maurin Bonesplitter"}, {"accept", 1435, at = {1443, 52.25, 53.44}, who = "Maurin Bonesplitter"}, note = "Felgur stands in the post; Takata Steelblade and Maurin Bonesplitter wait on the rise west of it, above the Kodo Graveyard.", title = "Ghost Walker Post"},
	{{"goto", 1443, 52, 57.5, "Kodo Graveyard"}, {"complete", 5561}, {"turnin", 5561, at = {1443, 60.86, 61.86}, who = "Smeed Scrabblescrew"}, note = "Use Smeed's Kodo Kombobulator on an Aged, Dying or Ancient Kodo in the graveyard and walk the tamed kodo back to Smeed. Five kodos, one at a time.", title = "Kodo Roundup"},
	{{"complete", 1365, at = {1443, 73, 47.8}}, note = "Head north-east to Kolkar Village. Khan Dez'hepah (35) walks among the tents on the east side with a Battle Lord or two (32-33): clear around him, then pull him alone at full health.", title = "Khan Dez'hepah"},
	{{"complete", 1434, at = {1443, 73.6, 25.46}}, note = "North along the eastern hills, the satyrs hold the ruins of Sargeron. The Shadowstalkers walk unseen; the four kinds you need do not.", title = "Sargeron"},
	{{"complete", 1435, at = {1443, 57.61, 26.32}}, {"have", 20310, 1, at = {1443, 57.61, 26.32}, name = "Flayed Demon Skin", optional = true}, {"accept", 1480, optional = true}, note = "Head west to Thunder Axe Fortress. Beat a Burning Blade cultist down, then use the Burning Gem on it before it dies to fill one Infused Burning Gem. They also drop a Flayed Demon Skin now and then (1-5%); if one drops, read it.", title = "Thunder Axe Fortress"},
	{{"turnin", 1435, at = {1443, 52.25, 53.44}, who = "Maurin Bonesplitter"}, {"turnin", 1480, at = {1443, 52.25, 53.44}, optional = true, who = "Maurin Bonesplitter"}, {"accept", 1481, at = {1443, 52.25, 53.44}, optional = true, who = "Maurin Bonesplitter"}, {"turnin", 1434, at = {1443, 52.57, 54.39}, who = "Takata Steelblade"}, {"turnin", 1365, at = {1443, 56.19, 59.57}, who = "Felgur Twocuts"}, {"accept", 1366, at = {1443, 56.19, 59.57}, who = "Felgur Twocuts"}, {"note", "Takata's next Alliance Relations sends you back to Orgrimmar for nothing: leave it."}, note = "Head back south to the post.", title = "Ghost Walker Post"},
	{{"complete", 1366, at = {1443, 65.59, 70.3}}, note = "Back at Kolkar Village, every Kolkar can drop an ear.", title = "Kolkar ears"},
	{{"goto", 1443, 72.4, 18, "Sargeron"}, {"complete", 1481, at = {1443, 70.11, 15.58}, optional = true}, note = "The Hatefury Shadowstalkers at Sargeron walk unseen until they strike; about one in three carries a scalp.", title = "Shadowstalker scalp"},
	{{"turnin", 1366, at = {1443, 56.19, 59.57}, who = "Felgur Twocuts"}, {"turnin", 1481, at = {1443, 52.25, 53.44}, optional = true, who = "Maurin Bonesplitter"}, {"accept", 1482, at = {1443, 52.25, 53.44}, optional = true, who = "Maurin Bonesplitter"}, {"note", "Sell and repair"}, title = "Ghost Walker Post"},
	{{"goto", 1443, 21.6, 74.13, "Get the flight path at Shadowprey Village"}, {"accept", 5763, at = {1443, 25.05, 72.27}, who = "Roon Wildmane"}, {"accept", 6142, at = {1443, 22.64, 71.97}, who = "Mai'Lahii"}, note = "Head south-west to the troll village on the coast, keeping clear of the Gelkis Village on the way.", title = "Shadowprey Village"},
	{{"complete", 6142, at = {1443, 30.96, 35.75}}, note = "Head north up the coast. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach; open each clam in your bags for its meat.", title = "Clam beds"},
	{{"goto", 1443, 28.5, 8.5, "Sar'theris Strand"}, {"complete", 1482, at = {1443, 27.69, 7.92}, optional = true}, note = "Keep north to Sar'theris Strand. The Oracles stand among the other naga at its north end; pull one at a time.", title = "Slitherblade Oracles"},
	{{"accept", 5741, at = {1443, 38.88, 27.16}, who = "Azore Aldamort"}, note = "Azore Aldamort waits in the ruined tower of Ethel Rethor, inland to the south-east.", title = "Ethel Rethor"},
	{{"complete", 5741, at = {1443, 55.2, 30.1}}, note = "The Seer stands on the south side of Thunder Axe Fortress, east of Ethel Rethor. Clear the cultists around it first.", title = "Burning Blade Seer"},
	{{"turnin", 5741, at = {1443, 38.88, 27.16}, who = "Azore Aldamort"}, {"note", "His next errand is not on this route."}, title = "Ethel Rethor"},
	{{"turnin", 1482, at = {1443, 52.25, 53.44}, optional = true, who = "Maurin Bonesplitter"}, {"accept", 1484, at = {1443, 52.25, 53.44}, optional = true, who = "Maurin Bonesplitter"}, {"turnin", 1484, at = {1443, 52.57, 54.39}, optional = true, who = "Takata Steelblade"}, {"note", "Takata's next errand sends you after a demon lord with an elite guard: skip it."}, note = "Head south-east to the post.", title = "Ghost Walker Post"},
	{{"level", 32}, note = "Head south-west towards Shadowprey. The Gelkis centaurs (32-35) around their village are a good camp; fight them until level 32.", title = "Gelkis Village"},
	{{"turnin", 6142, at = {1443, 22.64, 71.97}, who = "Mai'Lahii"}, title = "Shadowprey Village"},
	{{"note", "Fly to Thunder Bluff"}, {"note", "Train new spells at your class trainer"}, note = "Fly to Thunder Bluff from Shadowprey and train with Turak Runetotem on Elder Rise, then fly on to Orgrimmar.", only = {classes = {"DRUID"}}, title = "Thunder Bluff"},
	{{"note", "Fly to Orgrimmar"}, {"note", "Train new spells at your class trainer", only = {classes = {"WARRIOR", "HUNTER", "ROGUE", "PRIEST", "SHAMAN", "MAGE", "WARLOCK"}}}, title = "Fly to Orgrimmar"},
	{{"goto", 1411, 50.8, 13.5, "Zeppelin tower"}, note = "Leave Orgrimmar by the main gate; the zeppelin tower stands just north-east of it. Take the Undercity zeppelin.", title = "Zeppelin to the Undercity"},
	{{"note", "Train new spells at your class trainer"}, note = "Garen Largo trains Paladins in the Undercity.", only = {classes = {"PALADIN"}}, title = "Garen Largo"},
	{{"note", "Fly to The Sepulcher"}, {"complete", 63, at = {1421, 38.78, 44.26}}, {"turnin", 63, at = {1421, 38.26, 44.56}, who = "Brazier of Everfount"}, {"accept", 100, at = {1421, 38.26, 44.56}, who = "Brazier of Everfount"}, {"turnin", 100, at = {1421, 38.65, 44.58}, who = "Minor Manifestation of Water"}, {"accept", 96, at = {1421, 38.65, 44.58}, who = "Minor Manifestation of Water"}, note = "Do your shopping in the Undercity first, then fly to the Sepulcher. The Brazier of Everfount stands on the hill just south-west of it: beat the Corrupt Manifestation of Water beside it, place its bracers in the brazier, speak to the Minor Manifestation of Water and keep the Shard of Water for Islen. Fly on to Tarren Mill from the Sepulcher.", only = {classes = {"SHAMAN"}}, title = "Brazier of Everfount"},
	{{"note", "Strong Troll's Blood Potion: auction house or an alchemist, for Elixir of Agony."}, {"note", "Fly to Tarren Mill"}, note = "Elixir of Agony needs a Strong Troll's Blood Potion, an Alchemy item: buy one at the auction house here if you can (or ask an alchemist). No potion: skip the Elixir steps in Hillsbrad.", title = "Undercity"},
	{{"bind", "Tarren Mill", at = {1424, 62.78, 19.03}, who = "Innkeeper Shay"}, {"have", 3703, 1, at = {1424, 62.78, 19.03}, name = "Southshore Stout"}, {"accept", 552, at = {1424, 63.88, 19.66}, who = "Novice Thaivand"}, {"accept", 544, at = {1424, 61.6, 20.85}, who = "Magus Wordeen Voidglare"}, {"accept", 556, at = {1424, 61.5, 20.93}, who = "Keeper Bel'varil"}, {"accept", 676, at = {1424, 61.87, 19.57}, who = "Tallow"}, {"accept", 533, at = {1424, 63.24, 20.66}, who = "Krusk"}, {"accept", 1361, at = {1424, 63.24, 20.66}, who = "Krusk"}, title = "Tarren Mill"},
	{{"goto", 1424, 53, 65, "Daggerspine shore"}, {"complete", 515, at = {1424, 52.73, 65.51}, optional = true}, note = "Head south, east of Southshore, down to the coast. The Daggerspine naga line the shore south-east of the town.", title = "Daggerspine naga"},
	{{"goto", 1424, 36, 68, "Torn Fin beach"}, {"complete", 515, at = {1424, 36.06, 68.74}, optional = true}, note = "Follow the shore west past Southshore's bay; the Torn Fin murlocs camp on the beaches beyond it.", title = "Torn Fin murlocs"},
	{{"turnin", 515, at = {1424, 61.44, 19.06}, optional = true, who = "Apothecary Lydon"}, {"accept", 517, at = {1424, 61.44, 19.06}, optional = true, who = "Apothecary Lydon"}, note = "Head back north to Tarren Mill, keeping west of Southshore.", title = "Apothecary Lydon"},
	{{"complete", 517, at = {1424, 72, 80.5}, optional = true}, note = "The keg stands with a few others at the Syndicate camp on the south-east coast of Hillsbrad.", title = "Shindigger keg"},
	{{"note", "Hearth to Tarren Mill"}, {"turnin", 517, at = {1424, 61.44, 19.06}, optional = true, who = "Apothecary Lydon"}, {"accept", 524, at = {1424, 61.44, 19.06}, optional = true, who = "Apothecary Lydon"}, {"turnin", 524, at = {1424, 62.81, 18.73}, optional = true, who = "Dusty Rug"}, note = "Hearth back (or head north if it is on cooldown).", title = "Back to Tarren Mill"},
	{{"accept", 535, at = {1416, 57.17, 69.51}, who = "Henchman Valik"}, {"turnin", 535, at = {1416, 57.17, 69.51}, who = "Henchman Valik"}, note = "Follow the road north out of Tarren Mill into the Alterac foothills. Valik waits by the Syndicate camp; hand him the stout.", title = "Henchman Valik"},
	{{"complete", 533, at = {1416, 57.6, 68.54}}, note = "The Syndicate Footpads and Thieves (32-33) around the camps west of the road carry the missives; about one in three drops one.", title = "Syndicate missives"},
	{{"complete", 552, at = {1424, 44.86, 31.13}}, note = "South-west, the Cave and Ferocious Yetis (30-31) fill the caves in the hills west of Tarren Mill; about one in sixteen carries the rod.", title = "Helcular's Rod"},
	{{"complete", 544, at = {1416, 20.16, 84.28}}, {"complete", 556, at = {1416, 17.87, 83.11}}, note = "Head west along the foot of the mountains to the violet dome of Dalaran. Ricter, Alina and Dermot (33-34) stand together inside the crater's eastern rim, Kegan Darkmar (35) a little west of them; each carries one Bloodstone piece. The Shield Guards and Theurgists (31-32) around them drop the Worn Stone Tokens.", title = "The Dalaran traitors"},
	{{"turnin", 533, at = {1424, 63.24, 20.66}, who = "Krusk"}, {"accept", 503, at = {1424, 63.24, 20.66}, who = "Krusk"}, {"turnin", 552, at = {1424, 63.88, 19.66}, who = "Novice Thaivand"}, {"turnin", 544, at = {1424, 61.6, 20.85}, who = "Magus Wordeen Voidglare"}, {"turnin", 556, at = {1424, 61.5, 20.93}, who = "Keeper Bel'varil"}, {"note", "Thaivand's next task ends at Southshore's graveyard and the magus offers a dungeon errand: leave both."}, note = "Head back east to Tarren Mill.", title = "Tarren Mill"},
	{{"complete", 503, at = {1416, 61.93, 42.57}}, {"turnin", 503, at = {1416, 59.96, 43.74}, who = "Gol'dir"}, {"accept", 506, at = {1416, 59.96, 43.74}, who = "Gol'dir"}, note = "Head north past Valik's camp to Strahnbrad, the Syndicate-held village (35-37). Jailor Borhuin carries the Rusted Iron Key; Gol'dir sits in a cage in the house on the north side.", title = "Gol'dir"},
	{{"turnin", 506, at = {1424, 63.24, 20.66}, who = "Krusk"}, note = "Head back south to Tarren Mill.", title = "Tarren Mill"},
	{{"note", "Fly to Undercity"}, note = "The next guide starts in the Undercity, at the Grom'gol zeppelin.", title = "Fly to the Undercity"},
} })

