	{{"complete", 605, at = {1434, 34.68, 6.74}}, {"complete", 189, at = {1434, 31.41, 11.43}}, note = "West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear.", title = "Basilisks and the Bloodscalp village"},
