	{{"complete", 569, at = {1434, 35.55, 30.92}}, note = "The Mosh'Ogg ogres camp in the hills just east of Grom'gol. Kill one Brute and one Witch Doctor (36-37); pull them one at a time.", title = "Mosh'Ogg camp"},
	{{"complete", 570, at = {1434, 36.03, 33.95}}, {"complete", 577, at = {1434, 39.9, 28.4}}, note = "East of the ogres, Shadowmaw Panthers (37-38) stalk unseen until they strike; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for Drizzlik.", title = "Shadowmaw jungle and the Snapjaw river"},
	{{"turnin", 569, at = {1434, 32.17, 28.9}, who = "Commander Aggro'gosh"}, {"turnin", 570, at = {1434, 32.12, 29.24}, who = "Far Seer Mok'thardin"}, {"note", "Sell and repair"}, note = "Back to Grom'gol.", title = "Grom'gol"},
	{{"complete", 629, at = {1434, 24.8, 22.9}}, note = "North-west of Grom'gol the Vile Reef lies under the water off the coast. The Tablet Shard rests on the sea floor by the sunken ruins; watch your breath and the murlocs.", title = "The Vile Reef"},
	{{"complete", 596, at = {1434, 28.81, 19.95}}, note = "The Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a Bloody Bone Necklace. Keep looting pages of The Green Hills of Stranglethorn.", title = "Bloodscalp ruins"},
