	{{"complete", 192, at = {1434, 38.7, 32.86}}, note = "The Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way.", title = "Shadowmaw panthers"},
	{{"complete", 339, at = {1434, 35.52, 23.73}, optional = true}, {"complete", 340, at = {1434, 44.66, 11.01}, optional = true}, {"complete", 341, at = {1434, 44.66, 11.01}, optional = true}, {"complete", 342, at = {1434, 37.34, 31.33}, optional = true}, note = "Pages of The Green Hills of Stranglethorn drop at about 1% each from the Bloodscalp and Skullsplitter trolls; take what drops and check the Auction House for the rest.", title = "Green Hills pages"},
