	{{"turnin", 572, at = {1434, 32.12, 29.24}, who = "Far Seer Mok'thardin"}, {"accept", 571, at = {1434, 32.12, 29.24}, who = "Far Seer Mok'thardin"}, title = "Far Seer Mok'thardin"},
	{{"complete", 571, at = {1434, 32.42, 57.97}}, note = "Take the road south towards Booty Bay. The Elder Mistvale Gorillas (40-41) live in Mistvale Valley, east of the road; about one in twenty carries an aged sinew.", title = "Mistvale gorillas"},
