Pathwise.RegisterRoute({category = "Leveling", faction = "Horde", id = "forever/horde/30-40/03-arathi-highlands", levels = {37, 40}, map = 1417, next = "forever/horde/30-40/04-dustwallow-marsh", title = "Arathi Highlands, Badlands & The Barrens", steps = {
	{{"note", "Fly to Grom'gol"}, {"goto", 1434, 31.5, 29.4, "Zeppelin to the Undercity"}, note = "From Booty Bay, fly to Grom'gol. The Undercity zeppelin leaves from the tower on the west side of the camp.", title = "Fly to Grom'gol"},
	{{"note", "Train new spells at your class trainer"}, note = "The Undercity has no Hunter or Shaman trainer: take the Orgrimmar zeppelin from the same tower instead and train in the city, then take the Undercity zeppelin from the tower outside Orgrimmar's main gate.", only = {classes = {"HUNTER", "SHAMAN"}}, title = "Orgrimmar"},
	{{"note", "Train new spells at your class trainer"}, note = "Cast Teleport: Moonglade and take Bunthen Plainswind's flight to Thunder Bluff; Turak Runetotem trains you on Elder Rise. Then fly to Orgrimmar and take the Undercity zeppelin from the tower outside the main gate.", only = {classes = {"DRUID"}}, title = "Thunder Bluff"},
	{{"note", "Train new spells at your class trainer"}, note = "Train while you are in the Undercity: the trainers stand in the War Quarter, the Rogues' Quarter and the Magic Quarter (Paladins: Garen Largo).", only = {classes = {"WARRIOR", "PALADIN", "ROGUE", "PRIEST", "MAGE", "WARLOCK"}}, title = "Undercity trainers"},
	{{"note", "Fly to Tarren Mill"}, note = "The zeppelin lands at the towers outside the Undercity: head down into the city and fly to Tarren Mill.", title = "Fly to Tarren Mill"},
	{{"complete", 676, at = {1417, 34.45, 45}}, note = "Head east out of Tarren Mill through Thoradin's Wall and follow the road east. The Boulderfist Ogres and Enforcers (32-34) camp south of the road, south-east of Northfold Manor.", title = "Boulderfist camp"},
