	{{"complete", 672, at = {1417, 76.3, 31.12}}, note = "Highland Striders roam the hills all around Hammerfall; both they and the Thrashers further west drop the eyes.", title = "Highland raptors"},
	{{"turnin", 672, at = {1417, 74.72, 36.29}, who = "Tor'gan"}, {"accept", 674, at = {1417, 74.72, 36.29}, who = "Tor'gan"}, {"turnin", 674, at = {1417, 72.64, 33.93}, who = "Gor'mul"}, {"accept", 675, at = {1417, 72.64, 33.93}, who = "Gor'mul"}, {"turnin", 675, at = {1417, 74.72, 36.29}, who = "Tor'gan"}, {"accept", 701, at = {1417, 74.72, 36.29}, who = "Tor'gan"}, title = "Hammerfall"},
