	{{"turnin", 642, at = {1417, 84.31, 30.95}, who = "Iridescent Shards"}, {"accept", 651, at = {1417, 84.31, 30.95}, who = "Iridescent Shards"}, note = "The Iridescent Shards lie at the far end of the gorge.", title = "Iridescent Shards"},
	{{"complete", 651, at = {1417, 66.7, 29.72}}, note = "Each Circle of Binding is a ring of standing stones; the key sits on the stone at its heart. The eastern circle is on the hills north-west of Hammerfall.", title = "The Stone of East Binding"},
	{{"complete", 677, at = {1417, 70.71, 58.83}}, note = "The Witherbark trolls hold the village in the south-eastern hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village.", title = "Witherbark Village"},
	{{"complete", 701, at = {1417, 55.11, 67.46}}, note = "Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of Boulderfist Hall and another on the plain to its west. Pull them one at a time.", title = "Fleshstalker raptors"},
