	{{"turnin", 662, at = {1417, 32.8, 81.48}, who = "First Mate Nilzlix"}, {"turnin", 666, at = {1417, 33.86, 80.45}, who = "Doctor Draxlegauge"}, {"accept", 668, at = {1417, 33.86, 80.45}, who = "Doctor Draxlegauge"}, {"turnin", 664, at = {1417, 34, 80.8}, who = "Captain Steelgut"}, {"turnin", 668, at = {1417, 32.28, 81.38}, who = "Shakes O'Breen"}, {"accept", 669, at = {1417, 32.28, 81.38}, who = "Shakes O'Breen"}, title = "Faldir's Cove"},
	{{"complete", 651, at = {1417, 52.04, 50.73}}, note = "Head north; the outer circle stands in the middle of the highlands.", title = "The Stone of Outer Binding"},
	{{"complete", 671, at = {1417, 34.66, 31.69}}, note = "The Syndicate hold the walled manor and its farm in the north-west; their Highwaymen, Mercenaries and Pathstalkers carry the Bloodstone Amulets.", title = "Northfold Manor"},
