	{{"complete", 712, at = {1418, 17.03, 84.3}, optional = true}, {"complete", 2258, at = {1418, 17.03, 84.3}}, note = "The Greater Rock Elementals (42-44, well above you) wander the gulches in the south-west; the bracers drop about one kill in five. Pull one at a time and rest between fights, or leave them. Keep killing coyotes and buzzards you still need on the way.", title = "Greater Rock Elementals"},
