	{{"complete", 621, at = {1434, 38.66, 59.78}}, note = "North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture.", title = "Zanzil's camps"},
	{{"complete", 600, at = {1434, 36.52, 57.06}}, note = "Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals.", title = "Venture Co. mine"},
	{{"bind", "Grom'gol Base Camp", at = {1434, 31.49, 29.75}, who = "Innkeeper Thulbek"}, {"accept", 573, at = {1434, 32.12, 29.24}, who = "Far Seer Mok'thardin"}, {"accept", 584, at = {1434, 32.16, 27.72}, who = "Nimboya"}, {"accept", 2932, at = {1434, 32.16, 27.72}, who = "Nimboya"}, {"accept", 598, at = {1434, 32.27, 27.71}, who = "Kin'weelay"}, {"turnin", 1240, at = {1434, 32.27, 27.71}, who = "Kin'weelay"}, note = "Ride north-west to Grom'gol.", title = "Grom'gol Base Camp"},
	{{"accept", 196, at = {1434, 35.66, 10.81}, who = "Hemet Nesingwary"}, note = "Ride north up the road; the hunters camp on the hill above the river.", title = "Nesingwary's Expedition"},
	{{"complete", 584, at = {1434, 23.44, 8.12}}, note = "West of the expedition, the Bloodscalp chiefs Gan'zulah and Nezzliok stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them.", title = "Zul'Kunda"},
	{{"note", "Hearth to Grom'gol Base Camp"}, {"turnin", 584, at = {1434, 32.22, 27.6}, who = "Bubbling Cauldron"}, {"accept", 586, at = {1434, 32.22, 27.6}, who = "Bubbling Cauldron"}, {"accept", 585, at = {1434, 32.22, 27.6}, who = "Bubbling Cauldron"}, title = "Hearth to Grom'gol"},
	{{"complete", 196, at = {1434, 32.95, 36.54}}, note = "The stalker raptors hunt the jungle south of Grom'gol, out towards the west coast.", title = "Jungle stalkers"},
	{{"complete", 573, at = {1434, 27.06, 59.69}}, {"complete", 617, at = {1434, 27.06, 59.69}}, note = "Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the Holy Spring bubbles in the hills just east of them.", title = "Naga shore and the Holy Spring"},
	{{"bind", "Booty Bay", at = {1434, 27.04, 77.31}, who = "Innkeeper Skindle"}, {"turnin", 617, at = {1434, 26.76, 76.38}, who = "Privateer Bloads"}, {"turnin", 606, at = {1434, 26.9, 73.59}, who = "\"Shaky\" Phillipe"}, {"accept", 607, at = {1434, 26.9, 73.59}, who = "\"Shaky\" Phillipe"}, {"turnin", 607, at = {1434, 27.78, 77.07}, who = "\"Sea Wolf\" MacKinley"}, {"accept", 609, at = {1434, 27.78, 77.07}, who = "\"Sea Wolf\" MacKinley"}, {"turnin", 621, at = {1434, 27.12, 77.21}, who = "Crank Fizzlebub"}, {"turnin", 600, at = {1434, 27.12, 77.21}, who = "Crank Fizzlebub"}, {"turnin", 348, at = {1434, 27.61, 76.74}, who = "Fin Fizracket"}, {"note", "Sell and repair"}, note = "Ride south to Booty Bay. Shaky Phillipe waits on the docks.", title = "Booty Bay"},
	{{"note", "Kill Maury \"Club Foot\" Wilkins"}, {"complete", 609, at = {1434, 35.26, 51.27}}, {"note", "Kill Jon-Jon the Crow"}, {"note", "Kill Chucky \"Ten Thumbs\""}, note = "The three ghostly pirates haunt the jungle north of Booty Bay, near Zanzil's camps: Maury and Jon-Jon stand together, Chucky further east.", title = "Pirate ghosts"},
	{{"complete", 586, at = {1434, 45.04, 44.09}}, {"complete", 585, at = {1434, 47.65, 39.54}}, {"goto", 1434, 45.4, 36.2, "Skullsplitter warriors"}, {"complete", 209, at = {1434, 45.61, 41.6}}, {"complete", 598, at = {1434, 45.8, 41.79}}, note = "Ride north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. Ana'thek the Cruel guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all.", title = "Zul'Mamwe"},
	{{"complete", 585, at = {1434, 46.13, 32.33}}, note = "The next trophy skulls stand in the small ruins just north of the warriors' camp.", title = "Balia'mah Ruins"},
	{{"complete", 585, at = {1434, 42.21, 36.11}}, note = "The last skulls are in the ruins a short ride west, on the way back to Grom'gol.", title = "Ziata'jai Ruins"},
	{{"turnin", 573, at = {1434, 32.12, 29.24}, who = "Far Seer Mok'thardin"}, {"turnin", 586, at = {1434, 32.22, 27.6}, who = "Bubbling Cauldron"}, {"turnin", 585, at = {1434, 32.22, 27.6}, who = "Bubbling Cauldron"}, {"turnin", 598, at = {1434, 32.27, 27.71}, who = "Kin'weelay"}, note = "Ride west to Grom'gol.", title = "Grom'gol Base Camp"},
	{{"note", "Hearth to Booty Bay"}, {"turnin", 609, at = {1434, 27.78, 77.07}, who = "\"Sea Wolf\" MacKinley"}, {"turnin", 209, at = {1434, 27, 77.13}, who = "Kebok"}, title = "Hearth to Booty Bay"},
	{{"note", "Fly to Grom'gol"}, title = "Fly to Grom'gol"},
	{{"turnin", 196, at = {1434, 35.66, 10.81}, who = "Hemet Nesingwary"}, note = "Ride north up the road to the hunters' camp.", title = "Nesingwary's Expedition"},
	{{"accept", 1389, at = {1435, 25.98, 31.4}, who = "Magtoor"}, note = "Keep riding north into Duskwood, then east along the road through Deadwind Pass into the swamp. Magtoor waits at the Harborage, the draenei camp near the way in from Deadwind Pass.", title = "Into the Swamp of Sorrows"},
	{{"goto", 1435, 46.07, 54.83, "Get the flight path at Stonard"}, {"turnin", 1420, at = {1435, 47.74, 55.2}, who = "Helgrum the Swift"}, {"accept", 698, at = {1435, 44.7, 57.21}, who = "Dar"}, note = "Ride east to Stonard, in the reeds south of the road.", title = "Stonard"},
	{{"complete", 1389, at = {1435, 55.09, 30.08}}, note = "Ride north-east to the Fallow Sanctuary. The crystals stand along the way up to Galen Goodward's cage.", title = "Draenethyst crystals"},
	{{"accept", 1393, at = {1435, 65.47, 18.16}, who = "Galen Goodward"}, {"complete", 1393}, note = "Galen Goodward is held in the Fallow Sanctuary in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him.", title = "Galen's Escape"},
	{{"note", "Kill Noboru the Cudgel"}, {"have", 6196, 1, at = {1435, 54.9, 34.1}, name = "Noboru's Cudgel"}, {"accept", 1392}, note = "Noboru wanders the clearing south-west of the Fallow Sanctuary; his cudgel starts a quest.", title = "Noboru the Cudgel"},
	{{"turnin", 1393, at = {1435, 47.81, 39.76}, who = "Galen's Strongbox"}, note = "His strongbox waits at his old camp north of Stonard.", title = "Galen's Strongbox"},
	{{"complete", 698, at = {1435, 48.41, 39.12}}, note = "The crocolisks wallow in the pools around Galen's camp and south towards Stonard; about one in four drops a flank.", title = "Sawtooth crocolisks"},
	{{"turnin", 1392, at = {1435, 25.98, 31.4}, who = "Magtoor"}, {"turnin", 1389, at = {1435, 25.98, 31.4}, who = "Magtoor"}, note = "Ride west along the road to the draenei camp at the Harborage, near the way in from Deadwind Pass.", title = "The Harborage"},
	{{"turnin", 698, at = {1435, 81.32, 80.97}, who = "Tok'Kar"}, {"accept", 699, at = {1435, 81.32, 80.97}, who = "Tok'Kar"}, note = "Ride back east past Stonard and follow the road south-east to the small Horde post on the shore.", title = "Misty Reed Post"},
	{{"complete", 699, at = {1435, 83.8, 95.42}}, note = "The snappers line the strand south of the post.", title = "Sawtooth snappers"},
	{{"turnin", 699, at = {1435, 81.32, 80.97}, who = "Tok'Kar"}, note = "The next guide starts here and takes you to Tanaris.", title = "Misty Reed Post"},
} })

Pathwise.RegisterRoute({category = "Leveling", faction = "Horde", id = "forever/horde/40-50/02-feralas", levels = {42, 44}, map = 1444, next = "forever/horde/40-50/03-feralas", title = "Feralas & Tanaris", steps = {
	{{"note", "Fly to Grom'gol"}, note = "Ride back north-west from Misty Reed Post to Stonard and fly to Grom'gol.", title = "Fly to Grom'gol"},
	{{"goto", 1434, 31.4, 29.9, "Zeppelin tower"}, note = "The Orgrimmar zeppelin leaves from the tower beside Grom'gol; it lands just outside Orgrimmar's main gate.", title = "Zeppelin to Orgrimmar"},
	{{"note", "Train new spells at your class trainer", only = {classes = {"WARRIOR", "HUNTER", "ROGUE", "PRIEST", "SHAMAN", "MAGE", "WARLOCK"}}}, {"accept", 3631, at = {1454, 48.47, 45.43}, only = {classes = {"WARLOCK"}}, who = "Zevrost"}, title = "Orgrimmar"},
	{{"note", "Train new spells at your class trainer", optional = true}, {"note", "Wolves: Ogunaro Wolfrunner, beside Kildar.", only = {races = {"Orc"}}}, {"note", "Galestriders: Genn Fairweather, in Valanaar on Zephras Isle.", only = {races = {"Skyborne"}}}, note = "Riding needs level 40 and costs 100 gold; learning it gives you a mount. Kildar teaches Orcs in the Valley of Honor, by Ogunaro Wolfrunner's kennel; no Skyborne riding trainer is known, so Skyborne try Kildar too. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each.", only = {races = {"Orc", "Skyborne"}}, title = "Riding at 40"},
	{{"note", "Train new spells at your class trainer", optional = true}, {"note", "Raptors: Zjolnir, beside Xar'Ti in Sen'jin Village."}, note = "Riding needs level 40 and costs 100 gold; learning it gives you a mount. In Classic each race learns it from its own race's trainer: yours is Xar'Ti in Sen'jin Village on the Durotar coast, with Zjolnir's raptors (20 gold each) beside him. Forever may let any race learn from any riding trainer (not confirmed): try Kildar in Orgrimmar's Valley of Honor first, as he is the nearest, and skip this step if he teaches you.", only = {races = {"Troll"}}, title = "Riding at 40"},
	{{"note", "Train new spells at your class trainer", optional = true}, {"note", "Kodos: Harb Clawhoof, beside Kar Stormsinger in Bloodhoof Village."}, note = "Riding needs level 40 and costs 100 gold; learning it gives you a mount. In Classic each race learns it from its own race's trainer: yours is Kar Stormsinger in Bloodhoof Village, with Harb Clawhoof's kodos (20 gold each) beside him. Forever may let any race learn from any riding trainer (not confirmed): try Kildar in Orgrimmar's Valley of Honor first, as he is the nearest, and skip this step if he teaches you.", only = {races = {"Tauren"}}, title = "Riding at 40"},
	{{"note", "Train new spells at your class trainer", optional = true}, {"note", "Skeletal horses: Zachariah Post, beside Velma Warnam in Brill."}, note = "Riding needs level 40 and costs 100 gold; learning it gives you a mount. In Classic each race learns it from its own race's trainer: yours is Velma Warnam in Brill, with Zachariah Post's skeletal horses (20 gold each) beside her. Forever may let any race learn from any riding trainer (not confirmed): try Kildar in Orgrimmar's Valley of Honor first, as he is the nearest, and skip this step if he teaches you.", only = {races = {"Scourge"}}, title = "Riding at 40"},
	{{"note", "Fly to Thunder Bluff"}, {"note", "Train new spells at your class trainer"}, note = "Your trainer is in Thunder Bluff: Turak Runetotem (Druids) on Elder Rise, Alodan the Hopeful (Paladins). Fly there from Orgrimmar, then on to Freewind Post.", only = {classes = {"PALADIN", "DRUID"}}, title = "Thunder Bluff"},
	{{"note", "Fly to Ratchet"}, {"turnin", 3631, at = {1413, 62.63, 35.5}, who = "Strahad Farsan"}, {"accept", 4490, at = {1413, 62.63, 35.5}, who = "Strahad Farsan"}, {"turnin", 4490, at = {1413, 62.63, 35.5}, who = "Strahad Farsan"}, only = {classes = {"WARLOCK"}}, title = "Ratchet for the Felsteed"},
	{{"note", "Fly to Freewind Post"}, note = "Fly to Freewind Post, ride down the lift east of the post and across the salt flats, then south into Tanaris.", title = "Fly to Freewind Post"},
	{{"goto", 1446, 51.6, 25.44, "Get the flight path at Gadgetzan"}, {"turnin", 2864, at = {1446, 51.57, 26.76}, who = "Tran'rek"}, {"accept", 2875, at = {1446, 51.83, 27.04}, who = "Wanted Poster"}, {"accept", 1690, at = {1446, 52.46, 28.51}, who = "Chief Engineer Bilgewhizzle"}, {"accept", 1707, at = {1446, 52.49, 28.45}, who = "Spigot Operator Luglunket"}, note = "Gadgetzan is the walled goblin town just past the Tanaris border.", title = "Gadgetzan"},
