	{{"complete", 1691, at = {1446, 58.93, 35.85}}, note = "The shadow mages, rogues and assassins camp south-east of Gadgetzan.", title = "Southern Wastewander camps"},
	{{"accept", 8365, at = {1446, 66.56, 22.27}, who = "Haughty Modiste"}, {"accept", 3520, at = {1446, 66.99, 22.36}, who = "Yeh'kinya"}, {"turnin", 2872, at = {1446, 67.11, 23.98}, who = "Stoley"}, {"accept", 2873, at = {1446, 67.11, 23.98}, who = "Stoley"}, {"accept", 8366, at = {1446, 67.06, 23.89}, who = "Security Chief Bilgewhizzle"}, note = "Ride north-east to the goblin harbour on the coast.", title = "Steamwheedle Port"},
