	{{"complete", 2973, at = {1444, 70.15, 46.59}}, {"complete", 2863, at = {1444, 66.09, 51.56}}, note = "The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour.", title = "Sprite darters and Woodpaw alphas"},
	{{"turnin", 2863, at = {1444, 74.91, 42.46}, who = "Hadoken Swiftstrider"}, {"accept", 2902, at = {1444, 74.91, 42.46}, who = "Hadoken Swiftstrider"}, {"turnin", 2973, at = {1444, 75.94, 42.74}, who = "Krueg Skullsplitter"}, {"accept", 2974, at = {1444, 75.94, 42.74}, who = "Krueg Skullsplitter"}, title = "Camp Mojache"},
	{{"complete", 2974, at = {1444, 69.93, 39.96}}, note = "The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns.", title = "Grimtotem camp"},
	{{"turnin", 2902, at = {1444, 71.63, 55.92}, who = "Woodpaw Battle Map"}, {"accept", 2903, at = {1444, 71.63, 55.92}, who = "Woodpaw Battle Map"}, note = "The battle map lies in the Woodpaw camp south of Mojache.", title = "Woodpaw battle map"},
	{{"complete", 2980, at = {1444, 61.78, 54.65}}, {"complete", 2979, at = {1444, 60.27, 67.24}}, note = "Ride south-west to the ogre ruins below Feral Scar Vale. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb.", title = "Southern Gordunni ruins"},
	{{"turnin", 2974, at = {1444, 75.94, 42.74}, who = "Krueg Skullsplitter"}, {"accept", 2976, at = {1444, 75.94, 42.74}, who = "Krueg Skullsplitter"}, {"turnin", 2903, at = {1444, 74.91, 42.46}, who = "Hadoken Swiftstrider"}, {"accept", 7730, at = {1444, 74.91, 42.46}, who = "Hadoken Swiftstrider"}, {"accept", 7731, at = {1444, 74.91, 42.46}, who = "Hadoken Swiftstrider"}, {"turnin", 2979, at = {1444, 75.8, 43.58}, who = "Rok Orhan"}, {"turnin", 2980, at = {1444, 75.8, 43.58}, who = "Rok Orhan"}, {"accept", 3002, at = {1444, 75.8, 43.58}, who = "Rok Orhan"}, title = "Camp Mojache"},
	{{"complete", 7730, at = {1444, 76.22, 59.25}}, {"complete", 7731, at = {1444, 75.6, 60.9}}, note = "The Zukk'ash hive burrows into the hills south-east of the camp; Stinglasher waits in its deepest chamber.", title = "The Writhing Deep"},
	{{"turnin", 7730, at = {1444, 74.91, 42.46}, who = "Hadoken Swiftstrider"}, {"turnin", 7731, at = {1444, 74.91, 42.46}, who = "Hadoken Swiftstrider"}, {"note", "Sell and repair"}, title = "Camp Mojache"},
	{{"note", "Use Yeh'kinya's Bramble"}, {"complete", 3520, at = {1444, 46, 37.69}}, note = "Ride west into the middle of Feralas. Kill a Rogue Vale Screecher, use Yeh'kinya's Bramble on its body and kill the spirit that rises.", title = "Rogue Vale screechers"},
	{{"have", 8705, 1, at = {1444, 50.67, 33.75}, name = "OOX-22/FE Distress Beacon", optional = true}, {"accept", 2766, optional = true}, note = "Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest.", title = "The Forgotten Coast"},
	{{"turnin", 2766, at = {1444, 53.35, 55.7}, optional = true, who = "Homing Robot OOX-22/FE"}, {"accept", 2767, at = {1444, 53.35, 55.7}, optional = true, who = "Homing Robot OOX-22/FE"}, {"complete", 2767, optional = true}, note = "Only with the distress beacon: the robot sits in a small cave on the north side of Feral Scar Vale. Escort it to the dock on the Forgotten Coast; yetis and gorillas ambush you on the way. Its reward waits in Booty Bay for a later visit.", title = "Homing Robot OOX-22/FE"},
