	{{"complete", 1426, at = {1435, 87.1, 80.66}}, note = "The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore.", title = "Murlocs of the Misty Reed"},
