	{{"accept", 2981, at = {1454, 75.23, 34.24}, who = "Belgrom Rockmaul"}, {"turnin", 2976, at = {1454, 75.23, 34.24}, who = "Belgrom Rockmaul"}, {"turnin", 3121, at = {1454, 49.47, 50.59}, who = "Neeru Fireblade"}, {"accept", 3122, at = {1454, 49.47, 50.59}, who = "Neeru Fireblade"}, {"turnin", 3002, at = {1454, 39.16, 86.27}, who = "Uthel'nay"}, {"note", "Train new spells at your class trainer", only = {classes = {"WARRIOR", "HUNTER", "ROGUE", "PRIEST", "SHAMAN", "MAGE", "WARLOCK"}}}, note = "Valley of Honor, then the Cleft of Shadow and the Valley of Spirits.", title = "Orgrimmar"},
	{{"note", "Fly to Thunder Bluff"}, {"goto", 1456, 47, 49.83, "Get the flight path at Thunder Bluff"}, {"note", "Train new spells at your class trainer"}, note = "Your trainer is in Thunder Bluff: fly there (no flight path there yet? fly to Camp Taurajo and ride west through Mulgore), then on to Brackenwall Village.", only = {classes = {"PALADIN", "DRUID"}}, title = "Thunder Bluff"},
	{{"note", "Fly to Brackenwall Village"}, {"accept", 1166, at = {1445, 36.29, 31.41}, who = "Overlord Mok'Morokk"}, {"accept", 1168, at = {1445, 37.37, 31.39}, who = "Tharg"}, {"accept", 1169, at = {1445, 37.15, 33.09}, who = "Draz'Zilb"}, title = "Brackenwall Village"},
