	{{"turnin", 1166, at = {1445, 36.29, 31.41}, who = "Overlord Mok'Morokk"}, {"turnin", 1168, at = {1445, 37.37, 31.39}, who = "Tharg"}, {"turnin", 1169, at = {1445, 37.15, 33.09}, who = "Draz'Zilb"}, {"accept", 1170, at = {1445, 37.15, 33.09}, who = "Draz'Zilb"}, {"turnin", 1170, at = {1445, 36.29, 31.41}, who = "Overlord Mok'Morokk"}, {"accept", 1171, at = {1445, 36.29, 31.41}, who = "Overlord Mok'Morokk"}, {"turnin", 1171, at = {1445, 37.15, 33.09}, who = "Draz'Zilb"}, {"accept", 1172, at = {1445, 37.15, 33.09}, who = "Draz'Zilb"}, note = "Ride back north to Brackenwall.", title = "Brackenwall Village"},
	{{"goto", 1445, 53.4, 74.7, "Dragon caves"}, {"complete", 1172}, note = "The Eggs of Onyxia lie in the dragon caves in the Wyrmbog's south-east, guarded by the scalebanes; smash five.", title = "Onyxia's eggs"},
	{{"turnin", 1172, at = {1445, 37.15, 33.09}, who = "Draz'Zilb"}, note = "Ride back north to Brackenwall.", title = "Brackenwall Village"},
	{{"accept", 1173, at = {1445, 36.29, 31.41}, optional = true, who = "Overlord Mok'Morokk"}, {"complete", 1173, optional = true}, {"turnin", 1173, at = {1445, 37.15, 33.09}, optional = true, who = "Draz'Zilb"}, note = "Overlord Mok'Morokk is elite: grouping up is advised. Beat him down until he gives up, then report to Draz'Zilb.", title = "Challenge Overlord Mok'Morokk"},
	{{"note", "Fly to Camp Mojache"}, {"bind", "Camp Mojache", at = {1444, 74.8, 45.18}, who = "Innkeeper Greul"}, {"turnin", 2981, at = {1444, 75.8, 43.58}, who = "Rok Orhan"}, {"turnin", 3122, at = {1444, 74.42, 43.36}, who = "Witch Doctor Uzer'i"}, {"accept", 3123, at = {1444, 74.42, 43.36}, who = "Witch Doctor Uzer'i"}, {"accept", 3128, at = {1444, 74.42, 43.36}, who = "Witch Doctor Uzer'i"}, {"accept", 2822, at = {1444, 74.43, 42.91}, who = "Jangdor Swiftstrider"}, {"accept", 3063, at = {1444, 76.18, 43.83}, who = "Talo Thornhoof"}, {"accept", 7732, at = {1444, 74.91, 42.46}, who = "Hadoken Swiftstrider"}, title = "Camp Mojache"},
	{{"complete", 3128, at = {1444, 70.15, 46.59}}, {"goto", 1444, 60.6, 47.4, "Forest walkers"}, note = "The sprite darters flit over the grove just west of the camp and carry the Encrusted Minerals; the Wandering Forest Walkers, a little further west, carry the Splintered Logs.", title = "Sprite darters and forest walkers"},
	{{"complete", 2822, at = {1444, 55.29, 53.76}}, note = "South-west, the yetis den in Feral Scar Vale; every yeti there can drop a thick hide.", title = "Feral Scar Vale"},
	{{"complete", 3128, at = {1444, 54.92, 60.82}}, note = "South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments.", title = "Frayfeather hippogryphs"},
	{{"accept", 7003, at = {1444, 44.81, 43.42}, who = "Zorbin Fandazzle"}, {"accept", 7721, at = {1444, 44.81, 43.42}, who = "Zorbin Fandazzle"}, note = "Ride north-west to the Forgotten Coast; Zorbin waits on the dock.", title = "Zorbin Fandazzle"},
	{{"complete", 7721, at = {1444, 44.97, 46.29}}, {"complete", 7003, at = {1444, 44.34, 46.61}}, note = "Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with Zorbin's Ultra-Shrinker first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north.", title = "The Forgotten Coast"},
	{{"turnin", 7003, at = {1444, 44.81, 43.42}, who = "Zorbin Fandazzle"}, {"turnin", 7721, at = {1444, 44.81, 43.42}, who = "Zorbin Fandazzle"}, title = "Zorbin Fandazzle"},
	{{"complete", 3063, at = {1444, 40.1, 15.47}}, note = "The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time.", title = "Northspring harpies"},
	{{"note", "Hearth to Camp Mojache"}, {"turnin", 2822, at = {1444, 74.43, 42.91}, who = "Jangdor Swiftstrider"}, {"accept", 7734, at = {1444, 74.43, 42.91}, who = "Jangdor Swiftstrider"}, {"turnin", 3128, at = {1444, 74.42, 43.36}, who = "Witch Doctor Uzer'i"}, {"turnin", 3063, at = {1444, 76.18, 43.83}, who = "Talo Thornhoof"}, title = "Camp Mojache"},
	{{"complete", 7734, at = {1444, 55.73, 33.05}}, {"have", 18972, 1, at = {1444, 55.73, 33.05}, name = "Perfect Yeti Hide", optional = true}, {"accept", 7738, optional = true}, note = "North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a Perfect Yeti Hide, which starts a quest of its own.", title = "Rage Scar yetis"},
	{{"turnin", 7734, at = {1444, 74.43, 42.91}, who = "Jangdor Swiftstrider"}, {"turnin", 7738, at = {1444, 74.43, 42.91}, optional = true, who = "Jangdor Swiftstrider"}, note = "Ride back east to the camp. Stay here: the next guide starts with the flight to Gadgetzan.", title = "Camp Mojache"},
} })

