	{{"accept", 3161, at = {1446, 52.71, 45.92}, who = "Marvon Rivetseeker"}, note = "West along the road south; Marvon camps by the ruins at the Broken Pillar. Put on his Gahz'ridian Detector: it shows the buried ornaments, here and around the Dunemaul Compound.", title = "Marvon Rivetseeker"},
