	{{"complete", 5863, at = {1446, 39.27, 51.2}}, {"complete", 3161, at = {1446, 38.3, 61.9}}, note = "South of the Noxious Lair the Dunemaul ogres hold their compound, with Gor'marok the Ravager at its eastern end. Dig up Gahz'ridian ornaments between the fights.", title = "Dunemaul Compound"},
	{{"complete", 3362, at = {1446, 31.22, 65.54}}, {"complete", 2605, at = {1446, 29.2, 66.1}}, {"have", 8623, 1, at = {1446, 30.37, 77.65}, name = "OOX-17/TN Distress Beacon", optional = true}, note = "West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in Tanaris can drop OOX-17/TN's distress beacon, rarely: keep it if you see one.", title = "Thistleshrub Valley"},
