	{{"note", "Fly to Thunder Bluff"}, {"note", "Train new spells at your class trainer"}, note = "Fly to Thunder Bluff and train with Turak Runetotem on Elder Rise, then fly to Ratchet.", only = {classes = {"DRUID"}}, title = "Thunder Bluff"},
