	{{"goto", 1427, 34.84, 30.87, "Get the flight path at Thorium Point"}, {"accept", 7728, at = {1427, 37.65, 26.47}, who = "Wanted/Missing/Lost & Found"}, {"accept", 7729, at = {1427, 37.65, 26.47}, who = "Wanted/Missing/Lost & Found"}, {"accept", 7723, at = {1427, 38.58, 27.81}, who = "Hansel Heavyhands"}, {"accept", 7724, at = {1427, 38.58, 27.81}, who = "Hansel Heavyhands"}, {"accept", 7727, at = {1427, 38.58, 27.81}, who = "Hansel Heavyhands"}, {"accept", 7722, at = {1427, 38.8, 28.51}, who = "Master Smith Burninate"}, note = "Ride north-west across the gorge; Thorium Point is the scaffolded camp in the north-west.", title = "Thorium Point"},
