	{{"complete", 7723, at = {1427, 41.66, 41.39}}, {"complete", 3442, at = {1427, 41.66, 41.39}}, {"complete", 7729, at = {1427, 43.12, 40.37}}, {"have", 11818, 1, at = {1427, 42.81, 40.54}, name = "Grimesilt Outhouse Key", optional = true}, note = "Heavy War Golems patrol the Cauldron below Kalaran and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the Grimesilt Outhouse Key: keep it.", title = "The Cauldron"},
	{{"turnin", 3442, at = {1427, 39.06, 38.99}, who = "Kalaran Windblade"}, {"accept", 3443, at = {1427, 39.06, 38.99}, who = "Kalaran Windblade"}, title = "Kalaran Windblade"},
	{{"complete", 3443, at = {1427, 39.14, 37.86}}, {"complete", 7728, at = {1427, 40.01, 48.33}}, note = "The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a Thorium Plated Dagger, one in ten the Smithing Tuyere. Slaves, Slavers and Taskmasters carry daggers too.", title = "The Steamsmiths' furnaces"},
	{{"turnin", 3443, at = {1427, 39.06, 38.99}, who = "Kalaran Windblade"}, {"note", "His next request needs the Symbol of Ragnaros from elite cultists: leave it."}, title = "Kalaran Windblade"},
	{{"complete", 7727, at = {1427, 43.38, 28.26}}, {"complete", 7722, at = {1427, 40.5, 35.7}}, note = "The Slag Pit opens in the north of the Cauldron. Incendosaurs swim in its lava pools: pull them to the edge. The secret plans lie on the pit's upper ledge.", title = "The Slag Pit"},
	{{"complete", 7724, at = {1427, 38.01, 33.34}}, note = "The Greater Lava Spiders roam the plateaus and lava pools in the south-west of the gorge.", title = "Greater Lava Spiders"},
	{{"complete", 7728, at = {1427, 33.71, 51.92}}, note = "The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the Lookout's Spyglass.", title = "Dark Iron Lookouts"},
	{{"accept", 4451, optional = true}, {"turnin", 4451, at = {1427, 65.59, 62.17}, optional = true, who = "Wooden Outhouse"}, note = "Only with the Grimesilt Outhouse Key: back east to the Wooden Outhouse at the dig site.", title = "The Key to Freedom"},
	{{"turnin", 7723, at = {1427, 38.58, 27.81}, who = "Hansel Heavyhands"}, {"turnin", 7724, at = {1427, 38.58, 27.81}, who = "Hansel Heavyhands"}, {"turnin", 7727, at = {1427, 38.58, 27.81}, who = "Hansel Heavyhands"}, {"turnin", 7728, at = {1427, 38.97, 27.51}, who = "Taskmaster Scrange"}, {"turnin", 7729, at = {1427, 38.97, 27.51}, who = "Taskmaster Scrange"}, {"turnin", 7722, at = {1427, 38.8, 28.51}, who = "Master Smith Burninate"}, note = "Ride back north to Thorium Point. Stay here: the next guide starts with the flight to Stonard.", title = "Thorium Point"},
} })

