	{{"complete", 2995, at = {1425, 28.56, 46.05}}, {"accept", 2742, at = {1425, 30.73, 46.9}, who = "Rin'ji"}, {"complete", 2742}, note = "The Highvale elves camp around Quel'Danil Lodge. Burn the report, the notes and the records in their camps. Rin'ji is held inside the lodge: lead him out and fight off the ambush on the way.", title = "Highvale"},
	{{"have", 9320, 20, at = {1425, 31.61, 56.52}, name = "Witherbark Skull"}, {"note", "Use Nimboya's Pike"}, {"note", "Use Nimboya's Laden Pike"}, {"complete", 2932}, note = "South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use Nimboya's Pike to make the Laden Pike, then plant it inside the village.", title = "Grim Message"},
	{{"complete", 2641, at = {1425, 40.6, 59.7}}, note = "East of the village, the violet flower grows in the hills.", title = "Violet Tragan"},
	{{"turnin", 1429, at = {1425, 33.75, 75.21}, who = "Atal'ai Exile"}, note = "South-west again, the exile hides by the ruins of Shadra'Alor.", title = "The Atal'ai Exile"},
	{{"accept", 7839, at = {1425, 77.23, 80.13}, who = "Smith Slagtree"}, {"bind", "Revantusk Village", at = {1425, 78.14, 81.38}, who = "Lard"}, {"accept", 7840, at = {1425, 78.14, 81.38}, who = "Lard"}, {"accept", 7850, at = {1425, 78.2, 81.18}, who = "Primal Torntusk"}, {"accept", 7845, at = {1425, 78.2, 81.18}, who = "Primal Torntusk"}, {"accept", 7844, at = {1425, 78.8, 78.25}, who = "Mystic Yayo'jin"}, {"accept", 7841, at = {1425, 79.38, 79.08}, who = "Otho Moji'ko"}, {"accept", 7828, at = {1425, 79.16, 79.53}, who = "Huntsman Markhor"}, {"accept", 7829, at = {1425, 79.16, 79.53}, who = "Huntsman Markhor"}, {"accept", 7830, at = {1425, 79.16, 79.53}, who = "Huntsman Markhor"}, {"accept", 7849, at = {1425, 79.16, 79.53}, who = "Huntsman Markhor"}, {"accept", 7815, at = {1425, 80.33, 81.54}, who = "Katoom the Angler"}, {"goto", 1425, 81.7, 81.76, "Get the flight path at Revantusk Village"}, note = "Follow the roads east across the Hinterlands to the troll village on the eastern coast.", title = "Revantusk Village"},
	{{"complete", 7815, at = {1425, 80.56, 77.29}}, {"have", 8704, 1, at = {1425, 69.33, 62.4}, name = "OOX-09/HL Distress Beacon", optional = true}, note = "The big turtles crawl along the beaches north of the village. Whiskey Slim's port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it.", title = "Saltwater Snapjaws"},
	{{"turnin", 2742, at = {1425, 86.3, 59.01}, who = "Rin'ji's Secret"}, {"accept", 2782, at = {1425, 86.3, 59.01}, who = "Rin'ji's Secret"}, note = "The secret lies on the Overlook Cliffs, above the beach.", title = "Rin'ji's Secret"},
	{{"complete", 7840, at = {1425, 84.5, 41.2}}, note = "North along the coast, Lard's picnic basket is on the small island; a Vilebranch Kidnapper guards it.", title = "Lard's lunch"},
	{{"complete", 7844, at = {1425, 71.9, 47.17}}, {"complete", 7839, at = {1425, 71, 48.6}}, note = "West of the island, the Vilebranch scalpers hold the temples of Agol'watha and Shaol'watha. Slagtree's tools lie at one of the temples.", title = "The Vilebranch temples"},
	{{"complete", 7828, at = {1425, 69.32, 49.77}}, {"complete", 7829, at = {1425, 64.8, 50.6}}, {"complete", 7830, at = {1425, 65, 51.6}}, {"complete", 3123, at = {1425, 64.8, 50.6}}, {"have", 4589, 10, at = {1425, 65, 51.6}, name = "Long Elegant Feather"}, note = "The Silvermane Stalkers, Savage Owlbeasts and Razorbeak Skylords share the hills between the temples and Skulk Rock. Use the Wildkin Muisek Vessel on the owlbeasts you kill. The Skylords also drop Long Elegant Feathers: keep ten for Otho's second message.", title = "The central hills"},
	{{"complete", 77, at = {1425, 59.99, 42.49}}, note = "The crates of Hinterlands Honey Ripple lie around the abandoned Horde camp at Skulk Rock, among the oozes.", title = "Skulk Rock"},
	{{"accept", 485, optional = true}, {"turnin", 485, at = {1425, 49.35, 37.66}, optional = true, who = "Homing Robot OOX-09/HL"}, {"accept", 836, at = {1425, 49.35, 37.66}, optional = true, who = "Homing Robot OOX-09/HL"}, {"complete", 836, optional = true}, note = "Only with the distress beacon: the robot sits at the head of the river west of Skulk Rock. Escort it east to the shore beyond the Overlook Cliffs; its reward waits with Oglethorpe in Booty Bay.", title = "OOX-09/HL"},
	{{"complete", 7828, at = {1425, 51.06, 40.58}}, note = "South-west, the Silvermane Howlers roam the hills east of the Witherbark villages.", title = "Silvermane Howlers"},
	{{"complete", 7841, at = {1425, 33.93, 43.23}}, note = "Back west to Quel'Danil Lodge; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it.", title = "Highvale"},
	{{"turnin", 77, at = {1425, 26.71, 48.59}, who = "Gilveradin Sunchaser"}, {"accept", 81, at = {1425, 26.71, 48.59}, who = "Gilveradin Sunchaser"}, title = "Gilveradin's camp"},
	{{"complete", 7844, at = {1425, 44.57, 65.48}}, note = "On the way back east, the Vilebranch soothsayers hold the Altar of Zul, the troll temple south of the central hills. Qiaga and Morta'gya the Keeper (elite, 50) stand at its top: take the soothsayers on the lower steps.", title = "Vilebranch soothsayers"},
	{{"complete", 7849, at = {1425, 58.6, 64.8}}, {"complete", 7850, at = {1425, 63.56, 73.42}}, {"turnin", 7845, at = {1425, 59.69, 77.84}, who = "Elder Torntusk"}, {"note", "His next request, going on to the Altar of Zul, is for a group."}, note = "Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of Jintha'Alor. The Vessels of Tainted Blood sit on the lower terraces, and Elder Torntusk is held at the top. Keep to the paths: the trolls inside are elite.", title = "Jintha'Alor"},
	{{"turnin", 7815, at = {1425, 80.33, 81.54}, who = "Katoom the Angler"}, {"turnin", 7840, at = {1425, 78.14, 81.38}, who = "Lard"}, {"turnin", 7839, at = {1425, 77.23, 80.13}, who = "Smith Slagtree"}, {"turnin", 7844, at = {1425, 78.8, 78.25}, who = "Mystic Yayo'jin"}, {"turnin", 7841, at = {1425, 79.38, 79.08}, who = "Otho Moji'ko"}, {"accept", 7842, at = {1425, 79.38, 79.08}, who = "Otho Moji'ko"}, {"turnin", 7842, at = {1425, 79.38, 79.08}, who = "Otho Moji'ko"}, {"accept", 7843, at = {1425, 79.38, 79.08}, who = "Otho Moji'ko"}, {"turnin", 7828, at = {1425, 79.16, 79.53}, who = "Huntsman Markhor"}, {"turnin", 7829, at = {1425, 79.16, 79.53}, who = "Huntsman Markhor"}, {"turnin", 7830, at = {1425, 79.16, 79.53}, who = "Huntsman Markhor"}, {"turnin", 7849, at = {1425, 79.16, 79.53}, who = "Huntsman Markhor"}, {"turnin", 7850, at = {1425, 78.2, 81.18}, who = "Primal Torntusk"}, title = "Revantusk Village"},
	{{"goto", 1425, 14.3, 48.1, "Aerie Peak well"}, {"complete", 7843}, note = "Ride all the way west to the Wildhammer town of Aerie Peak and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out.", title = "Aerie Peak"},
	{{"note", "Hearth to Revantusk Village"}, {"turnin", 7843, at = {1425, 79.38, 79.08}, who = "Otho Moji'ko"}, note = "The next guide starts here, at Revantusk Village.", title = "Revantusk Village"},
} })

