	{{"complete", 5535, at = {1447, 14.7, 73.48}}, {"complete", 5536, at = {1447, 19.22, 62.67}}, note = "The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north.", title = "Highborne and Haldarr satyrs"},
	{{"turnin", 5535, at = {1447, 11.37, 78.17}, who = "Loh'atu"}, {"turnin", 5536, at = {1447, 11.37, 78.17}, who = "Loh'atu"}, note = "Back to Loh'atu at the shrine; stay west of the Talrendis Point guards.", title = "Loh'atu"},
	{{"goto", 1447, 21.96, 49.62, "Get the flight path at Valormok"}, {"accept", 3517, at = {1447, 22.56, 51.42}, who = "Jediga"}, {"accept", 3381, at = {1447, 28.11, 50.09}, name = "A Meeting with the Master", optional = true, who = "Sanath Lim-yo"}, note = "Follow the road north to Valormok, the Horde camp.", title = "Valormok"},
	{{"complete", 3381, at = {1447, 21.11, 54.18}, name = "A Meeting with the Master", optional = true}, note = "The Thunderhead Hippogryphs fly over the hills just south of Valormok.", title = "Undamaged Hippogryph Feathers"},
	{{"turnin", 3381, at = {1447, 28.11, 50.09}, name = "A Meeting with the Master", optional = true, who = "Sanath Lim-yo"}, title = "Sanath Lim-yo"},
