	{{"turnin", 3601, at = {1447, 53.45, 21.82}, who = "Kim'jael"}, {"accept", 5534, at = {1447, 53.45, 21.82}, who = "Kim'jael"}, title = "Kim'jael"},
	{{"complete", 3517, at = {1447, 39.6, 48.14}}, {"complete", 5534, at = {1447, 35, 52.01}}, note = "Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry Kim'jael's rune.", title = "Ruins of Eldarath"},
	{{"turnin", 5534, at = {1447, 53.45, 21.82}, who = "Kim'jael"}, note = "Back north-east to Kim'jael.", title = "Kim'jael"},
