	{{"goto", 1434, 32.2, 27.7, "Grom'gol Base Camp"}, note = "Fly from Valormok to Orgrimmar, walk out of the main gate to the zeppelin towers and take the zeppelin to Grom'gol.", title = "To Grom'gol"},
	{{"turnin", 2932, at = {1434, 32.16, 27.72}, who = "Nimboya"}, {"accept", 588, at = {1434, 32.22, 27.6}, who = "Bubbling Cauldron"}, {"turnin", 588, at = {1434, 32.27, 27.71}, who = "Kin'weelay"}, {"accept", 589, at = {1434, 32.27, 27.71}, who = "Kin'weelay"}, title = "Grom'gol Base Camp"},
	{{"complete", 589, at = {1434, 42.71, 45.84}}, note = "Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often.", title = "Ironjaw Basilisks"},
	{{"turnin", 2767, at = {1434, 28.36, 76.35}, optional = true, who = "Oglethorpe Obnoticus"}, {"turnin", 836, at = {1434, 28.36, 76.35}, optional = true, who = "Oglethorpe Obnoticus"}, {"turnin", 648, at = {1434, 28.36, 76.35}, optional = true, who = "Oglethorpe Obnoticus"}, {"accept", 3721, at = {1434, 28.36, 76.35}, optional = true, who = "Oglethorpe Obnoticus"}, {"turnin", 3721, at = {1434, 28.36, 76.35}, optional = true, who = "Oglethorpe Obnoticus"}, {"turnin", 2874, at = {1434, 27.78, 77.07}, who = "\"Sea Wolf\" MacKinley"}, note = "Continue south to Booty Bay. Oglethorpe Obnoticus has his workshop on the upper ring of the bay.", title = "Booty Bay"},
