	{{"note", "Fly to Thunder Bluff"}, {"goto", 1456, 47, 49.83, "Get the flight path at Thunder Bluff"}, {"turnin", 3784, at = {1456, 78.62, 28.56}, who = "Arch Druid Hamuul Runetotem"}, {"accept", 3761, at = {1456, 78.62, 28.56}, who = "Arch Druid Hamuul Runetotem"}, {"turnin", 3518, at = {1456, 69.85, 30.91}, who = "Magatha Grimtotem"}, {"accept", 3562, at = {1456, 69.85, 30.91}, who = "Magatha Grimtotem"}, {"note", "Train new spells at your class trainer", only = {classes = {"PALADIN", "DRUID"}}}, {"note", "Un'Goro Soil is gathered in the next guide; Magatha's payment goes back to Jediga later."}, note = "Fly to Thunder Bluff; it is on the way to Camp Mojache. No flight path there yet? Fly to Camp Taurajo and ride west through Mulgore. Hamuul and Magatha are on the Elder Rise; Druids and Paladins train here (Turak Runetotem, Alodan the Hopeful).", title = "Thunder Bluff"},
	{{"note", "Fly to Camp Mojache"}, {"bind", "Camp Mojache", at = {1444, 74.8, 45.18}, who = "Innkeeper Greul"}, {"turnin", 3123, at = {1444, 74.42, 43.36}, who = "Witch Doctor Uzer'i"}, {"accept", 3124, at = {1444, 74.42, 43.36}, who = "Witch Doctor Uzer'i"}, {"accept", 3380, at = {1444, 74.42, 43.36}, who = "Witch Doctor Uzer'i"}, {"accept", 4120, at = {1444, 76.18, 43.83}, who = "Talo Thornhoof"}, {"note", "Keep Sunken Temple for Marvon in Tanaris."}, title = "Camp Mojache"},
	{{"complete", 3124, at = {1444, 57.98, 62.83}}, note = "The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body.", title = "Frayfeather Hippogryphs"},
	{{"turnin", 3124, at = {1444, 74.42, 43.36}, who = "Witch Doctor Uzer'i"}, {"accept", 3125, at = {1444, 74.42, 43.36}, who = "Witch Doctor Uzer'i"}, title = "Witch Doctor Uzer'i"},
	{{"complete", 3125, at = {1444, 70.15, 46.59}}, note = "The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill.", title = "Sprite Darters"},
	{{"turnin", 3125, at = {1444, 74.42, 43.36}, who = "Witch Doctor Uzer'i"}, {"accept", 3126, at = {1444, 74.42, 43.36}, who = "Witch Doctor Uzer'i"}, title = "Witch Doctor Uzer'i"},
	{{"complete", 3126, at = {1444, 73.9, 38.84}}, note = "The treants wander the forest roads between the camp and the middle of Feralas; there are only a few, so look along the paths.", title = "Wandering Forest Walkers"},
	{{"turnin", 3126, at = {1444, 74.42, 43.36}, who = "Witch Doctor Uzer'i"}, {"accept", 3127, at = {1444, 74.42, 43.36}, who = "Witch Doctor Uzer'i"}, title = "Witch Doctor Uzer'i"},
	{{"accept", 7725, at = {1444, 44.81, 43.42}, who = "Zorbin Fandazzle"}, {"accept", 7726, at = {1444, 44.81, 43.42}, who = "Zorbin Fandazzle"}, note = "Ride north-west to the Forgotten Coast; Zorbin waits on the dock.", title = "Zorbin Fandazzle"},
	{{"complete", 7725, at = {1444, 44.34, 46.61}}, {"complete", 3127, at = {1444, 39.9, 22.2}}, note = "The Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with Zorbin's Ultra-Shrinker first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too.", title = "Zapped giants"},
	{{"complete", 7726, at = {1444, 37.54, 33.08}}, note = "The Sea Elementals and Sea Sprays wash along the shore around the dock.", title = "Sea elementals"},
	{{"turnin", 7725, at = {1444, 44.81, 43.42}, who = "Zorbin Fandazzle"}, {"turnin", 7726, at = {1444, 44.81, 43.42}, who = "Zorbin Fandazzle"}, title = "Zorbin Fandazzle"},
