Pathwise.RegisterRoute({category = "Leveling", faction = "Horde", id = "forever/horde/50-60/01-un-goro-crater", levels = {50, 53}, map = 1449, next = "forever/horde/50-60/02-felwood", title = "Un'Goro Crater, Eastern Plaguelands & Burning Steppes", steps = {
	{{"goto", 1449, 45.23, 5.83, "Get the flight path at Marshal's Refuge"}, {"accept", 3881, at = {1449, 43.95, 7.14}, who = "Williden Marshal"}, {"accept", 3883, at = {1449, 43.89, 7.24}, who = "Hol'anyee Marshal"}, {"accept", 3882, at = {1449, 43.5, 7.42}, who = "Spark Nilminer"}, {"accept", 4501, at = {1449, 43.53, 8.44}, who = "Beware of Pterrordax"}, {"accept", 4492, at = {1449, 43.62, 8.5}, who = "Spraggle Frock"}, {"accept", 4145, at = {1449, 45.54, 8.72}, who = "Larion"}, {"accept", 4284, at = {1449, 41.92, 2.7}, who = "J.D. Collie"}, note = "From the Broken Pillar ride west to the long ramp that winds down into Un'Goro Crater, then follow the crater's north wall to Marshal's Refuge, a camp in the cliff caves. Everyone here is neutral.", title = "Into Un'Goro Crater"},
	{{"accept", 4503, at = {1449, 44.23, 11.59}, who = "Shizzle"}, {"accept", 4243, at = {1449, 46.38, 13.44}, who = "Karna Remtravel"}, {"note", "From here on pick up every Power Crystal (blue, green, red, yellow) and every Un'Goro Soil pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."}, title = "Out of the refuge"},
	{{"complete", 4504, at = {1449, 45.72, 15.49}}, note = "The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the Super Sticky Tar.", title = "Lakkari Tar Pits"},
	{{"complete", 4501, at = {1449, 39, 19.4}}, {"complete", 4145, at = {1449, 40.3, 23.29}}, note = "Ride south-west along the western cliffs. Frenzied Pterrordax fly over the west side, and Bloodpetal Trappers grow in the same jungle.", title = "Western jungle"},
	{{"complete", 3882, at = {1449, 32.85, 62.71}}, {"complete", 4503, at = {1449, 31.17, 62.9}}, {"complete", 4300, at = {1449, 57.36, 77.14}}, {"have", 11116, 1, at = {1449, 57.36, 77.14}, name = "A Mangled Journal", optional = true}, {"accept", 3884, optional = true}, note = "South of the hot springs, Stegodons graze and Dinosaur Bones drop from them or lie on the ground; Diemetradons nearby carry the scales Shizzle wants. Ravasaurs hunt in packs in the south-west: their claws are for Jes'rimon, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon.", title = "Stegodons and ravasaurs"},
	{{"complete", 3881, at = {1449, 38.5, 66.1}}, note = "The expedition's lost equipment lies in the south-west jungle.", title = "Research Equipment"},
	{{"complete", 4496, at = {1449, 45.5, 72.3}}, {"complete", 3883, at = {1449, 48.7, 85.3}}, {"complete", 4501, at = {1449, 50.4, 87.8}}, {"complete", 4503, at = {1449, 50.4, 87.8}}, note = "The silithid hive fills the south of the crater. Gorishi wasps and workers drop the scent gland; use the Scraping Vial on the egg mass inside the first chamber. The Hive Queen at the bottom is an elite boss: stay out of her chamber. Pterrordax nest on the cliffs above the hive; their scales are for Shizzle.", title = "The Gorishi hive"},
	{{"accept", 3844, at = {1449, 63.02, 68.6}, who = "A Wrecked Raft"}, {"turnin", 3844, at = {1449, 63.11, 69.06}, who = "A Small Pack"}, {"accept", 3845, at = {1449, 63.11, 69.06}, who = "A Small Pack"}, {"complete", 3845, at = {1449, 63.1, 69.1}}, note = "The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it.", title = "A Wrecked Raft"},
	{{"accept", 4289, at = {1449, 71.64, 75.96}, who = "Torwa Pathfinder"}, {"accept", 4290, at = {1449, 71.64, 75.96}, who = "Torwa Pathfinder"}, note = "Torwa camps in the south-east corner of the crater.", title = "Torwa Pathfinder"},
	{{"complete", 4290, at = {1449, 68.74, 56.71}}, note = "North of Torwa, a dead Threshadon lies by the water.", title = "Fresh Threshadon Carcass"},
	{{"turnin", 4290, at = {1449, 71.64, 75.96}, who = "Torwa Pathfinder"}, {"accept", 4291, at = {1449, 71.64, 75.96}, who = "Torwa Pathfinder"}, title = "Torwa Pathfinder"},
	{{"complete", 4291, at = {1449, 67, 73}}, note = "The Lar'korwi Mates prowl the jungle north-west of Torwa.", title = "Lar'korwi Mates"},
	{{"turnin", 4291, at = {1449, 71.64, 75.96}, who = "Torwa Pathfinder"}, {"accept", 4292, at = {1449, 71.64, 75.96}, who = "Torwa Pathfinder"}, {"note", "Keep the bait: Lar'korwi is level 56, and the second loop passes his lair."}, title = "Torwa Pathfinder"},
	{{"complete", 4145, at = {1449, 74.5, 44.1}}, note = "Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle.", title = "Lashers and Threshers"},
	{{"complete", 3881, at = {1449, 68.5, 36.5}}, note = "The expedition's crate sits at an abandoned camp in the eastern jungle.", title = "Crate of Foodstuffs"},
	{{"complete", 4289, at = {1449, 69.05, 17.64}}, {"turnin", 4243, at = {1449, 67.66, 16.76}, who = "A-Me 01"}, {"note", "A-Me 01 then wants a Mithril Casing, an Engineering item. Skip it unless you have one."}, note = "The gorillas live on the north-east plateau. Stay out of the deepest cave: U'cha lives there.", title = "Gorillas"},
	{{"complete", 4145, at = {1449, 59.95, 19.86}}, note = "Ride south-west to Fire Plume Ridge, the volcano in the middle of the crater. Bloodpetal Flayers grow around its foot.", title = "Bloodpetal Flayers"},
	{{"complete", 4284, at = {1449, 63.4, 23}}, {"complete", 3761, at = {1449, 61.11, 27.56}}, {"complete", 4496, at = {1449, 61.11, 27.56}}, note = "The crystal clusters stand all over the crater, many around Fire Plume Ridge. Take a few extra of each colour for the pylons.", title = "Power Crystals and soil"},
	{{"turnin", 4492, at = {1449, 51.9, 49.85}, who = "Ringo"}, {"accept", 4491, at = {1449, 51.9, 49.85}, who = "Ringo"}, note = "Ringo sits on the ridge, lost and exhausted.", title = "Ringo"},
	{{"complete", 4491}, note = "Lead Ringo north to Marshal's Refuge. When he faints, use Spraggle's Canteen on him to wake him.", title = "Escort Ringo"},
	{{"turnin", 4503, at = {1449, 44.23, 11.59}, who = "Shizzle"}, {"turnin", 4491, at = {1449, 43.62, 8.5}, who = "Spraggle Frock"}, {"turnin", 4501, at = {1449, 43.62, 8.5}, who = "Spraggle Frock"}, {"turnin", 4145, at = {1449, 45.54, 8.72}, who = "Larion"}, {"accept", 4147, at = {1449, 45.54, 8.72}, who = "Larion"}, {"turnin", 3845, at = {1449, 44.66, 8.1}, who = "Linken"}, {"accept", 3908, at = {1449, 44.66, 8.1}, who = "Linken"}, {"turnin", 3881, at = {1449, 43.95, 7.14}, who = "Williden Marshal"}, {"turnin", 3884, at = {1449, 43.95, 7.14}, optional = true, who = "Williden Marshal"}, {"turnin", 3883, at = {1449, 43.89, 7.24}, who = "Hol'anyee Marshal"}, {"turnin", 3882, at = {1449, 43.5, 7.42}, who = "Spark Nilminer"}, {"turnin", 4284, at = {1449, 41.92, 2.7}, who = "J.D. Collie"}, {"accept", 4285, at = {1449, 41.92, 2.7}, who = "J.D. Collie"}, {"accept", 4287, at = {1449, 41.92, 2.7}, who = "J.D. Collie"}, {"accept", 4288, at = {1449, 41.92, 2.7}, who = "J.D. Collie"}, {"note", "Keep Larion's Marvon's Workshop and Linken's letter for later guides."}, title = "Marshal's Refuge"},
	{{"goto", 1449, 56.5, 12.5, "Northern Crystal Pylon"}, {"complete", 4285}, note = "The pylon stands on the slope east of the refuge.", title = "Northern Pylon"},
	{{"goto", 1449, 77.2, 50, "Eastern Crystal Pylon"}, {"complete", 4287}, note = "Ride down the east side of the crater to the pylon on the eastern cliffs.", title = "Eastern Pylon"},
	{{"complete", 4292, at = {1449, 79.65, 49.83}}, note = "Lar'korwi's lair is just south of the pylon. Use Torwa's bait there; Lar'korwi is level 56 and hits hard, so start at full health.", title = "Lar'korwi"},
	{{"turnin", 4289, at = {1449, 71.64, 75.96}, who = "Torwa Pathfinder"}, {"turnin", 4292, at = {1449, 71.64, 75.96}, who = "Torwa Pathfinder"}, {"note", "Torwa now asks for U'cha's pelt, back in the north-east cave: skip it."}, title = "Torwa Pathfinder"},
	{{"goto", 1449, 23.9, 59.2, "Western Crystal Pylon"}, {"complete", 4288}, note = "Cross the south of the crater to the pylon on the western cliffs.", title = "Western Pylon"},
	{{"accept", 974, at = {1449, 30.93, 50.44}, who = "Krakle"}, note = "Krakle the goblin sits at Golakka Hot Springs, just east of the pylon.", title = "Krakle"},
	{{"complete", 974, at = {1449, 49.7, 45.6}}, note = "Ride east to Fire Plume Ridge, climb it and use Krakle's Thermometer at the lava vent near the top, then ride back west to Krakle.", title = "Krakle's Thermometer"},
	{{"turnin", 974, at = {1449, 30.93, 50.44}, who = "Krakle"}, {"accept", 980, at = {1449, 30.93, 50.44}, who = "Krakle"}, {"note", "Krakle sends you to Donova Snowden in Winterspring: keep it."}, title = "Krakle"},
	{{"turnin", 4285, at = {1449, 41.92, 2.7}, who = "J.D. Collie"}, {"turnin", 4287, at = {1449, 41.92, 2.7}, who = "J.D. Collie"}, {"turnin", 4288, at = {1449, 41.92, 2.7}, who = "J.D. Collie"}, {"accept", 4321, at = {1449, 41.92, 2.7}, who = "J.D. Collie"}, {"turnin", 4321, at = {1449, 41.92, 2.7}, who = "J.D. Collie"}, note = "Ride north back to Marshal's Refuge.", title = "J.D. Collie"},
	{{"level", 52}, note = "Theodora's quest in Kargath needs level 52. The Tar Lurkers and Tar Lords just south of the refuge are the closest camp.", title = "Lakkari Tar Pits"},
	{{"note", "Hearth to Gadgetzan"}, {"turnin", 4504, at = {1446, 51.57, 26.76}, who = "Tran'rek"}, {"turnin", 4496, at = {1446, 50.89, 26.96}, who = "Alchemist Pestlezugg"}, {"note", "Pestlezugg's next quest needs the Gorishi Hive Queen, an elite boss. Skip it."}, title = "Gadgetzan"},
	{{"note", "Fly to Orgrimmar"}, {"note", "Train new spells at your class trainer"}, note = "Fly to Orgrimmar and train before the Grom'gol zeppelin: the Undercity stop later in this guide has no Hunter or Shaman trainer.", only = {classes = {"HUNTER", "SHAMAN"}}, title = "Orgrimmar"},
	{{"note", "Fly to Thunder Bluff"}, {"note", "Train new spells at your class trainer"}, note = "Fly to Thunder Bluff and train with Turak Runetotem on Elder Rise, then fly to Orgrimmar for the Grom'gol zeppelin.", only = {classes = {"DRUID"}}, title = "Thunder Bluff"},
	{{"note", "Fly to Kargath"}, {"accept", 3821, at = {1418, 3.36, 48.06}, who = "Thal'trak Proudtusk"}, {"accept", 4061, at = {1418, 3.02, 47.81}, who = "Hierophant Theodora Mulvadania"}, note = "Fly to Orgrimmar, take the zeppelin to Grom'gol and fly from there to Kargath, built into the cliffs on the Badlands' west edge.", title = "Fly to Kargath"},
	{{"goto", 1427, 34.8, 83, "Bridge into Blackrock Mountain"}, note = "Take the pass out of Kargath's west side into the Searing Gorge, then ride south across the gorge to the long bridge into Blackrock Mountain. Inside, follow the chain walkways down and leave through the southern exit; stay off the paths to the dungeon portals.", title = "Into the Searing Gorge"},
	{{"goto", 1428, 65.69, 24.22, "Get the flight path at Flame Crest"}, {"accept", 4296, at = {1428, 65.15, 23.91}, who = "Maxwort Uberglint"}, {"accept", 4726, at = {1428, 65.24, 24}, who = "Tinkee Steamboil"}, note = "The mountain lets you out beside Blackrock Stronghold, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at Flame Crest.", title = "Flame Crest"},
	{{"complete", 4726, at = {1428, 81, 28}}, note = "Black Broodlings nest in the hills just east of Flame Crest. Use Tinkee's Draco-Incarcinatrix 900 on a broodling when it is almost dead to capture its essence.", title = "Black Broodlings"},
	{{"turnin", 3821, at = {1428, 79.95, 45.4}, who = "Sha'ni Proudtusk"}, {"accept", 3822, at = {1428, 79.95, 45.4}, who = "Sha'ni Proudtusk"}, note = "Follow the cliffs south to Dreadmaul Rock, the Firegut ogres' hill. Sha'ni Proudtusk's remains lie at its foot.", title = "Sha'ni Proudtusk"},
	{{"complete", 3822, at = {1428, 79.66, 47.43}}, note = "Krom'Grul walks the caves and mine tunnels of Dreadmaul Rock; if he isn't home, clear the ogres around the entrances until he comes back.", title = "Krom'Grul"},
	{{"complete", 4061, at = {1428, 85.81, 57.07}}, {"complete", 4296, at = {1428, 54.1, 40.8}}, note = "Ride west to the dig site. War Reaver golems (53) stomp around it and drop the shards often; the Tablet of the Seven stands in its middle among the Thaurissan dwarves. Copy it.", title = "Thaurissan dig site"},
	{{"turnin", 4296, at = {1428, 65.15, 23.91}, who = "Maxwort Uberglint"}, {"turnin", 4726, at = {1428, 65.24, 24}, who = "Tinkee Steamboil"}, {"accept", 4808, at = {1428, 65.24, 24}, who = "Tinkee Steamboil"}, {"note", "Keep Tinkee's letter: Felnok Steelspring is in Everlook, Winterspring."}, note = "Back north-east to Flame Crest.", title = "Flame Crest"},
	{{"note", "Fly to Kargath"}, {"turnin", 3822, at = {1418, 3.36, 48.06}, who = "Thal'trak Proudtusk"}, {"turnin", 4061, at = {1418, 3.02, 47.81}, who = "Hierophant Theodora Mulvadania"}, {"note", "Theodora's next errand goes to Lotwil east of town and then into Blackrock Depths: skip it."}, title = "Kargath"},
	{{"note", "Fly to Undercity"}, {"accept", 5094, at = {1458, 63.9, 44.08}, who = "Harbinger Balthazad"}, {"turnin", 3542, at = {1458, 54.81, 76.33}, who = "Andron Gant"}, {"accept", 3564, at = {1458, 54.81, 76.33}, who = "Andron Gant"}, {"accept", 3568, at = {1458, 48.71, 71.39}, who = "Chemist Cuely"}, {"note", "Train new spells at your class trainer", only = {classes = {"WARRIOR", "PALADIN", "ROGUE", "PRIEST", "MAGE", "WARLOCK"}}}, title = "Undercity"},
	{{"turnin", 5094, at = {1420, 83.13, 68.94}, who = "High Executor Derrington"}, {"accept", 5096, at = {1420, 83.13, 68.94}, who = "High Executor Derrington"}, {"accept", 5405, at = {1420, 83.19, 68.45}, who = "Argent Officer Garush"}, {"turnin", 5405, at = {1420, 83.19, 68.45}, who = "Argent Officer Garush"}, {"accept", 5407, at = {1420, 83.19, 68.45}, optional = true, who = "Argent Officer Garush"}, {"accept", 5408, at = {1420, 83.19, 68.45}, optional = true, who = "Argent Officer Garush"}, {"accept", 5901, at = {1420, 83.29, 72.34}, who = "Mickey Levine"}, {"note", "Take a Box of Incendiaries from the crate next to Derrington for Scarlet Diversions, done on the way back. Equip the Argent Dawn Commission: Scourgestones only drop while you wear it."}, note = "Leave the Undercity and ride east along the road through Tirisfal Glades to the Bulwark, the Forsaken fort on the border.", title = "The Bulwark"},
	{{"accept", 6164, at = {1423, 11.36, 26.37}, who = "Augustus the Touched"}, note = "Follow the road east through the Western Plaguelands and across the river into the Eastern Plaguelands; leave it north for Terrordale, the ruined town in the north-west. Augustus sits in a hut at its edge.", title = "Augustus the Touched"},
	{{"complete", 6164, at = {1423, 14.01, 24.22}}, note = "The book lies in the ruined inn of Terrordale.", title = "Augustus' Receipt Book"},
	{{"turnin", 6164, at = {1423, 11.36, 26.37}, who = "Augustus the Touched"}, title = "Augustus the Touched"},
	{{"complete", 5901, at = {1423, 15.91, 26.75}}, note = "The Large Termite Mounds stand all over the hills east of Terrordale. Use the Empty Termite Jar on each mound you pass.", title = "Termite mounds"},
	{{"goto", 1423, 70.53, 47.55, "Get the flight path at Light's Hope Chapel"}, {"bind", "Light's Hope Chapel", at = {1423, 71.8, 48.52}, who = "Jessica Chambers"}, {"accept", 5211, at = {1423, 71.7, 50.04}, who = "Carlin Redpath"}, {"accept", 6021, at = {1423, 69.93, 53.72}, who = "Caretaker Alen"}, {"accept", 5509, at = {1423, 71.63, 50.09}, optional = true, who = "Duke Nicholas Zverenhoff"}, {"accept", 5510, at = {1423, 71.63, 50.09}, optional = true, who = "Duke Nicholas Zverenhoff"}, note = "Ride south back to the road and follow it east across the whole zone to Light's Hope Chapel.", title = "Light's Hope Chapel"},
	{{"complete", 5211, at = {1423, 69.61, 46.79}}, {"complete", 5510, at = {1423, 68.77, 55.79}, optional = true}, {"complete", 5509, at = {1423, 69.79, 47.19}, optional = true}, note = "With Carlin's quest in your log, slain Scourge sometimes leave a Darrowshire Spirit; talk to it to free it. Kill undead on the ride south-west to Darrowshire.", title = "Darrowshire Spirits"},
	{{"accept", 5149, at = {1423, 31.15, 77.98}, who = "Pamela Redpath"}, note = "Pamela's ghost stands in the ruins of Darrowshire, in the south-west.", title = "Pamela Redpath"},
	{{"have", 12886, 1, at = {1423, 32.58, 79.56}, name = "Pamela's Doll's Head"}, {"have", 12887, 1, at = {1423, 32.72, 79.12}, name = "Pamela's Doll's Left Side"}, {"have", 12888, 1, at = {1423, 33.1, 79.67}, name = "Pamela's Doll's Right Side"}, {"complete", 5149, at = {1423, 32.99, 78.52}}, note = "The doll's head and its two sides lie in the houses around Pamela; join them from your bags.", title = "Pamela's Doll"},
	{{"turnin", 5149, at = {1423, 31.15, 77.98}, who = "Pamela Redpath"}, {"accept", 5152, at = {1423, 31.15, 77.98}, who = "Pamela Redpath"}, {"accept", 5241, at = {1423, 31.15, 77.98}, who = "Pamela Redpath"}, {"note", "Keep Auntie Marlene: Marlene lives at Sorrow Hill in the Western Plaguelands."}, title = "Pamela Redpath"},
	{{"complete", 6021, at = {1423, 23.07, 72.63}}, note = "Zaeldarr lurks just west of Darrowshire.", title = "Zaeldarr the Outcast"},
	{{"note", "Hearth to Light's Hope Chapel"}, {"turnin", 6021, at = {1423, 69.93, 53.72}, who = "Caretaker Alen"}, {"turnin", 5241, at = {1423, 71.7, 50.04}, who = "Carlin Redpath"}, {"turnin", 5211, at = {1423, 71.7, 50.04}, who = "Carlin Redpath"}, {"turnin", 5509, at = {1423, 71.63, 50.09}, optional = true, who = "Duke Nicholas Zverenhoff"}, {"turnin", 5510, at = {1423, 71.63, 50.09}, optional = true, who = "Duke Nicholas Zverenhoff"}, {"note", "The next guide starts here, at the chapel's flight master."}, title = "Back to Light's Hope Chapel"},
