Pathwise.RegisterRoute({category = "Leveling", faction = "Horde", id = "forever/horde/50-60/02-felwood", levels = {52, 54}, map = 1448, next = "forever/horde/50-60/03-winterspring", title = "Felwood & Western Plaguelands", steps = {
