	{{"note", "Scarlet Crusade Forward Camp"}, {"complete", 5096}, note = "The Scarlet Crusade's tents stand between Felstone Field and Dalson's Tears. Torch the command tent with the Box of Incendiaries and plant the Scourge banner.", title = "Scarlet forward camp"},
	{{"accept", 5058, at = {1422, 47.8, 50.67}, who = "Mrs. Dalson's Diary"}, {"turnin", 5058, at = {1422, 47.8, 50.67}, who = "Mrs. Dalson's Diary"}, {"accept", 5060, at = {1422, 47.35, 49.63}, who = "Locked Cabinet"}, {"accept", 5059, at = {1422, 48.11, 49.65}, who = "Outhouse"}, {"complete", 5059, at = {1422, 47.71, 49.87}}, {"turnin", 5059, at = {1422, 48.11, 49.65}, who = "Outhouse"}, {"complete", 5060, at = {1422, 48.1, 49.7}}, {"turnin", 5060, at = {1422, 47.35, 49.63}, who = "Locked Cabinet"}, note = "The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A Wandering Skeleton carries the outhouse key; Farmer Dalson comes out when you open the outhouse and carries the cabinet key.", title = "Dalson's Tears farmhouse"},
	{{"accept", 4984, at = {1422, 53.73, 64.66}, who = "Mulgris Deepriver"}, note = "He camps by the Writhing Haunt, south-east of Dalson's Tears.", title = "Mulgris Deepriver"},
	{{"complete", 4984, at = {1422, 51.09, 64.35}, optional = true}, {"turnin", 5152, at = {1422, 49.17, 78.57}, who = "Marlene Redpath"}, {"accept", 5142, at = {1422, 49.17, 78.57}, who = "Marlene Redpath"}, {"accept", 5153, at = {1422, 49.17, 78.57}, who = "Marlene Redpath"}, {"complete", 5153, at = {1422, 49.7, 76.8}}, {"accept", 5402, at = {1422, 42.97, 83.55}, optional = true, who = "Argent Officer Pureheart"}, {"accept", 5403, at = {1422, 42.97, 83.55}, optional = true, who = "Argent Officer Pureheart"}, {"turnin", 5402, at = {1422, 42.97, 83.55}, optional = true, who = "Argent Officer Pureheart"}, {"turnin", 5403, at = {1422, 42.97, 83.55}, optional = true, who = "Argent Officer Pureheart"}, {"note", "Keep Little Pamela: Pamela is in Darrowshire, visited again later."}, note = "Ride south past the Writhing Haunt to Sorrow Hill; Marlene's house stands by the road, and Joseph Redpath's monument is in the graveyard behind it. Kill the Diseased Wolves you meet in the fields on the way.", title = "Sorrow Hill"},
	{{"turnin", 5153, at = {1422, 39.46, 66.76}, who = "Chromie"}, {"accept", 5154, at = {1422, 39.46, 66.76}, who = "Chromie"}, note = "Ride north-west into Andorhal. Chromie waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges.", title = "Chromie"},
	{{"complete", 5154, at = {1422, 43.4, 69.5}}, note = "The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one.", title = "The Annals of Darrowshire"},
	{{"turnin", 5154, at = {1422, 39.46, 66.76}, who = "Chromie"}, {"accept", 5210, at = {1422, 39.46, 66.76}, who = "Chromie"}, {"note", "Brother Carlin goes to Light's Hope Chapel: keep it for later."}, title = "Chromie"},
	{{"complete", 4984, at = {1422, 44.95, 59.83}}, note = "The wolves roam the fields between Andorhal, Dalson's Tears and the Writhing Haunt. Finish them on the ride back east.", title = "Diseased Wolves"},
	{{"turnin", 4984, at = {1422, 53.73, 64.66}, who = "Mulgris Deepriver"}, {"accept", 4985, at = {1422, 53.73, 64.66}, who = "Mulgris Deepriver"}, title = "Mulgris Deepriver"},
	{{"complete", 4985, at = {1422, 55.16, 64.54}}, note = "The bears roam the hills north and east of the Writhing Haunt.", title = "Diseased Grizzlies"},
	{{"turnin", 4985, at = {1422, 53.73, 64.66}, who = "Mulgris Deepriver"}, {"accept", 4987, at = {1422, 53.73, 64.66}, who = "Mulgris Deepriver"}, {"note", "Keep the branch: Nara Wildmane is in Thunder Bluff."}, title = "Mulgris Deepriver"},
	{{"accept", 5542, at = {1423, 5.16, 35.57}, who = "Tirion Fordring"}, {"accept", 5543, at = {1423, 5.16, 35.57}, who = "Tirion Fordring"}, {"accept", 5544, at = {1423, 5.16, 35.57}, who = "Tirion Fordring"}, {"note", "Tirion's hunts are in the Eastern Plaguelands: keep them for later."}, note = "Ride north along the eastern hills; Tirion lives in a small house by the Thondroril River, at the border with the Eastern Plaguelands.", title = "Tirion Fordring"},
	{{"accept", 6004, at = {1422, 51.92, 28.06}, who = "Kirsta Deepshadow"}, note = "Ride west to the Northridge Lumber Camp; Kirsta hides on the hill north-east of it.", title = "Kirsta Deepshadow"},
	{{"complete", 6004, at = {1422, 51.76, 44.83}}, note = "Knights and magi work the Northridge Lumber Camp; the medics and hunters camp south of it.", title = "Scarlet Crusade"},
	{{"turnin", 6004, at = {1422, 51.92, 28.06}, who = "Kirsta Deepshadow"}, {"accept", 6023, at = {1422, 51.92, 28.06}, who = "Kirsta Deepshadow"}, title = "Kirsta Deepshadow"},
	{{"complete", 6023, at = {1422, 57.83, 36.1}}, note = "Huntsman Radley stands east of the lumber camp; Cavalier Durgen guards the road north-east of Kirsta, toward Hearthglen.", title = "Radley and Durgen"},
	{{"turnin", 6023, at = {1422, 51.92, 28.06}, who = "Kirsta Deepshadow"}, title = "Kirsta Deepshadow"},
	{{"level", 53}, note = "Kirsta's last task needs level 53. The Scarlet Knights and Magi (54-55) working the lumber camp just south-west of her are the closest camp.", title = "Northridge Lumber Camp"},
	{{"accept", 6025, at = {1422, 51.92, 28.06}, who = "Kirsta Deepshadow"}, title = "Kirsta Deepshadow"},
	{{"complete", 6025, at = {1422, 45.5, 18.6}}, note = "Hearthglen's Scarlets are level 58-60. Ride in to the high point marked on your map, look over the town, and get out.", title = "Hearthglen"},
	{{"turnin", 6025, at = {1422, 51.92, 28.06}, who = "Kirsta Deepshadow"}, title = "Kirsta Deepshadow"},
