	{{"note", "Fly to Splintertree Post"}, note = "Ride back to the Undercity, take the zeppelin to Orgrimmar and fly to Splintertree Post. Follow the road west out of Splintertree and take the fork north into Felwood.", title = "To Felwood"},
	{{"accept", 5156, at = {1448, 50.89, 81.62}, who = "Taronn Redfeather"}, {"accept", 5155, at = {1448, 51.21, 82.11}, who = "Greta Mosshoof"}, {"accept", 4102, at = {1448, 46.75, 83.13}, who = "Maybess Riverbreeze"}, note = "The druids' camp is just past the border.", title = "Emerald Sanctuary"},
