	{{"accept", 6022, at = {1423, 22.23, 63.51}, who = "Nathanos Blightcaller"}, {"accept", 6042, at = {1423, 22.23, 63.51}, who = "Nathanos Blightcaller"}, {"accept", 6133, at = {1423, 22.23, 63.51}, who = "Nathanos Blightcaller"}, note = "The Banshee Queen's champion holds the Marris Stead farmhouse.", title = "Nathanos Blightcaller"},
	{{"complete", 5542, at = {1423, 20.8, 60.51}}, {"complete", 5543, at = {1423, 20.13, 56.23}}, {"complete", 5544, at = {1423, 19.13, 61.85}}, note = "Plaguehound Runts and Plaguebats roam the hills north of the Marris Stead, Carrion Grubs crawl among them; work north toward Terrordale.", title = "The western hills"},
	{{"turnin", 5281, at = {1423, 11.36, 26.6}, who = "Egan"}, note = "Egan the ghost stands by a hut in Terrordale, in the north-west corner.", title = "Egan"},
	{{"complete", 6133, at = {1423, 45.27, 12.7}}, {"complete", 6042, at = {1423, 46.31, 41.5}}, note = "The high elf Rangers, Pathstriders and Woodsmen guard the lodge by Northpass Tower; the Registry lies inside. Rangers reach 60: pull one at a time. Noxious Plaguebats fly over the fields on the way.", title = "Quel'Lithien Lodge"},
	{{"complete", 6024, at = {1423, 61.96, 11.11}}, note = "Hameya hides among the Mossflayer trolls of Zul'Mashar, in the north-east corner.", title = "Infiltrator Hameya"},
