	{{"have", 15447, 7, at = {1423, 50.72, 53.51}, name = "Living Rot"}, {"complete", 6022}, note = "Living Rot spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the Mortar and Pestle at once.", title = "Corin's Crossing"},
	{{"turnin", 6022, at = {1423, 22.23, 63.51}, who = "Nathanos Blightcaller"}, {"turnin", 6042, at = {1423, 22.23, 63.51}, who = "Nathanos Blightcaller"}, {"turnin", 6133, at = {1423, 22.23, 63.51}, who = "Nathanos Blightcaller"}, note = "Ride west to the Marris Stead.", title = "Nathanos Blightcaller"},
	{{"turnin", 6024, at = {1423, 23.58, 73.79}, who = "Mound of Dirt"}, note = "The Mound of Dirt is just behind the Undercroft.", title = "Hameya's mound"},
	{{"note", "Hearth to Light's Hope Chapel"}, {"turnin", 5181, at = {1423, 71.7, 50.04}, who = "Carlin Redpath"}, title = "Carlin Redpath"},
