	{{"turnin", 7820, at = {1456, 43.05, 42.72}, who = "Rumstag Proudstrider"}, {"turnin", 7821, at = {1456, 43.05, 42.72}, who = "Rumstag Proudstrider"}, {"turnin", 7822, at = {1456, 43.05, 42.72}, who = "Rumstag Proudstrider"}, note = "On Hunter Rise. Have the Wool, Silk and Mageweave in your bags.", title = "Rumstag Proudstrider"},
	{{"note", "Fly to Bloodvenom Post"}, {"turnin", 4521, at = {1448, 34.73, 52.79}, who = "Trull Failbane"}, {"accept", 4741, at = {1448, 34.73, 52.79}, who = "Trull Failbane"}, title = "Trull Failbane"},
	{{"turnin", 5084, at = {1448, 60.2, 5.84}, optional = true, who = "Deadwood Cauldron"}, {"accept", 5085, at = {1448, 60.2, 5.84}, optional = true, who = "Deadwood Cauldron"}, note = "Only if you found a Winterfall Firewater flask in Winterspring: ride north up the road. The cauldron stands in Felpaw Village, just south-west of Timbermaw Hold; the Deadwood furbolgs there are hostile.", title = "Deadwood Cauldron"},
	{{"turnin", 8471, at = {1448, 65.5, 3.52}, optional = true, who = "Kernda"}, note = "Only if a Winterfall Ritual Totem dropped for you: Kernda waits at the Felwood entrance of Timbermaw Hold, and speaks to you only at Neutral with the Timbermaw.", title = "Kernda"},
	{{"accept", 5527, at = {1450, 51.69, 45.1}, who = "Rabine Saturna"}, {"turnin", 1123, at = {1450, 51.69, 45.1}, who = "Rabine Saturna"}, {"accept", 1124, at = {1450, 51.69, 45.1}, who = "Rabine Saturna"}, {"note", "Both quests lead to Silithus: keep them."}, note = "Go through Timbermaw Hold and take the Moonglade branch of the tunnel. Rabine is in Nighthaven.", title = "Rabine Saturna"},
	{{"turnin", 5085, at = {1452, 31.27, 45.16}, optional = true, who = "Donova Snowden"}, {"accept", 5086, at = {1452, 31.27, 45.16}, optional = true, who = "Donova Snowden"}, {"turnin", 3909, at = {1452, 31.27, 45.16}, who = "Donova Snowden"}, {"accept", 3912, at = {1452, 31.27, 45.16}, who = "Donova Snowden"}, {"note", "Toxic Horrors are in Felwood, on a later trip: keep it if you have it."}, note = "Back through the tunnel and take the Winterspring exit, then ride south to Frostfire Hot Springs.", title = "Donova Snowden"},
	{{"complete", 4741, at = {1452, 58.95, 59.03}}, note = "Ride east to Everlook and north out of it; the Moontouched Owlbeasts roam the hills of Frostsaber Rock's southern slopes. Pull them one at a time.", title = "Moontouched Owlbeasts"},
	{{"note", "Hearth to Thunder Bluff"}, title = "Back to Thunder Bluff"},
	{{"note", "Fly to Gadgetzan"}, {"accept", 2741, at = {1446, 52.39, 26.97}, who = "Egg-O-Matic"}, title = "Gadgetzan"},
	{{"complete", 5163, at = {1446, 51.06, 26.87}}, note = "Use Umi's Mechanical Yeti on Sprinkle, the goblin girl in Gadgetzan. Quixxil and Legacki are scared later in the route.", title = "Sprinkle"},
	{{"turnin", 3912, at = {1446, 53.92, 23.33}, who = "Gaeriyan"}, {"accept", 3913, at = {1446, 53.92, 23.33}, who = "Gaeriyan"}, {"turnin", 3913, at = {1446, 53.81, 29.06}, who = "A Conspicuous Gravestone"}, {"accept", 3914, at = {1446, 53.81, 29.06}, who = "A Conspicuous Gravestone"}, {"note", "Linken's Sword goes back to Linken in Un'Goro: keep it."}, note = "Gaeriyan is a ghost at the graveyard just north of Gadgetzan; the Conspicuous Gravestone is south of it, outside the town wall.", title = "Gaeriyan"},
	{{"turnin", 3444, at = {1446, 52.71, 45.92}, who = "Marvon Rivetseeker"}, note = "Marvon camps by the Lost Rigger Cove road, south of Gadgetzan.", title = "Marvon Rivetseeker"},
	{{"note", "Fly to Camp Mojache"}, {"complete", 2741, at = {1444, 57.1, 76.28}}, note = "Fly to Camp Mojache. The hippogryph nests are in the south of Feralas; each holds an egg for the Egg-O-Matic.", title = "Hippogryph eggs"},
	{{"note", "Fly to Marshal's Refuge"}, note = "Fly to Marshal's Refuge, then ride south-west through Un'Goro to the pass into Silithus. The next guide opens at Valor's Rest, where the pass comes out.", title = "On to Silithus"},
} })

