	{{"complete", 8282, at = {1451, 44.56, 91.38}}, note = "The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away.", title = "Noggle's Lost Satchel"},
