	{{"complete", 5206, at = {1423, 71.68, 35.84}}, note = "Scourge Champions roam the Noxious Glade, north of the chapel. Pass Carlin's Mystic Crystal over each one you kill: the skulls that resonate are the ones he wants.", title = "Scourge Champions"},
	{{"turnin", 5206, at = {1423, 71.7, 50.04}, who = "Carlin Redpath"}, {"accept", 5941, at = {1423, 71.7, 50.04}, who = "Carlin Redpath"}, title = "Light's Hope Chapel"},
	{{"turnin", 5142, at = {1423, 31.15, 77.98}, who = "Pamela Redpath"}, {"complete", 5781, at = {1423, 23.85, 74.22}}, {"note", "Pamela's own errand is not on this route. Skip it."}, note = "Ride to Darrowshire in the south-west; Pamela plays among the houses. Mercutio Filthgorger lurks in the Undercroft, the crypt just west of the town.", title = "Pamela and the Undercroft"},
	{{"turnin", 5961, at = {1423, 22.23, 63.51}, who = "Nathanos Blightcaller"}, {"note", "Nathanos' errands are not on this route. Skip them."}, note = "The Banshee Queen's champion holds the Marris Stead farmhouse, north of the Undercroft.", title = "Nathanos Blightcaller"},
