	{{"complete", 5165, at = {1448, 36.27, 56.3}}, note = "Ride north-west to Jaedenar. The four braziers stand among the Shadow Council's buildings; use the Cleansed Water on each one.", title = "Dousing the Flames of Protection"},
	{{"turnin", 5165, at = {1448, 51.21, 82.11}, who = "Greta Mosshoof"}, {"accept", 5242, at = {1448, 51.21, 82.11}, who = "Greta Mosshoof"}, note = "Back south to the Sanctuary, a short ride.", title = "Greta Mosshoof"},
	{{"complete", 5242, at = {1448, 38.81, 46.87}}, note = "Moora, Salia and Shadow Lord Fel'dan wait at the back of Shadow Hold, the cave in Jaedenar's north. Clear the tunnel as you go.", title = "A Final Blow"},
	{{"turnin", 5242, at = {1448, 51.21, 82.11}, who = "Greta Mosshoof"}, note = "South to the Sanctuary once more.", title = "Greta Mosshoof"},
	{{"turnin", 6605, at = {1448, 34.21, 52.34}, who = "Winna Hazzard"}, {"turnin", 4741, at = {1448, 34.73, 52.79}, who = "Trull Failbane"}, {"note", "Trull's next Wild Guardians would bring you back here from Winterspring. Skip it."}, note = "Ride north along the road, past Jaedenar, to Bloodvenom Post.", title = "Bloodvenom Post"},
